window.__D("text/likkutei-sichot/c185",{"p":[[1300291141,"„לעולם יהא אדם רך כקנה ואל יהא קשה כארז\", אַז אַ מענטש האָט מדות, אָבער ער דאַרף האָבן „ווייכע\" מדות, וואָס דאָס מיינט אַז יעדע מדה גיט אַן אָרט צו דער מדה הפכית (וע\"ד המבואר ברמב\"ם44 אַז „הדרך הישרה היא מדה בינונית שבכל דעה ודעה\")] —\nאון דאָ זאָגט מען אַז דער איסור פון כלאים באַשטייט אין דעם וואָס מ'איז מערבב די מדות פון חסד וגבורה?!\nשטייט אויף דעם דער ביאור45, אַז די התכללות המדות אין קדושה איז ע\"ד ווי „תערובות מין במינו\", ווייל אַלע ענינים פון קדושה — „הכל הוא מין א', הביטול וההכנעה אליו ית'\"46. און דערפאַר גע־פינט מען, אַז אין עבודת ה' קענען זיין ביידע מדות הפכיות דחסד וגבורה צו־זאַמען, ווי עס שטייט אין ספרי עה\"פ ואהבת את ה\"א47 — „אין לך אהבה במקום יראה ויראה במקום אהבה אלא במדת הקב\"ה בלבד\".\nאין עניני העולם, אָבער — וואָס דער גדר פון עולם איז וואָס ער פילט זיך אַ מציאות (ביז אַז מען קען מקיים זיין דורך עם מצוות48 תפילין וכיו\"ב) — איז דער „ציור\" פון יעדער מדה מיט אַ תוקף, און אַזאַ תוקף, וואָס גיט ניט קיין אָרט פאַר אַ צווייטער מדה ובפרט — אַ מדה הפכית, און דעריבער — „אין לך אהבה במקום יראה ויראה במקום אהבה\". ובמילא, אויב ס'איז יע פאַראַן אַ חיבור ועירבוב פון שני הפכים אין עניני העולם, איז עס באופן פון תערובות „מין בשאינו מינו\";\nמשא\"כ אין קדושה — וואָס קדושה איז ענינה ביטול49 צום אויבערשטן — זיינען די מדות הפכיות פון חסד וגבורה ניט בהתנגדות איינע צו דער צווייטער, נאָר אדרבה, זיי זיינען באמת „מין אחד\" — דער תוכן וענין פון ביידע מדות איז איינער און דער זעלבער: עבודת ה'.\n[ע\"ד ווי חז\"ל50 זאָגן אויפן פסוק51 „עושה שלום במרומיו\" — „מיכאל52 שר של מים וגבריאל שר של אש ואין מכבים זה את זה\" — ווייל שטייענדיק לפני מלך מלכי המלכים הקב\"ה פילן זיי ניט דעם אייגענעם תוקף ומציאות, נאָר בלויז דאָס וואָס זיי זיינען שלוחיו של המלך (הקב\"ה) ובמילא איז ניטאָ קיין ניגוד צווישן זיי, ביידע זיינען „מין אחד\" — שלוחי המלך53].\nז. לויט דעם וועט מען פאַרשטיין דעם חילוק צווישן די צוויי סוגים הנ\"ל אין כלאים — כלאי בהמה (וקרקע) און כלאי בגדים:\nבשעת מען איז מחבר ומערבב צוזאַ־מען צוויי דברים הפכים — זיינען דאָ צוויי אפשריות'ן באופן פון תוצאות הפכיות: א) מ'איז מבטל זייערע ציורים הפכיים וסותרים, ווערט צווישן זיי שלום; ב) יעדערער בלייבט בתקפו אויך דאַן ווען מען בריינגט זיי צוזאַמען — ווערט דערפון אַ פלוגתא ומחלוקת.\nאון די צוויי אופנים ווערן אויס־געדריקט אין די צוויי סוגי כלאים:",[["44","44","הל' דעות פ\"א ה\"ד."],["45","45","אוה\"ת נ\"ך שם (אלא דשם קאי לפי הביאור דאיסור כלאים הוא „שעי\"ז מחבר רוח הקדושה עם רוח הטומאה\"). מאמרים שבהערה 13."],["46","46","ל' אוה\"ת שם (ריש ע' קלג)."],["47","47","ואתחנן ו, ה."],["48","48","ראה ד\"ה מי כמוכה הידוע — לאדמו\"ר מהר\"ש (סה\"מ תרכ\"ט ע' קמח)."],["49","49","להעיר מתניא פכ\"ב, ועוד."],["50","50","במדב\"ר פי\"ב, ח (וש\"נ). אגה\"ק סי\"ב."],["51","51","איוב כה, ב."],["52","52","ל' אגה\"ק שם (ובבמדב\"ר שם (ועוד) בשינוי לשון)."],["53","53","ראה גם רש\"י וארא ט, כד: אש . . מים . . ולעשות רצון קונם עשו שלום ביניהם."]]],[1300291142,"ביי כלאי בהמה וכלאי קרקע — וואָס די מטרה אין דעם איז „להוליד מינים זרים משונים בתולדות\"54, מ'וויל פון די צוויי מינים שאַפן אַ נייע מציאות משונה — איז דער חסרון אין דעם „ערבוב\" דערין וואָס דורך דעם ווערן זיי נתבטל אַלס צוויי באַזונדערע מינים (יעדער לויט זיינע תכונות כו'), זיי ווערן היפך רצון הבורא וואָס האָט זיי באַשאַפן אַלס באַזונדערע מינים און געוואָלט אַז זיי זאָלן פאַרבלייבן אין זייערע באַזונדערע גדרים, תפקידים כו'\n[וע\"ד ווי אין דעם ענין פון „עושה שלום במרומיו\" (הנ\"ל) — איז ניט דער פירוש אַז דורך זייער ביטול צום מלך (הקב\"ה) ווערן נתבטל די באַזונדערע תפקידים פון מיכאל וגבריאל (שר של מים און שר של אש) — דאָס וואָלט גע־ווען היפך רצון המלך — נאָר יעדערער בלייבט ביי זיין ענין און פירט דורך תפקידו, אָבער צוזאַמען דערמיט איז „ואין מכבין זה את זה\"]55;\nמשא\"כ ביי כלאי בגדים איז דער חסרון אַ פאַרקערטער: וויבאַלד דער צמר און די פשתים בלייבן במציאותם\n— און (א) די „כחות העליונים\" וואָס אין זיי זיינען דאָך שני הפכים (חסד וגבורה), (ב) עס רעדט זיך וועגן עניני העולם ביי וועלכע ס'איז ניטאָ בגלוי דער ענין הביטול ובמילא איז זייער חיבור אַ תערובת „מין בשאינו מינו\" — ווערט פון זייער חבור וערבוב אַ תוצאה הפכית — אַן ענין פון פירוד ומחלוקת.\nח. ע\"פ כל הנ\"ל קען מען אויך מסביר זיין די דריי חילוקים הנ\"ל (סעיף ב) בנוגע צו מקדש וכו':\nדער טעם אויפן היתר פון כלאים בציצית, און אַזוי אויך בשייכות לעבודת המקדש, איז56 — ווייל אין אַן ענין פון מצוה וקדושה („מדת הקב\"ה\") טוט זיך אויף דורכן עירבוב פון שני הפכים (ניט קיין פירוד ומחלוקת, נאָר אדרבה) שלום ואחדות (כנ\"ל בארוכה).\nבמה דברים אמורים — אין אַזאַ סוג כלאים וואו דער „ערבוב\" פירט צו פירוד ומחלוקת, וואָס דער חסרון איז ניט שייך ביי אַ דבר מצוה וקדושה; אָבער אין אַזאַ סוג כלאים, וואו דער „ערבוב\" איז מבטל דעם „למיניהם\", די סדרי הבריאה, איז קיין נפק\"מ ניט צי עס רעדט זיך וועגן עניני העולם אָדער וועגן אַ דבר מצוה וקדושה — בכל אופן טאָרן ניט בטל ווערן די גבולות וואָס דער אויבערשטער האָט איינגעשטעלט.\nאון דערפאַר איז ביי כלאי בהמה וכלאי קרקע ניטאָ קיין קס\"ד אפילו אַז מען זאָל זיי מתיר זיין במוקדשין.\nדוקא ביי בשר בחלב, וואָס יש מקום לומר אַז עס געהערט צום סוג פון כלאי בגדים (כנ\"ל סעיף ד'), איז דאָ אַ קס\"ד אַז דאָס זאָל זיין מותר במוקדשין (ע\"ד ווי שעטנז בבגדי כהונה).",[["54","54","לשון הבחיי קדושים שם. ועד\"ז בפרשתנו שם, יוד."],["55","55","אין זה סתירה לזה שיש אופני התכללות בקדושה שמתבטלים הציורים הפרטיים (ראה ס' הליקוטים דא\"ח דהצ\"צ ערך התכללות (וש\"נ). ובכ\"מ) — כי זהו מצד פשיטות האוא\"ס (שלמעלה מהשתלשלות), אבל בנוגע לעניני העולם (וס' השתלשלות) הרי רצון הבורא שיהי' „למינהו\" דוקא, קוין חלוקים כו'."],["56","56","מאמרים שבהערה 13. וראה אוה\"ת פרשתנו (ע' תתקסב. ע' תתקעז. כרך ו ע' ב'שנט) — לפי הביאור דכלאים למטה הוא תערובות קדושה עם סט\"א, משא\"כ בשרשן (ומפרש (שם ע' תתקסא ואילך) לשון הבחיי. ע\"ש). וראה זח\"ג שבהערה 39."]]],[1300291143,"אָבער די מסקנא איז, אַז „בית ה' אלקיך לא תבשל גו'\" — ווייל דער גדר פון בשר בחלב איז (כנ\"ל) וואָס מען שאַפט אַ מציאות חדשה, איז עס בדומה צום סוג פון כלאי בהמה, וואָס דער אופן פון תערובות איז אסור אויך במוקדשין57 (כנ\"ל).\nט. עס שטייט אין בחיי58 אַז „באותו הזמן (לעתיד לבוא) . . יהי' איסור בשר בחלב בטל\" (און עד\"ז געפינט מען אַז די מלאכים (ביי אברהם'ן) האָבן געגעסן בשר בחלב<sup data-n=\"59\">59</sup>.\nוע\"פ המבואר לעיל קען מען דאָס מסביר זיין:\nס'האָט זיך גערעדט פריער (סעיף ד') אַז דאָס וואָס בשר בחלב ווערט אַ מציאות חדשה איז נאָר בנוגע זייער גשם וחומר, דאָס רירט אָבער ניט אָן זייערע „כחות\", פנימיות המציאות. דערפון איז פאַרשטאַנדיק, אַז בנוגע די „כחות העליונים\" וואָס אין בשר וחלב (וועלכע זיינען פאַרבונדן מיט זייער פנימיות המציאות) איז די תערובות ע\"ד ווי כלאי בגדים (וואָס יעדער כח פאַר־בלייבט אין זיין מציאות).\nאון דאָס איז דער חילוק צווישן זמן הזה און „אותו הזמן\":\nאין עוה\"ז פון זמן הזה זעט מען נאָר דעם גשם וחומר פון יעדן דבר גשמי. און וויבאַלד אַז בנוגע דעם גשם וחומר הדבר איז פון דעם עירוב בשר בחלב געוואָרן אַ מציאות חדשה, דערפאַר דאַרף אויסקומען אַז ע\"פ דיני התורה (שניתנה למטה אין עוה\"ז, בארץ דוקא, נשמה בגוף) איז דאָס אַ תערובות בדומה צו כלאי בהמה (ובמילא אסור אויך ביי אַ דבר מצוה וכו').\nמשא\"כ לעתיד לבוא, ווען עס וועט מקויים ווערן דער יעוד60 „ונגלה כבוד ה' וראו כל בשר יחדיו כי פי ה' דבר\" — מ'וועט זען61 ווי די אמת'ע מציאות פון שמים וכו' איז (ניט זיין גשם וחומר, נאָר) דער „בדבר ה'\" דורך וועלכן „נעשו\"62 („פי ה' דבר\") וואָס איז מהווה ומחי' ומקיים יעדן נברא63 —",[["57","57","והמבואר במאמרים שבהערה 13 (ובאוה\"ת משפטים שנסמן בשוה\"ג להערה הנ\"ל) דזה שהמלאכים אכלו בשר בחלב אצל אברהם הוא דוגמת היתר כלאים בציצית ובגדי כהונה (שהם בחי' קדושה) — ראה לקמן סעיף ט ובהערה 61."],["58","58","משפטים כג, יט (בסופו). — ולהעיר מענין עתיד חזיר ליטהר והשקו\"ט בזה*."],["59","59","וירא יח, ח. מדרש תהלים ח, ב. וראה תו\"ש וירא שם אות קכג (וש\"נ). *) מרז\"ל בלשון זה הובא: בשל\"ה פ' חיי שרה. מדרש תלפיות ענף חזיר בשם ר' בחיי. ס' הקנה (?). תו\"א וישלח כה, א. לקו\"ת ד\"ה וכל בניך ס\"ג. קהלת יעקב מע' חזיר. בס' הברית ח\"א מ\"כ דרך אמונה פל\"א בשם מדרש תנחומא (כ\"כ בס' נפש חיים). ועוד. — (וראה ג\"כ עשרה מאמרות מאמר חקור דין ח\"ד פי\"ג. אור החיים פ' שמיני). — בלשון: שעתיד הקב\"ה להחזירו לישראל (לנו): בחיי שמיני י\"א, ז' (לנו). שו\"ת הרדב\"ז ח\"ב תתכ\"ח ומגן דוד להרדב\"ז ט' (לישראל). אור יקרות (לישראל להיתרו הראשון) ראש אמנה למהר\"י אברבנאל פי\"ג. ריטב\"א קידושין מט, א. רקנטי פ' שמיני. ישועות משיחו בשם בראשית רבה (כ\"כ בשד\"ח). תורת משה להחת\"ס פ' שמיני. מאו\"א ח, ו (חזיר נק' ק\"ן ולכן במיתוקה עתידה לחזור ותהי' קדושה). כמה פי' במרז\"ל אלו נקבצו בשדי חמד: כללים אות ג' עו'. פאת השדה ג' ז' ואות ח' ח' שיורי הפאה ג' ז'. ואחרי שכל הנ\"ל שקו\"ט במאמר זה — תמוה דעת היפ\"ת ויק\"ר פי\"ג ג' — הובא בס' ערה\"כ לבעהמ\"ס סה\"ד — שמאמר זה לא הי' ולא נברא!"],["60","60","ישעי' מ, ה."],["61","61","וכן גם עתה בעולם המלאכים, שהם „עליונים\" מובדלים מן הגשם."],["62","62","תהלים לג, ו."],["63","63","כמשנ\"ת בארוכה בשער היחוד והאמונה פ\"א ואילך."]]],[1300291144,"וועט עד\"ז זיין בנוגע למציאות של בשר בחלב, אַז מ'וועט זען אין אים זיין אמת'ע מציאות, דעם דבר הוי' און די „כחות העליונים\" שבו — און זיי ווערן דאָך ניט נתבטל דורך דער תערובות, כנ\"ל;\nאון וויבאַלד אַז די גאַנצע וועלט וועט דעמאָלט נזדכך ווערן און ווערן אַן עולם של קדושה64 און אַן עולם קדוש — איז, אדרבה (כנ\"ל): דער עירוב פון (בשר בחלב —) חסד וגבורה אין קדושה איז אַן ענין הכי נעלה, שלום ואחדות65.\n(משיחות ש\"פ משפטים תשל\"ה־ו, תש\"מ)",[["64","64","ראה תניא ספל\"ו."],["65","65","ולכאורה עפ\"ז צ\"ל שגם כלאי בגדים יהי' מותר לעת\"ל. וצ\"ע."]]],[1300291145,"<h3>תצא ב</h3>\nא. די גמרא זאָגט1: „כל הנודר אע\"פ שהוא מקיימו נקרא חוטא, אמר ר' זביד מאי קרא וכי תחדל לנדור לא יהי' בך חטא2, הא לא חדלת איכא חטא\". אויך לערנט מען אָפּ3 פון אַ גזירה שוה „חדלה חדלה\" — „כתיב הכא כי תחדל לנדור4 וכתיב התם5 שם רשעים חדלו רוגז\" — אַז „כל הנודר6 אע\"פ שמקיימו7 נקרא רשע\".\nביידע לימודים ווערן אַראָפּגעבראַכט להלכה אין טושו\"ע8 „כל9 הנודר אע\"פ שמקיימו נקרא רשע ונקרא חוטא\"10\nדער רמב\"ם אָבער א) ברענגט ניט אַראָפּ אין הלכות נדרים די לימודים הנ\"ל11. ב) ברענגט אַראָפּ אַ דריטען מאמר רז\"ל12",[["1","1","נדרים עז, ב."],["2","2","פרשתנו כג, כג."],["3","3","נדרים כב, א."],["4","4","והיינו (ראה דרישה שבהערה 9) דמהפסוק (הנ\"ל) עצמו יודעים שנקרא „חוטא\" (ראה פרש\"י* שם ד\"ה כי תחדל „מכלל דאי נדר . . איכא חטא\". ועד\"ז בר\"ן שם ד\"ה ויליף), ומהגז\"ש ד„חדלה חדלה\" (שהובא בפנים) ילפינן דנקרא (גם) „רשע\". וראה הלשון והסדר בטושו\"ע שנסמן לקמן הערה 8. וראה בהנסמן בהערה 10."],["5","5","איוב ג, טז."],["6","6","כ\"ה גירסת הע\"י. וכ\"ה בהגהות הב\"ח בגמרא שם."],["7","7","להעיר מלשון רש\"י הנ\"ל „דאי נדר ועבד לי'\", היינו — שקיים הנדר. ובפרש\"י שם דף עז (ד\"ה הא לא חדלת) כתב „אלא נדרת\" ותו לא."],["8","8","יו\"ד ר\"ס רג. וראה לבוש שם."],["9","9","כ\"ה הלשון בשו\"ע, ובטור שם מעתיק לשונות הגמרא. וראה דרישה שם סק\"א."],["10","10","ב' הענינים — ראה ט\"ז שם סק\"א דתלוי אם מצא פתח לחרטה או לא. ובקרבן נתנאל לרא\"ש *) וידועה השקו\"ט אם הפירוש דמס' נדרים (גם עד דף כב) הוא מרש\"י — ראה יד מלאכי כללי רש\"י ותוס' כו' אות ו. שם הגדולים להחיד\"א מע' גדולים מערכת רש\"י. שד\"ח (כרך ט) כללי הפוסקים סי' ח אות ד. נדרים פ\"א ס\"ח (אות ב), דהא דנק' רשע הוא בנדרי איסור ש(בדרך כלל) נודר מחמת כעס (משא\"כ בנדרי הקדש, דנק' רק „חוטא\"). וכדבריו משמע לכאורה מפשטות המשך הגמ' שם (כב, א). וכן משמע מרמב\"ם שבהערה הבאה."],["11","11","קושיא גמורה אינה, כי בנוגע לרשע י\"ל דנכלל* במ\"ש בפ\"א הכ\"ה־כו „כנדרי רשעים כו' חייב כו' אסור כו' כנדרי כשרים לא נתחייב בכלום שאין הכשרים נודרים בדרך אסור וכעס\", ובכלל מאתים מנה דמובן שהוא חוטא. אבל עדיין צריך ביאור, דהו\"ל לכתוב ענין זה (דהוי רשע וחוטא) בפני עצמו [וכבש\"ס שם (כב, א) שמבאר שנק' רשע מגז\"ש (וגם דנקרא חוטא — ראה הערה 4), אף שמפורש במשנה (שם ט, א)** „כנדרי רשעים כו' כשרים כו'\" (שהובא ברמב\"ם הנ\"ל), שרק „רשעים\" נודרים (וראה השקו\"ט בגמ' שם (ט, א־ב))] — להדגיש חומר ענין הנדרים, כדי שיהי' אדם נזהר בהם (וע\"ד שמביא בסוף הל' נדרים (מובא לקמן בפנים) דהוי „כאילו בנה במה\")."],["12","12","נדרים כב, א. נט, א. ס, ב. יבמות קט, ריש ע\"ב. וגיטין מו, רע\"ב (וכנסמן במסורת הש\"ס). ברדב\"ז הל' נדרים (וכן בסוף הל' שבועות) ציין המקור לדברי הרמב\"ם „בפרק הנודר מן הירק\"* (והוא בנדרים נט שם), ועד\"ז בצפע\"נ שם: כן מבואר *) ואף שבנוגע לנזירות („שהוא נדר מכלל נדרי איסור\" — רמב\"ם ריש הל' נזירות) כתב הרמב\"ם (סוף הל' נזירות) „האומר הריני נזיר . . ה\"ז רשע ונזירות כזו מנזירות רשעים היא\" — דוחק לומר דסמיך ע\"ז ושלכן אינו מביא בהל' נדרים (שלפנ\"ז) ד„נק' רשע . . חוטא\". **) ומובא בגמרא (שם כב, א) — בהמשך למ\"ש ש„נק' רשע\": אף אנן נמי תנינא כנדרי רשעים כו'. *) אבל בכס\"מ שם: פרק קונם (והוא שם דף ס). ובמגדל עוז שם ציין לב' מקומות הנ\"ל, ומסיים „ומייתי לה בכמה דוכתי\". וראה לקמן הערה 27."]]],[1300291146,"וועגן דעם חסרון פון נודר זיין — בסוף הל' נדרים זאָגט דער רמב\"ם „כל הנודר כאילו בנה במה ואם עבר ונדר מצוה להשאל על נדרו\".\nוצריך ביאור: פאַרוואָס ברענגט ער ניט די לימודים הנ\"ל פון פסוקים, נאָר „כל הנודר כו'\" — אויף וועלכן עס ברענגט זיך ניט קיין פסוק13?\nאויך דאַרף מען פאַרשטיין: דעם ענין, אַז מ'זאָל זיך אָפּהאַלטן פון נודר זיין, זאָגט שוין דער רמב\"ם פריער, אין הל' דעות14, וואו ער רעדט ווי אַזוי ס'דאַרף זיין הנהגת האדם בכלל בנוגע דברים שבעולם — פון וועלכע מ'דאַרף זיך אָפּשיידן און פון וועלכע מ'דאַרף ניט — וז\"ל: „לפיכך צוו חכמים שלא ימנע אדם עצמו אלא מדברים שמנעתו התורה בלבד, ולא יהא אוסר עצמו בנדרים ובשבועות על דברים המותרים. כך אמרו חכמים15 לא דייך מה שאסרה תורה אלא שאתה אוסר עליך דברים אחרים\".\nאיז ניט גלאַטיק: פאַרוואָס ברענגט ער ניט דאָרטן דעם חסרון אין נדרים דמאמרים הנ\"ל, אַז „כל הנודר כו' נקרא חוטא (פושע), כאילו בנה במה\"? — וואָס איז דאָך שטרענגער פון דער טענה לא דייך כו'.\nב. וועט מען דאָס פאַרשטיין בהקדים ביאור דברי הרמב\"ם אין דער הלכה הנ\"ל: „כל הנודר כאילו בנה במה, ואם עבר ונדר מצוה להשאל על נדרו כדי שלא יהא מכשול לפניו\".\nדער מקור פון דער הלכה, איז דער מאמר פון רבי נתן וואָס ווערט געבראַכט כמה פעמים בש\"ס16, און ר\"נ פירט אויס „והמקיימו כאילו הקריב עלי' קרבן\"17. איז ניט מובן: פאַרוואָס ברענגט ניט דער רמב\"ם אויך דעם סיום פון דעם מאמר וואָס ברענגט נאָכמער אַרויס דעם גודל החטא אויב מ'איז ניט שואל אויפן נדר (ובמילא — מקיימו), אַז ווען מ'איז מקיים דעם נדר18 — איז כאילו מ'איז מקריב אַ קרבן אויף דער במה19?\nנאָכמער: אין טור ושו\"ע20 ווערט דאָס",[["","","בנדרים דף נט ע\"א עיי\"ש. ובפשטות כוונתם כי שם דוקא הובא מאמר ר\"נ ע\"ז ד„קונמות מצוה לאיתשולי עליהן משום דר\"נ כו'\" המפורש ברמב\"ם כאן."],["13","13","ברמב\"ם, וגם לא בש\"ס (מקומות שבהערה 12). ולהעיר, שבפרש\"י יבמות (שם ד\"ה כאילו בנה) — על מרז\"ל הנ\"ל „כאילו בנה במה\", כתב „דחוטא הוא דכתיב וכי תחדל לנדור וגו' הא לא תחדל והי' בך חטא\". ובתוד\"ה הנודר (יבמות שם. גיטין שם) הביא, די\"מ דנפקא לן חדלה חדלה (ע\"ש)."],["14","14","פ\"ג ה\"א."],["15","15","ירושלמי נדרים פ\"ט ה\"א (בשינוי ל' קצת)."],["16","16","ראה לעיל הערה 12."],["17","17","כ\"ה בנדרים כב, א (לגירסת הע\"י), יבמות וגיטין שם. ובנדרים נט, א. ס, ב (וכ\"ה בפרש\"י שם כב, א ד\"ה ברישא פתחינן) — „כאילו מקטיר עלי'\"."],["18","18","ראה ר\"ן נדרים (כב, א) ד\"ה והמקיימו „כלומר שאינו נשאל עליו כאילו כו'\". ועד\"ז ברש\"י גיטין שם ד\"ה והמקיימו (וד\"ה שלאח\"ז). וראה גם פרש\"י יבמות שם ד\"ה כאילו הקריב. תוס' רי\"ד גיטין שם. וראה הלשון בטור ובשו\"ע שבהערה 20."],["19","19","ואין לתרץ לפי שהרמב\"ם (בספר היד) אין ענינו להעתיק כל הלשון דמרז\"ל כ\"א רק מה שנוגע להלכה, והנפק\"מ להלכה מדברי ר\"נ ד„המקיימו כאילו הקריב עלי' קרבן\" הוא שצריך להשאל על נדרו (כבנדרים נט שם. וראה מקומות שבהערה שלפנ\"ז), וזה כתב בפירוש כי מכיון שהרמב\"ם מביא התחלת המאמר „כל הנודר כאילו בנה במה\", להדגיש חומר ענין הנדרים בכדי שיהא האדם זהיר מלנדור, הו\"ל להעתיק גם סיום מאמרו, שמביא גם לתוס' זירוז שלא לנדור נוסף על אשר אם עבר ונדר שישאל עליו."],["20","20","יו\"ד סי' רג ס\"ג. וכן הובא בראב\"ד סוף הל' שבועות. סמ\"ג מל\"ת רמב בסופה."]]],[1300291147,"<h3>יע21 אַראָפּגעבראַכט22!</h3>\nדער רדב\"ז23 איז מסביר, אַז דעם המשך המאמר פון ר\"נ, „והמקיימו כאילו הקריב עלי' קרבן\" איז דער רמב\"ם מפרש באופן זה, אַז „אם הוא ירא שמא יבא לידי מכשול ומקיים נדרו ואינו שואל עליו הוי כאילו הקריב עלי' קרבן, אבל אם ברי לו שלא יבא לידי מכשול אם רצה לקיים יקיים\".\nאָבער ס'איז לכאורה ניט גלאַטיק אַזוי צו איינלערנען אין רמב\"ם, א) פון פשטות לשון הרמב\"ם „כל הנודר כאילו בנה במה ואם עבר ונדר מצוה להשאל על נדרו כו'\" איז משמע, אַז כשם ווי די רישא רעדט וועגן יעדן אופן פון נדר („כל הנודר\"), אַזוי איז אויך דער המשך „אם עבר ונדר\", מיינט דאָס בכל אופן, סיי ביי „ירא שמא כו'\" און סיי אויך ביי „ברי לו כו'\"24.\nב) ווי קען זיין ברי לו שלא יבוא לידי מכשול — וויבאַלד אַז אמחז\"ל במשנתם25 „אל תאמין בעצמך\", און זיי האָבן געאַסרט זיך שטעלן בנסיון26.\nג. לכאורה קען מען דאָס פאַרענטפערן ע\"פ דיוק לשון הרמב\"ם „כל הנודר כאילו בנה במה\" — ניט ווי בכמה מקומות בש\"ס27 (ועד\"ז אין שו\"ע<sup data-n=\"28\">28</sup> וואו עס שטייט „הנודר\" סתם — וואָס יש לומר כוונת הרמב\"ם בזה:\nדער רמב\"ם איז ממשיך ומסיים די הלכה, אַז „ואם עבר ונדר מצוה להשאל על נדרו כו' במה דברים אמורים בנדרי איסר אבל נדרי הקדש מצוה לקיימן כו'\". פון דעם וואָס דער רמב\"ם מאַכט אַ",[["21","21","ההוספה בטושו\"ע „הנודר כאילו בנה (בונה) במה בשעת איסור הבמות\" הוא (בלשון הב\"ח שם) „לפי שהרא\"ש (נדרים כב) פירש כאילו בנה במה בשעת איסור הבמות (לכן כתב רבי' כו')\". וכ\"ה ברש\"י יבמות וגיטין שם; ר\"ן נדרים שם (ראה ב\"י וב\"ח לטור שם). וי\"ל (וראה ב\"ח שם) שמביאו — כדי לשלול הפירוש (רש\"י נדרים כב, א) כאילו בנה במה „לעבודת כוכבים\"*. וברמב\"ם י\"ל דלא פירשו, כי מעתיק דברי התלמוד כצורתם וכלשונם (וראה יד מלאכי כללי הרמב\"ם אות ה). ולהעיר שהרמב\"ם מקדים אמרו חכמים."],["22","22","עוד שינוי בין הרמב\"ם וטושו\"ע: ברמב\"ם באה ההלכה ד„כל הנודר כאילו בנה במה\" בסוף הל' נדרים, ובטושו\"ע — בתחלת הל' נדרים. ויש לומר ע\"פ המבואר כמ\"פ החילוק בין הרמב\"ם והשו\"ע (ראה לקו\"ש חט\"ז ע' 374. ועוד), דהשו\"ע ענינו בכדי שהאדם ידע את המעשה, ולכן מתחיל בחומר ואזהרת הנדרים, שנוגע למעשה בפועל שאינו רצוי להדיר (ואיזה נדרים משובחים — ראה לקמן שוה\"ג להערה 30). ורק אח\"כ באו פרטי הלכות נדרים: משא\"כ ספר היד להרמב\"ם הוא כמ\"ש בהקדמתו „חיבור זה מקבץ לתורה שבע\"פ כולה . . שאדם קורא בתורה שבכתב תחלה ואח\"כ קורא בזה ויודע ממנו תורה שבע\"פ כולה כו'\", היינו לימוד וידיעת הדינים. ולכן כתב הסדר כמו שהוא בידיעת הדינים, שמתחיל בהגדרת ענין הנדרים, פרטי הדינים דנדרים, ולבסוף ההלכות — מוסיף בנוגע למעשה, מתי לנדור או שאין לידור כלל וכו' (ועד\"ז הוא בסוף כל הלכה שבספר הפלאה. וכ\"ה בכ\"מ ברמב\"ם)."],["23","23","סוף הל' שבועות. וראה גם מגדל עוז שם. *) ולהעיר מרש\"י סוטה ד, סע\"ב (ד\"ה במה) — וראה תוס' שבהערה 13 — זהר חדש רות צ, סע\"ד."],["24","24","אלא שי\"ל, דלא קאי על זה שנודר „כדי לכונן דיעותיו ולתקן מעשיו כו'\" (שבסוף הל' נדרים שם הכ\"ג), שעליו כתב (שם) „הרי זה זריז ומשובח\", אלא „שלא ירבה (אדם) בנדרי איסור ולא ירגיל עצמו בהם\". ואח\"כ מוסיף „כל הנודר\" — היינו שאר כל הנודרים (שלא באופן הנ\"ל). אבל דוחק הוא. וראה לח\"מ סוף הל' ערכין. וראה לקמן הערה 30."],["25","25","אבות פ\"ב מ\"ד."],["26","26","סנהדרין קז, רע\"א. ובכל יום מבקשים (בברכת השחר) אל תביאני לידי נסיון (ברכות ס, ב)."],["27","27","נדרים כב שם. יבמות וגיטין שם. אבל בב' המקומות האחרים בנדרים שם „כל הנודר\"."],["28","28","ובטור הובא מאמר ר\"נ בתוספת „כל\". ולהעיר מב\"י שם שהביא המאמר „מפ\"ג דנדרים\" והעתיק תיבת „כל\"."]]],[1300291148,"חילוק צווישן נדרי איסור און נדרי הקדש נאָר ביים צווייטן פאַל פון „ואם עבר ונדר\", וואָס ביי נדרי איסור איז „מצוה להשאל על נדרו\" און „נדרי הקדש מצוה לקיימן ולא ישאל עליהן אלא מדוחק\" — און ניט בנוגע דעם ערשטן פאַל פון „כל הנודר\" (מלכתחילה) — איז מוכח, אַז דער ערשטער ענין (פון „כל הנודר כאילו בנה במה\") איז ניט בלויז ביי „נדרי איסר\" נאָר אויך ביי „נדרי הקדש\".\n[און אַזוי שטייט בפירוש אין פרישה29, אַז מאמר רבי נתן רעדט אפילו וועגן נדרי צדקה, ווייל „אף ע\"ג שמצוה הוא ליתן צדקה מ\"מ כשהוא נודר ומחייב את עצמו בנדר נראה כאילו הוא מוסיף על מצות הש\"י כאילו אין הש\"י השלים חוקיו במה שציוה אותנו\"].\nאון דערפאַר איז דער רמב\"ם מדייק „כל הנודר\" — צו כולל זיין אויך נדרי הקדש30.\nלויט דעם איז אויך פאַרענטפערט וואָס דער רמב\"ם ברענגט ניט דעם המשך פון מאמר ר\"נ „והמקיימו כאילו הקריב עלי' קרבן\": היות אַז „כל הנודר כאילו בנה במה\" מיינט אויך נדרי הקדש — איז אויב דער רמב\"ם וואָלט ממשיך געווען „והמקיימו כאילו הקריב עלי' קרבן\", וואָלט עס דאָך געווען בסתירה צום המשך אין רמב\"ם „במה דברים אמורים בנדרי איסר אבל נדרי הקדש מצוה לקיימן ולא ישאל עליהן אלא מדוחק שנאמר נדרי לה' אשלם\". וויבאַלד אַז דער קיום הנדר איז „כאילו הקריב עלי' קרבן\" — ווי קען מען זאָגן בנוגע לנדרי הקדש „מצוה לקיימן\"?!\n[ועפ\"ז איז אויך מתורץ וואָס דער רמב\"ם ברענגט ניט אַראָפּ „כל הנודר כאילו בנה במה\" אין הל' דעות, וואָרום דאָרטן רעדט ער וועגן פרישות פון עניני העולם ונדרי איסור; אָבער וועגן נדרי הקדש — רעדט ער ניט דאָרטן].\nעס בלייבט אָבער ניט מובן: וויבאַלד אַז אויך נדרי הקדש זיינען „כאילו בנה במה\" — פאַרוואָס זאָגט תורה אַז מען זאָל איבערלאָזן דעם „מכשול לפניו\" (די",[["29","29","לטור יו\"ד שם סק\"ז. ודוחק גדול לומר שכתב כן רק בנוגע לצדקה ולא בנוגע לשאר נדרי הקדש. וראה שם סק\"ח וסקי\"א. ולהעיר מאגודה (הובא בברכ\"י לשו\"ע יו\"ד שם ס\"ה): הנודר אע\"פ שמקיימו נקרא רשע יש מפרשים אפילו בנודר בעת צרה דהא על כל הנדרים מייתי לה. וראה טושו\"ע יו\"ד שם ס\"ד בנוגע לצדקה."],["30","30","דאף שבא בהמשך לב' הלכות שלפנ\"ז שמדובר בנדרי איסור, הרי מזה שהתחיל זה בהלכה בפ\"ע משמע שכולל הכל. ואף שכתב (הל' ערכין וחרמין פ\"ח הי\"ב) „שההקדשות וחרמין והערכין מצות וראוי לו לאדם להנהיג עצמו בדברים אלו כדי לכוף יצרו ולא יהי' כילי כו'\", הרי מסיים שם „אעפ\"כ אם לא הקדיש ולא העריך ולא החרים מעולם אין בכך כלום הרי התורה העידה ואמרה כו' לא יהי' בך חטא\". והיינו לאדם שמרגיש בעצמו כילי כו', גם עליו אומרים שאם לא הקדיש כו' אין בכך כלום. אבל לאדם שאינו כילי ואינו צריך לנדור להקדש כדי לכוף יצרו — עליו אומרים „כל הנודר כאילו בנה במה\" (וראה לח\"מ שם). והרי גם בנדרי איסור כתב הרמב\"ם (הל' נדרים שם הכ\"ג — הובא בלח\"מ הנ\"ל) ד„מי שנדר נדרים כדי לכונן דעותיו ולתקן מעשיו הרי זה זריז ומשובח\", ואעפ\"כ ממשיך בהכ\"ד ואילך ש„לא ירבה אדם בנדרי איסור כו' כל הנודר כאילו בנה במה כו'\".* וראה לעיל הערה 24. *) משא\"כ בטושו\"ע שם שהתחלת הסימן היא בהחסרון ושלא ינדור, ואח\"כ בא (בס\"ג) אבל נדרי הקדש מצוה לקיימן כו'. ולבסוף (ס\"ז) מי שנדר נדרים כדי לכונן דעתו כו' (שברמב\"ם הכ\"ג־כד) — נדר הרצוי. ולהעיר שהכותרת להסי' בשו\"ע: איזה דברים משובחים (ואח\"כ) ואיזה הם מגונים."]]],[1300291149,"„במה\"), און ניט אים מבטל זיין, דורך שואל זיין על נדרו (ווי ביי נדרי איסור30*)?\nד. ויש לבאר בכל זה:\nבהקדם — דעם ענין פון „כאילו בנה במה\" זאָגט דער רמב\"ם — און אַזוי שטייט אין גמרא — נאָר לגבי נדרים („כל הנודר\"), אָבער ניט לגבי שבועות [אע\"פ אַז בכ\"מ אין הל' נדרים ברענגט דער רמב\"ם זיי צוזאַמען31, „הנודר או הנשבע כו'\". נאָכמער: אין הל' דעות, וואו דער רמב\"ם רעדט (כנ\"ל) וועגן דעם חסרון פון אסר'ן אויף זיך דברים המותרים, איז ער כולל נדרים ושבועות צוזאַמען].\nאון ווי ס'איז מוכח אין סוף הל' שבועות, וואו דער רמב\"ם זאָגט: „וטובה גדולה היא לאדם שלא ישבע כלל\" און ער איז ממשיך „ואם עבר ונשבע (ע\"ד לשונו גבי נדר בסוף הל' נדרים: ואם עבר ונדר) שיצטער כו'\". און ער זאָגט ניט אויף דעם „כאילו בנה במה\".\nדער ראָגאַטשאָווער32 איז דאָס מבאר: „דגבי שבועה דהוא איסור גברא ולא חל האיסור על שום דבר לא שייך לומר כאילו בנה במה33 דהאיסור הוא השבועה ולא דבר אחר\".\nדי הסברה בזה:\nאין דעם טעם הדבר, פאַרוואָס מ'זאָגט אַז דער וואָס טוט אַ נדר איז „כאילו בנה במה\", זאָגט דער ר\"ן34: „נראה בעיני דלהכי מדמינן לה לבונה במה משום דסליק אדעתי' דנודר דמצוה קא עביד, דרחמנא אסרי' במילי דאיסורא ואיהו נמי אסר אנפשי'\". און אויף דעם זאָגט מען „דטעי, דאדרבה לבונה במה דמי דנהי דרחמנא אזהרי' לאקרובי קרבנות בפנים, אזהרי' דלא לוסיף עלי' לבנות במה ולהקריב בחוץ, ה\"נ נהי דרחמנא אסר עלי' דברים האסורים כי מוסיף איהו אמאי דאסר רחמנא פשע, כענין שאמרו בירושלמי בפרק פותחין35 לא דייך במה שאסרה תורה אלא שאתה אוסר עליך דברים אחרים\".\nדעם צושטעל קען מען טייטשן אויף צוויי אופנים — אין וואָס עס באַשטייט דער חסרון וחטא הנודר: א) אין פעולת הגברא, וואָס ער אסר'ט ענינים וואָס די תורה האָט זיי ניט גע'אסר'ט. ב) אין דער חפצא, אין דעם וואָס דורך זיין נדר איז געוואָרן אַ חפצא של איסור, וואָס די תורה האָט ניט גע'אסר'ט.\n[בסגנון אחר קצת: צי דער איסור איז מצד הפועל והפעולה, אָדער מצד הנפעל].\nאון אויך ביי נדרים ליתן צדקה, ובכלל נדרי הקדש — אע\"פ אַז דאָרט ווערט ניט קיין חפצא של איסור, קען מען לערנען דעם חסרון (בהמשך לדברי הפרישה36 הנ\"ל ס\"ג) אויף צוויי אופנים (ע\"ד הנ\"ל ביי נדרי איסור): א) אַז דאָס",[["","","30*) ראה תוס' רי\"ד נדרים (ס, ב) שע\"י השאלה עוקר (גם) נדר שנתקיים „שלא יתחשב כמקריב קרבן בבמה בשעת איסור הבמות והאיסור שנהג נמצא שנהג בו בלא נדר\". וראה גם צפע\"נ לרמב\"ם סוף הל' נדרים."],["31","31","ראה שם פ\"א ה\"ד (לגבי המצוה לקיים). וראה פ\"ד הי\"א. פ\"ה הי\"ד־טז, וכו\"כ פעמים בפרקים שלאח\"ז."],["32","32","צפע\"נ סוף הל' שבועות."],["33","33","להעיר גם מחדא\"ג מהרש\"א יבמות שם סד\"ה בהפרת נדרים."],["34","34","נדרים כב שם (הובא במפרשי הטור שם). וראה עד\"ז תוס' רי\"ד גיטין שם."],["35","35","נסמן בהערה 15."],["36","36","שבא לבאר דברי הר\"ן הנ\"ל בפנים."]]],[1300291150,"איז מצד דעם עצם נדר — מעשה הגברא, וואָס ער איז מוסיף על מצות השי\"ת (ער איז זיך מחייב בצדקה וכיו\"ב) וואָס דער אויבערשטער האָט אים ניט מחייב געווען; ב) דאָס איז מצד הנפעל — ס'איז געוואָרן אַ נייע חלות חיוב פון צדקה (וכיו\"ב) על נכסיו (ע\"ד הנ\"ל בנדרי איסור, אַז ער האָט אויפגעמאַכט אַ חפצא).\nה. עפ\"ז יומתק דיוק הלשון (הש\"ס והרמב\"ם) „כאילו בנה במה\" — ניט ווי אין שו\"ע, וואו דער לשון איז „כאילו בונה במה\"37 שיש לפרשו:\n„כאילו בונה במה\", איז מדגיש דעם חסרון אין גברא שעוסק בבני' בלתי רצוי' (וואָס קען אים ברענגען38 צום איסור הקרבה בבמה<sup data-n=\"39\">39</sup>;\nדער רמב\"ם זאָגט אָבער אַז דאָס איז „כאילו בנה (ונעשית מציאות — חפצא —) במה\" ער האָט אויפגעמאַכט אַ חפצא (וואָס איז אַ הכשר38 צו אַ הקרבה) אסורה.\nלויט דעם איז אויך מדויק לשון הרמב\"ם „ואם עבר ונדר מצוה להשאל על נדרו כדי שלא יהא מכשול לפניו\". דלכאורה: לויט דעם פירוש הרדב\"ז (הנ\"ל ס\"ב)40, אַז דער מכשול איז וואָס ער וועט עובר זיין על נדרו, האָט דער רמב\"ם געדאַרפט זאָגן „כדי שלא יבוא לידי מכשול\"41, אָדער (ע\"ד לשון הגמרא<sup data-n=\"42\">42</sup> „כדי שלא יבוא לידי תקלה\", וכיו\"ב.\nנאָר דערמיט איז דער רמב\"ם מדגיש, אַז דאָס איז (ניט מצד הגברא, אַז ער וועט קומען לידי תקלה ומכשול, נאָר אַ) התהוות של חפצא, פון אַ („שלא) יהא מכשול לפניו\"; עס43 ווערט אַ מכשול לפניו — די חפצא האסור וואָס ער האָט אויפגעמאַכט על ידי נדרו.\nאון דער טעם וואָס דער רמב\"ם לערנט אַזוי — איז מצד דעם גופא וואָס די גמרא זאָגט דאָס („כאילו בנה במה\") נאָר בנוגע לנדר, און ניט בנוגע לשבועה: אויב מצד דער מעשה הגברא, איז דאָך עד\"ז אויך בנוגע שבועה.\nו. לויט דעם איז אויך מובן דער חילוק צווישן דברי הרמב\"ם אין הל' דעות און אין הל' נדרים:\nאין הל' דעות רעדט דער רמב\"ם",[["37","37","ובפרישה לטור שם סק\"ז נעתק הלשון „כאילו בונה במה\". אבל צ\"ע אם אפשר לדייק בזה בדפוסים."],["38","38","ראה חדא\"ג מהרש\"א יבמות שם ד\"ה הנ\"ל בתחלתו (אבל הוא כתב זה כעוד ביאור על ההשוואה „כאילו בונה במה\", ולא כדברי הר\"ן). וראה הערה הבאה. וראה לקמן ס\"ז."],["39","39","ראה פרש\"י גיטין שם ד\"ה כאילו הקריב „וגמר עונו שלם\". אבל בפרש\"י יבמות שם ד\"ה כאילו הקריב קרבן — „שעבר עליו שתי עבירות\". וראה ר\"ן נדרים (כב שם) ד\"ה ברישא „כאילו בנה במה כו' שאין העבירה גדולה כ\"כ כו'\" (וראה תוס' רי\"ד גיטין שם). ובמאירי נדרים שם „הואיל ואינו איסור גדול\". ולהלן שם במאירי „שהנדרים כל שאינו רואה לעצמו צורך בהם יש בהם סרך עבירה\". וראה ר\"ן (ס, ב) ד\"ה כמאן „כיון דכי נדר לאו שפיר עבד כדר' נתן\". ובפרש\"י שם ד\"ה כרבי נתן „הואיל ועבד איסורא כו'\". ואכ\"מ."],["40","40","וכן משמע במגדל עוז שנסמן לעיל שם. וכן מובן בשו\"ת מהרי\"ק שורש נב. סמ\"ג שם. ועוד."],["41","41","ע\"ד הלשון בסמ\"ג שם: פן יבא לידי מכשול."],["42","42","נדרים ט, ריש ע\"ב; י, רע\"א — אבל שם אינו לענין נדרי איסור."],["43","43","ראה פרישה שם „לפי הירושלמי הנודר אינו עושה איסור מצד עצמו רק משום דלמא לא יוכל לקיימו אבל רבי נתן סבר שעושה איסור מצד עצמו כו'\". אבל לפי ביאורו (בנוגע לצדקה) אפ\"ל שזה בעיקר מצד פעולת הגברא (כנ\"ל בפנים ס\"ד), משא\"כ בהמבואר בפנים שהוא מצד החפצא „מכשול לפניו\"."]]],[1300291151,"וועגן דעם (פעולות ה)גברא, וואָס איז כולל כמה ענינים: אָנהויבנדיק פון דער הנהגה כללית של פרישה מדרכי העולם באופן אַז „לא יאכל בשר ולא ישתה יין ולא ישא אשה כו' וכיוצא בהן\", וואָס „דרך רעה היא ואסור לילך בה. המהלך בדרך זו נקרא חוטא שהרי הוא אומר בנזיר כו'\"; און עד\"ז בענינים פרטיים „שלא ימנע אדם עצמו אלא מדברים שמנעתו התורה בלבד\" כנ\"ל, וואָס אין דעם זיינען נדרים ושבועות בשוה (ווי דער רמב\"ם איז דאָרטן ממשיך), וואָרום אין דער פרישות הגברא פון „דברים המותרים\" — איז קיין נפק\"מ ניט באיזה אופן דאָס ווערט געטאָן44:\nמשא\"כ אין הל' נדרים רעדט דער רמב\"ם וועגן דעם חסרון מצד דער חפצא, וואָס ער האָט אויפגעמאַכט אַ דבר איסור. דערפאַר זאָגט ער דוקא דאָרטן אַז „כאילו בנה במה\" און ניט ביי שבועות כנ\"ל.\nאון דאָס איז אויך דער טעם וואָס דער רמב\"ם ברענגט דאָ ניט „כל הנודר אע\"פ שמקיימו נקרא חוטא\" אָדער „נקרא רשע\", וואָרום אין הל' נדרים רעדט דער רמב\"ם נאָר וועגן דעם חידוש וענין מיוחד ביי נדרים — והיינו וואָס דער נודר מאַכט אויף אַ חפצא של איסור (און דערפאַר „כל הנודר כאילו בנה במה\" כנ\"ל), משא\"כ דאָס וואָס „נקרא רשע\" און „נקרא חוטא\", שם ותואר הגברא, וואָס איז ניט קיין ענין מיוחד ביי נדרים, וע\"ד ווי די גמרא45 זאָגט אַז „כל היושב בתענית נקרא חוטא\".\nאון תוכן ענין זה (דעם חטא ביי נדרים מצד הגברא) ברענגט טאַקע דער רמב\"ם אין הל' דעות, אַז „המהלך בדרך זו (ער איז זיך פורש פון עניני העולם) נקרא חוטא\", און בהמשך לזה: „לפיכך צוו חכמים כו' ולא יהא אוסר עצמו בנדרים ובשבועות על דברים המותרים כו' (ובכלל הזה אלו שמתענים תמיד כו' ואסרו חכמים שיהא אדם מסגף עצמו בתענית<sup data-n=\"46\">46</sup>\".\nז. ע\"פ כל זה וועט מען אויך פאַרשטיין דעם חילוק צווישן נדרי איסור און נדרי הקדש:\nביי נדרי איסור, איז דורך זיין נדר געוואָרן אַ חפצא של איסור, ובמילא האָט ער געמאַכט אַ חפצא, אַ „מכשול לפניו\". און דעריבער איז „מצוה להשאל על נדרו כדי שלא יהא מכשול לפניו\";\nמשא\"כ ביי נדרי הקדש, האָט זיין נדר געשאַפן (ניט אַ חפצא של איסור, נאָר אדרבה) אַ חלות חיוב של צדקה (וכיו\"ב בשאר הקדשות); און דעריבער איז די חפצא ניט אַן ענין פון „מכשול לפניו\" — אדרבה, ס'איז אַ חפצא של מצוה, „מצוה לקיימן\".\nאון דאָס איז אויך דער דיוק אין דעם צושטעל צו „כאילו בנה במה\": בנין במה אויב ער בויט עס מלכתחילה ניט צוליב אַ פעולה אסורה — איז ניט קיין איסור47.",[["44","44","וגם אם פורש עצמו (סתם) גם לא ע\"י נדר ושבועה, ובכלל זה היושב בתענית — ראה רמב\"ם שם (הובא לקמן בפנים בסוף הסעיף)."],["45","45","נדרים י, א. וכ\"ה בתענית יא, א."],["46","46","וראה לח\"מ שם."],["47","47","ראה רמב\"ם הל' בית הבחירה (פ\"א ה\"ג) „כיון שנבנה המקדש בירושלים נאסרו כל המקומות כולן לבנות בהן בית לה' ולהקריב בהן קרבן\", דאסור גם לבנות בית לה' במקום אחר, לא רק איסור הקרבה בבמות (ראה לקו\"ש חט\"ז ע' 466 הערה 12), אבל עכ\"פ צ\"ל בית לה'. ואכ\"מ."]]],[1300291152,"ס'איז נאָר אַ הכשר48 צו פעולות בבמה וועלכע קענען זיין אַן איסור (הקרבת קרבן) אָדער אַ מצוה (מקום כבוד לאביו ורבו, קריאה בתורה, אמירת דברי התעוררות ממקום „גבוה\" — כלשון הכתוב49: על הר גבוה עלי לך וגו' הרימי בכח קולך גו', וכיו\"ב) או דבר הרשות וסתם.\nאון דעריבער ברענגט דאָ ניט דער רמב\"ם דעם פסוק מפורש50 „מוצא שפתיך תשמור ועשית כאשר נדרת\", אַז ס'איז אַ מ\"ע מן התורה ער זאָל מקיים זיין נדרו, ווי דער רמב\"ם זאָגט פריער51, נאָר וויבאַלד ס'איז „נדרי לה'\"52, דאָס איז (ניט זיין אייגענער איסור וחיוב, נאָר דאָס איז) געוואָרן אַן ענין לה'53, דעריבער איז — „אשלם\".\nח. בנוגע ענין שהזמ\"ג, ז' דנחמתא — דער שבועה54 פון דעם אויבערשטן אויף אַריינברענגען אידן אין ארץ ישראל, און בכלל אויף דער גאולה55, איז דאָס אַן ענין וואָס דער אויבערשטער האָט מבטיח געווען, און נאָכמער — זיך געבונדן כביכול מיט אַ שבועה, און נאָכמער: דורך דעם האָט זיך דאָס אויפגעטאָן אין דער חפצא דהעולם — וויבאַלד דיבורו של הקב\"ה חשיב מעשה, איז — מצד דער מציאות פון וועלט „מאָנט זיך\" אַז אידן זאָלן אַריינגיין אין ארץ ישראל, און אַז עס זאָל קומען די גאולה האמיתית והשלימה ע\"י משיח צדקנו.\nאון דעריבער, ווי נאָר אידן וועלן תשובה טאָן איז „מיד הן נגאלין\"56, און עס איז ניט שייך קיינע מניעות ועיכובים ח\"ו מצד עפּעס אין וועלט, דאדרבה — וועלט גופא מאָנט אַז עס זאָל קומען די גאולה, און קומען במהרה בימינו ממש.\n(ע\"פ שיחת כ\"א מנ\"א תשד\"מ)",[["48","48","ראה לעיל הערה 38־39."],["49","49","ישעי' מ, ט."],["50","50","פרשתנו כג, כד."],["51","51","הל' נדרים פ\"א ה\"ד. ולהעיר דשם כולל נדרי איסור עם נדרי הקדש (וראה רדב\"ז שם). ועד\"ז בסהמ\"צ מ\"ע צד (וראה רמב\"ן בסהמ\"צ שם). וראה מפרשי סהמ\"צ שם. צפע\"נ להרמב\"ם סוף הל' נדרים [ובהכותרת להל' נדרים לא חילק וכתב (מצוה א) „שישמור מוצא שפתיו ויעשה כמו שנדר\"]. אבל במנין המצות שבריש ספר היד מ\"ע צד כתב המצוה רק בנדרי הקדש „לקיים אדם כל מה שיוציא בשפתיו מקרבן או צדקה וכיוצא בהם\", ומביא (רק) הכתוב „מוצא שפתיך תשמור ועשית\". ומדברי הרדב\"ז הנ\"ל מובן, שלכן גם ביד הביא ב' הפסוקים. ואכ\"מ."],["52","52","משא\"כ נדרי איסור גם כשנודר „לכונן דעותיו ולתקן מעשיו\" שאז הרי זה „זריז ומשובח\" — הרי „דרך עבודה לשם הו'\" (רמב\"ם הל' נדרים פי\"ג הכ\"ג) ולא „נדר לה'\"."],["53","53","ראה כס\"מ כאן: דברי טעם הם דלמה יגרע כח ההקדש להשאל עליו כו'. די\"ל שכוונתו כנ\"ל (בפנים)."],["54","54","להעיר מפרש\"י עה\"ת ואתחנן בתחלתו ד\"ה בעת ההיא „שמא הותר הנדר\", ובחוקת כ, יב בסופו ד\"ה לכן לא תביאו פי' „בשבועה\"."],["55","55","ראה לקו\"ש חכ\"ה ע' 274 ובהערה שם."],["56","56","רמב\"ם הל' תשובה פ\"ז ה\"ה."]]],[1300291153,"<h3>תצא ג</h3>\nא. בנוגע דעם ציווי1 „ביומו תתן שכרו ולא תבוא עליו השמש גו׳“ — איז ידוע די שאלה:\nחז״ל זאָגן2 אַז דער אויבערשטער איז „מקיים“ דאָס וואָס „הוא אומר לישראל לעשות ולשמור“. ובעניננו — מיר געפינען בכמה מקומות בחז״ל3, אַז די עבודה פון אידן בקיום התומ״צ ווערט צוגעגליכן צו דער עבודה פון אַ פועל פאַר זיין בעה״ב, און שכר מצות איז דער „תשלום“ וואָס דער אויבערשטער (דער „בעל הבית“) צאָלט די אידן (די „פועלים“) פאַר זייער „אַרבעט“.\nדאַרף לפ״ז אויסקומען, אַז יעדער מאָל ווען אַ איד פאַרענדיקט טאָן אַ מצוה, זאָל ער באַלד („ביומו“) באַקומען דעם שכר פאַר זיין „אַרבעט“ — כציווי השם בתורתו „ביומו תתן שכרו ולא תבוא עליו השמש גו׳“ (און „לא4 תלין פעולת שכיר אתך עד בקר“)5.\nפאַרוואָס געפינט מען6, אַז דער אויבערשטער צאָלט שכר מצות (ניט גלייך, נאָר) ערשט „למחר (לעולם הבא<sup data-n=\"7\">7</sup>“, כמאמר חז״ל8 „היום לעשותם, למחר לקבל (ליטול<sup data-n=\"9\">9</sup> שכרם“, אַז10 דער אויבערשטער איז „מאחר“ שכרם (פון צדיקים גמורים אפילו) ביז „למחר“11?!\nב. מפרשים12 פאַרענטפערן, אַז וויבאַלד „כל ימינו אנו משועבדים להקב״ה לעבודתו“ (וואָרום יעדער רגע פון חיי האדם איז ער מחוייב „לשמש את קונו“<sup data-n=\"13\">13</sup>, קומט אויס, אַז דער גאַנצער לעבן פון אַ מענטשן איז איין זמן של שכירות — יעדן אידן איז צוגעטיילט געוואָרן איין „שליחות“ און תפקיד וואָס ער דאַרף דורכפירן במשך חיים חיותו בעלמא דין, און יעדע פעולה שלו בתומ״צ איז אַ פרט פון זיין שליחות ותפקיד:\nדערפאַר איז ניטאָ קיין חיוב צו צאָלן אַ אידן שכר מצות ביז לאחרי פטירתו",[["1","1","פרשתנו כד, טו."],["2","2","שמו״ר פ״ל, ט. ירושלמי ר״ה פ״א ה״ג. וראה ויק״ר פל״ה, ג. ועוד."],["3","3","ראה אבות פ״ב מי״ד־טז. תו״כ (ורש״י) בחוקותי כו, ט. ועוד. — וראה בארוכה „הדרן“ על מס׳ אבות (נדפס בלקו״ש חי״ז ע׳ 387 ואילך. „ביאורים לפרקי אבות“ בסופו)."],["4","4","קדושים יט, יג. וראה פרש״י עה״פ."],["5","5","ואע״פ שאם התנה עם הפועל ע״מ שלא יתחייב לפורעו בזמנו תנאו קיים (שו״ע אדה״ז חו״מ הל׳ שאלה ושכירות כו׳ סי״ח) — הרי (א) אם יוכל לפרוע בזמנו טוב לפרעו ולא לסמוך על התנאי (שו״ע שם). (ב) ועוד ועיקר: איך מתאים לומר שהקב״ה התנה שלא כהוראתו בתורתו „ביומו תתן שכרו“ — והרי „מה שהוא עושה הוא אומר לישראל לעשות“ (כנ״ל בפנים)."],["6","6","להעיר מדב״ר (פי״א, י) אמר משה כו׳ אתה עושה תורתך פלסתר דכתיב ביומו תתן שכרו . . זו היא שילום עבודה של מ׳ שנה שעמלתי כו׳."],["7","7","תנחומא בראשית א. רש״י ס״פ ואתחנן."],["8","8","עירובין כב, א. ע״ז (ג, א. ד, ב)."],["9","9","כ״ה בע״י עירובין שם (ועד״ז בע״ז ותנחומא שם: ולא היום ליטול שכרו). רש״י ס״פ ואתחנן. ועוד. — נת׳ לעיל ע׳ 44 ואילך."],["10","10","עירובין שם."],["11","11","אף שישנם עניני שכר גם בעוה״ז (ככל יעודי התורה (ראה לקמן סעיף ד ואילך). וראה משנה ריש פאה. ועוד) — אי״ז עיקר שכרן של מצות. ואחז״ל (קידושין לט, ב. חולין בסופה) שכר מצוה בהאי עלמא ליכא (וראה לקו״ש חי״ט ע׳ 197 ואילך)."],["12","12","עיון יעקב לע״י עירובין שם (וראה שם (וכן בע״ז ד, ב). ובכמה מפרשים עוד תירוצים. ואכ״מ)."],["13","13","קידושין בסופה."]]],[1300291154,"מן העולם (ווען עס ענדיקט זיך דער זמן השכירות), ווייל „שכירות אינה משתלמת אלא לבסוף“14 (ווי דער דין15, אַז אויב איינער האָט געדונגען אַ פועל פאַר אַ תקופה מסויימת, איז דער שוכר ניט עובר אויף בל תלין ביז עס גייט דורך כל התקופה).\nדער תירוץ איז אָבער מתאים נאָר לויט שיטת הרמב״ם, אַז עוה״ב — „סוף מתן שכרן של מצות“16 — איז עולם הנפשות בלא גוף (גן עדן)17, וואָס „באין לו לאדם אחר חיי העולם הזה“18 — ולפ״ז באַציט זיך „למחר (לעולם הבא) לקבל שכרם“ צו גן עדן19;\nמשא״כ לויט שיטת הרמב״ן20 — וואָס אַזוי איז די הכרעה פון קבלה און חסידות21 — אַז עולם הבא דאָ מיינט עולם התחי׳ (און דאָס איז דער תכלית השכר) — קומט אויס, אַז דער אויבערשטער איז „מאחר“ שכר מצות ביז לעתיד לבא, הרבה זמן נאָך דעם ווי עס ענדיקט זיך דער זמן ה„שכירות“ פון אַ אידן (אַ איד מוז וואַרטן צו באַקומען דעם שכר מצות ביזן זמן פון (ימות המשיח ו)עולם התחי׳)22!\nוהדרא קושיא לדוכתא: ווי שטימט דער זמן התשלום פון שכר מצות מיט דער הלכה פון „ביומו תתן שכרו“?\nג. וי״ל — די שאלה ווערט באַוואָרנט לויטן ביאור פון אַלטן רבי׳ן אין ספר התניא:\nדער אַלטער רבי23 ברענגט דעם מאמר רז״ל24 אַז „תכלית בריאת עולם הזה הוא שנתאוה הקב״ה להיות לו דירה בתחתונים“, וואָס דאָס מיינט אַז אין עולם הזה התחתון „שאין תחתון למטה ממנו בענין הסתר אורו ית׳“ זאָל לייכטן דער „אור ה׳“ אָן קיין שום פאַרשטעל25.\nאון דאָס ווערט אויפגעטאָן דורך „מעשינו ועבודתנו כל זמן משך הגלות“26 (ובמשך כל זמני העבודה בכלל), וואָרום יעדע פעולה פון אַ אידן אין עבודת התומ״צ איז פועל אַ זיכוך בגשמיות גופו וחלקו בעולם (און אַ המשכת אור אלקי בעולם) — אַזוי, אַז בצירוף פון עבודת כל בני ישראל במשך כל הדורות ווערט נשלם דער בירור וזיכוך פון גאַנץ עולם הזה און די גאַנצע וועלט ווערט אַ „דירה לו יתברך“.\n[און ווי דער אַלטער רבי איז מבאר27, אַז „כללות העולם“ איז צעטיילט אויף ששים רבוא חלקים, כנגד די „ששים רבוא נשמות“ (וואָס דאָס איז דער מספר",[["14","14","ב״מ קי, ב."],["15","15","ב״מ שם (במשנה). רמב״ם הל׳ שכירות פי״א ה״ב. שו״ע חו״מ סשל״ט ס״ה. שו״ע אדה״ז חו״מ שם סי״ב."],["16","16","ל׳ הרמב״ם הל׳ תשובה פ״ט ה״א."],["17","17","הל׳ תשובה פ״ח ה״ב."],["18","18","שם ספ״ח."],["19","19","להעיר מרש״י עירובין שם ד״ה ולא למחר לעשותם. וראה ענף יוסף לע״י שם. „חדושי גאונים“ לע״י ע״ז ג, א. אבל להעיר, דגם להרמב״ם, „סוף מתן שכרן של מצות“ לכאורה אינו הג״ע דעתה (שלאחרי מיתה), אלא לאחרי ימוה״מ ותחה״מ (ראה עיקרים מ״ד פל״א)."],["20","20","שער הגמול בסופו (הועתק ב„פירוש“ לרמב״ם הל׳ תשובה פ״ט ה״ב). וראה גם השגת הראב״ד שם פ״ח ה״ב. ועוד."],["21","21","ראה לקו״ת (צו טו, ג. ש״ש סה, סע״ד). סהמ״צ להצ״צ מצות ציצית. ובכ״מ."],["22","22","אף שישנו השכר דג״ע — אי״ז עיקר שכרן של מצות (לדעת הרמב״ן כו׳). וראה סהמ״צ להצ״צ שם (ובכ״מ) דבג״ע הוא (בעיקר) השכר על לימוד התורה, ובתחה״מ הוא מתן שכרן של מצות. ע״ש."],["23","23","תניא רפל״ו."],["24","24","תנחומא נשא טז. ועוד."],["25","25","תניא שם (פל״ו)."],["26","26","ל׳ התניא רפל״ז."],["27","27","תניא פל״ז (מח, א)."]]],[1300291155,"פון די נשמות כלליות וועלכע זיינען „שרשים“ פון אַלע נשמות ישראל — וואָס יעדע נשמה פרטית איז אַ ניצוץ פון איינעם פון די „ששים רבוא . . שרשים“) — והיינו, אַז יעדע נשמה פרטית, יעדער איד האָט אַ חלק אין עולם וואָס איז „שייך לו“, וואָס דורך זיין עבודה בתומ״צ איז ער מזכך „זיין“ חלק אין עוה״ז;\nאון דורך דעם וואָס אַלע ששים רבוא נשמות ישראל פירן דורך זייער עבודה, ווערט נזדכך „כללות העולם“ און ער ווערט אַ דירה לו יתברך].\nאון צו דעם מצב פון תכלית הזיכוך והעלי׳ וועט דער עולם צוקומען לעתיד לבא — לימות המשיח, ובעיקר ובשלימות — בתחיית המתים, וואָס דאַן וועט לגמרי בטל ווערן דער רע פון עולם הזה און עס וועט זיין „התגלות28 כבודו וראו כל בשר יחדיו ויופיע עליהם בהדר גאון עוזו וימלא כבוד ה׳ את כל הארץ“.\nקומט לפ״ז אויס, אַז די עבודה פון אַלע אידן צוזאַמען במשך כל הדורות יחד איז אין גדר פון איין „שכירות“, וואָס ענינה ותכליתה איז צו אויפטאָן אַ דירה לו יתברך בתחתונים. וי״ל נאָך מער: אין דעם תפקיד זיינען אידן (ניט אין גדר פון „שכיר“, נאָר) אין גדר פון „קבלן“: דער אויבערשטער האָט איבערגעגעבן עולמו בידי ישראל אַז זיי זאָלן מאַכן פון דעם עולם אַ דירה לו יתברך.\nאון דערמיט איז פאַרענטפערט פאַרוואָס עיקר ענין השכר ווערט באַצאָלט ערשט לעתיד לבא (בימות המשיח, ובעיקר — בעולם התחי׳) — ווייל דער שכר פון עולם הבא איז דער תשלום כללי צו אַלע אידן כאחד28* פאַר זייער עבודה צו מאַכן פון וועלט אַ דירה לו יתברך; און דעם שכר באַקומען אידן תיכף נאָך זייער פאַרענדיקן די עבודה פון לעשות לו יתברך דירה בתחתונים.\nד. לויט דעם הסבר אין דעם תוכן פון שכר המצות — קען מען מבאר זיין נאָך אַן ענין בשייכות צו שכר מצות:\nעס איז ידוע וואָס דער רמב״ם29 איז מבאר בנוגע די הבטחות ויעודים טובים בגשמיות, וואָס מיר געפינען „בכל התורה כולה“ (דלכאורה, ווי שטימט עס מיט דעם אַז „מתן שכרן של מצות . . היא חיי העולם הבא“?) — אַז „אין אותן הטובות הם סוף מתן שכרן של מצות . . אלא . . הקב״ה נתן לנו תורה . . והבטיחנו בתורה שאם נעשה אותה בשמחה . . יסיר ממנו כל הדברים המונעים אותנו מלעשותה . . וישפיע לנו כל הטובות המחזיקות את ידינו לעשות התורה . . כדי . . (ש)נשב פנויים ללמוד בחכמה ולעשות המצוה כדי שנזכה לחיי העולם הבא“.\nפון שטחיות לשון הרמב״ם איז משמע, אַז די השפעות „כל הטובות“ בענינים גשמיים וואָס דער אויבערשטער איז מבטיח, זיינען ניט בתור תשלום שכר, נאָר אַן ענין צדדי, וואָס קומט מצד חסד ה׳ — היות אַז אידן זיינען מקיים תומ״צ (בשמחה), איז די הנהגה מלמעלה באופן אַז דער אויבערשטער נעמט אַוועק די דברים המונעים און איז משפיע „לנו כל הטובות המחזיקות את ידינו“ צו קענען נאָך בעסער דורכפירן זייער עבודה בתומ״צ.\nס׳איז אָבער שווער אַזוי צו זאָגן, ווייל לפ״ז וועט אויסקומען, אַז אין די אַלע",[["28","28","ל׳ התניא שם (מז, סע״ב ואילך). 28*) משא״כ השכר דג״ע הוא על עבודתו הפרטית של כאו״א, ולכן בא לו לאחרי גמר עבודתו (כנ״ל ס״ב). וראה לעיל הערה 22. — ולהעיר מאגה״ק סי״ז."],["29","29","הל׳ תשובה פ״ט ה״א."]]],[1300291156,"ערטער וואו חז״ל פאַרגלייכן דעם ענין פון שכר מצות צום תשלום וואָס אַ בעה״ב איז מחוייב צו צאָלן זיין פועל, ווערט געמיינט בלויז דער שכר פון עוה״ב — און ניט דער ריבוי עניני שכר המפורשים בתורה שבכתב30!\nאיז דעריבער מסתבר צו זאָגן, אַז אויך דער ענין פון השפעות „כל הטובות“ המבואר ברמב״ם (המחזיקות את ידינו לעשות התורה), איז אין גדר פון שכר31 ובמילא אַן ענין פון הלכה, וואָס מען געפינט דוגמתה אין די חיובי הבעה״ב צו אַ פועל.\nה. לכאורה וואָלט מען דאָס געקענט פאַרבינדן מיט הידוע, אַז אידן ווערן אָנגערופן עבדי ה׳, און דער דין ביי אַן עבד עברי איז, אַז „חייב האדון להשוותן לו במאכל ובמשקה בכסות ובמדור“32. און דערפאַר, בשעת מיר זיינען זיך מתעסק בעבודת ה׳, איז דאָ אַ חיוב כביכול אויף דעם אויבערשטן, אונזער אדון, צוצושטעלן אַלע אונזערע צרכים ובהרחבה („להשוותן לו“).\nאָבער דאָס איז ניט מתאים. ווייל דער חיוב פון אַן אדון לעבדו — איז ניט דומה צו שכר מצות (ווי אַ בעה״ב צאָלט זיין פועל) — דאָס איז ניט שכר פעולה, נאָר אַ חיוב על האדון לעבדו מצד דעם וואָס הקונה עבד עברי כקונה אדון לעצמו33.\n[ובכלל: דער גדר פון שכר מצות — אַז דער אויבערשטער צאָלט אידן פאַר זייער עבודה ווי מען צאָלט אַ פועל — איז ניטאָ באַ אידן אַלס עבדים פון אויבערשטן: אַן עבד באַקומט ניט שכר פאַר זיין אַרבעט; ער איז מחוייב צו אַרבעטן, זייענדיק קנוי לרבו34].\nמשא״כ די השפעות טובות הנ״ל, זיינען אַן ענין של התחייבות35, וואָס דוגמתם זיינען די חיובים פון אַ בעה״ב צו זיין פועל.\nאויך איז דאָס ניט מצד דעם וואָס ביי אַ פועל איז דער דין — „כי תבוא בכרם רעך ואכלת ענבים כנפשך שבעך גו׳ כי תבא בקמת רעך וקטפת גו׳“36, אַז דער בעה״ב מוז לאָזן די פועלים עסן „ממה שהן עושין בו“37 — אַז עד״ז איז בנדו״ד: וויבאַלד אידן געפינען זיך בכרמו ושדהו של הקב״ה (עולם הזה) און טוען דאָרט „מלאכה“ פאַרן „בעל הבית“, נעמען זיי זייערע צרכים (שכל",[["30","30","ראה גם לעיל ע׳ 42־43."],["31","31","ולהעיר מלשון הרמב״ם שם „אין אותן הטובות כו׳ סוף מתן שכרן של מצות“."],["32","32","רמב״ם הל׳ עבדים פ״א ה״ט. וראה גם לקו״ש חי״ט ע׳ 204 ואילך."],["33","33","קידושין כ, א."],["34","34","ראה בארוכה „הדרן“ הנ״ל (הערה 3) סעיף ז (ח) ואילך."],["35","35","אף שבכלל לא שייך „חיוב“ למעלה, ד„מי הקדימני ואשלם“ (ויק״ר פכ״ז, ב), ונאמר (תהלים סב, יג) „ולך אד׳ חסד כי אתה תשלם לאיש כמעשהו“ (ראה אוה״ת שה״ש (כרך ב) ע׳ תשמט ואילך. וש״נ. ועוד)."],["36","36","פרשתנו כג, כה־כו — דבפועל הכתוב מדבר (ב״מ פז, סע״ב. פרש״י עה״פ*. רמב״ם הל׳ שכירות רפי״ב)."],["37","37","ל׳ הרמב״ם שם. *) היינו שכ״ה גם ע״פ פשוטו של מקרא. ועוד: מזה שרש״י מעתיק בהד״ה רק התיבות „כי תבוא בכרם רעך“ (וכן בפירושו על כי תבוא בקמת רעך) מובן, שההכרח לפירושו הוא מתיבות אלו עצמן (ודלא כמ״ש במפרשי רש״י (רא״ם, גו״א ועוד) שרש״י סומך עמ״ש בד״ה שלאח״ז), וי״ל בפשטות, כמ״ש ברמב״ם (שבפנים ההערה) „וכי אילו לא שכרו מי התיר לו שיבא בכרם רעו או בקמה שלו שלא מדעתו“ (ומתורצת קושיית הלח״מ שם, כי זהו „דרשה היותר פשוטה“ — יד מלאכי כללי הרמב״ם אות ד). — וראה בארוכה לקו״ש חל״ד ע׳ 129 ואילך."]]],[1300291157,"צרכי האדם ווערן אָנגערופן בשם אכילה<sup data-n=\"38\">38</sup> „ממה שהן עושין בו“ —\nווייל די מצוה לייגט אַרויף אַ חיוב אויפן בעה״ב (ניט צו מאכיל זיין דעם פועל, נאָר) בלויז — „שיניח37 אותן לאכול“39 [ולהוסיף: דער חיוב איז ניט נאָר בשייכות צו אַן אדם במלאכתו, נאָר אפילו בנוגע אַ בהמה וואָס אַרבעט — „לא תחסום שור בדישו“40];\nמשא״כ די יעודים טובים הנ״ל בנוגע די מצות זיינען ענינים וואָס דער אויבערשטער איז כביכול מחוייב35 צו געבן אידן אַלס שכר פאַר זייער עבודה.\nו. ויש לומר הביאור בזה:\nע״פ האמור לעיל (סעיף ג) — אַז דער תפקיד פון אידן איז צו מאַכן פון עולם הזה אַ דירה לו יתברך — איז יש לומר, אַז די עבודה פון אידן אין וועלט האָט אין זיך (ניט נאָר דעם גדר פון „קבלנות“, נאָר) אויך דעם גדר פון שותפות:\nהיות אַז דער שכר דלעתיד לבא באַשטייט אין דעם וואָס אידן וועלן זען „עין בעין“ כבוד השם, דעם אור אלקי וואָס איז נמשך געוואָרן דורך זייער עבודה, אין דעם אופן פון „שכר מצוה מצוה“41 — והיינו, אַז דער „שכר“ איז ניט קיין באַזונדער זאַך פון זייער עבודה, נאָר — דער תוכן פון דער עבודה גופא42 —\nקומט אויס, אַז דאָס איז בדוגמא כביכול פונעם דין43 „הנותן ביצים לבעל התרנגולים להושיב התרנגולים עליהן עד שיצאו האפרוחים ויגדל אותן בעל התרנגולים ויהי׳ הריוח ביניהם“:\nדער אויבערשטער האָט איבערגעגעבן עולמו צו בני ישראל, זיי זאָלן אויפטאָן בעבודתם, אַז אלקות וואָס איז פאַראַן אין וועלט בכח44 ובהעלם (בדוגמא כביכול ווי די אפרוחים וועלכע זיינען דאָ „בכח“ אין די ביצים) זאָל נתגלה ווערן און ביז צו תכלית הגילוי (— „ויגדל אותן“) — און דער „ריוח“ פון אָט דער עבודה איז (מצד וכעין „שותפות“) „ביניהם“:",[["38","38","ראה סנהדרין לח, א (ובפרש״י שם ד״ה שיכנס). ועוד."],["39","39","ודוחק לומר שהבטחת התורה ביעודים גשמיים היא כמו בעה״ב שפסק ליתן מזונות לפועליו (ראה ב״מ רפ״ז) — כי זהו לא שכר פעולה, כ״א ענין נוסף שהבעה״ב קיבל עליו (או שכ״ה מנהג המקום — ראה ב״מ שם), משא״כ הדין שהפועלים אוכלים ממה שהן עושין בו שהוא חיוב מה״ת (ראה תוד״ה ואלו ב״מ פז, א)."],["40","40","פרשתנו כה, ד. — ודיני לא תחסום באו ברמב״ם (שם פי״ג) בהמשך לדיני אכילת הפועל. ובשו״ע אדה״ז (חו״מ שם סכ״ב) כללם יחד: אדם או בהמה כו׳ אוכלים ממה שעושי׳ בו כו׳."],["41","41","אבות פ״ד מ״ב. וראה תניא רפל״ז. שם פל״ט (נב, ב)."],["42","42","וי״ל שזהו ההפרש בין השכר דימות המשיח ותחה״מ לגבי „קבלת שכר (ש)עיקרו באלף השביעי“ (תניא פל״ז בהגהה) — דימוה״מ ותחה״מ „הם תכלית ושלימות בריאת* עוה״ז“ (תניא שם), היינו ה„ריוח“ מהעבודה עצמה (ע״ד האפרוחים היוצאים ע״י הושבת התרנגולים); משא״כ השכר דאלף השביעי הוא לאחרי (ולמעלה מ)כל גדר של עבודה (ראה שע״ת לאדהאמ״צ ח״ב פל״ב (כג, ד)). [ומ״מ אין ב„איחור“ שכר זה עד אלף השביעי משום בל תלין — כי ענינו של אלף השביעי הוא קבלת השכר על כללות ענין העבודה דכל שית אלפי שנין, ששת ימי המעשה (ראה שע״ת שם). ואכ״מ]."],["43","43","רמב״ם הל׳ שלוחין ושותפין רפ״ח."],["44","44","להעיר מע״ח בתחלתו (וכן בשער ההקדמות הקדמה ג׳) שאחד מטעמי הבריאה הוא — „שיתגלו שלימות כוחותיו כו׳“. וע״פ המבואר בלקו״ש חי״ט (ע׳ 194 ואילך) יש לקשר זה עם המבואר בפנים. ואכ״מ. *) לכאורה כצ״ל. וכ״ה בכמה דפוסים."]]],[1300291158,"דער אויבערשטער איז זיך מתענג כביכול פון דעם וואָס עס האָט זיך אויסגעפירט דער נתאוה הקב״ה להיות לו דירה בתחתונים (כמאמר45 „נחת רוח לפני שאמרתי ונעשה רצוני“); און אידן האָבן תענוג פון „לחזות בנועם ה׳“46, פון דעם גילוי אלקות וואָס זיי האָבן אויפגעטאָן בעבודתם.\n[וואָס דאָס איז ניט נאָר אַ „שותפות“ אין אַ זייטיקן „ריוח“ — אין דעם גילוי התענוג וואָס עבודת בני ישראל טוט אויף — נאָר אין אַ „ריוח“ וואָס איז פאַרבונדן מיט דעם עצם מציאות פון עולם (ע״ד ווי אין דעם דין הנ״ל, אַז מ׳איז שותפים אין די אפרוחים וועלכע קומען אַרויס פון די ביצים גופא), כמאמר חז״ל47 „כל המתפלל כו׳ ויכולו כו׳ כאילו נעשה שותף להקב״ה במעשה בראשית“. וואָס דער תוכן הענין פון אמירת „ויכולו“ איז צו „מעיד“ און מגלה זיין48 די הכרה אין בורא עולם, וואָס דאָס איז דער מכוון פון כללות עבודתם של בנ״י בעולם שנברא בששת ימי בראשית — און דורך דער עבודה פון מגלה זיין אלקות אין עולם, וואָס מען מאַכט די וועלט גופא אַ „דירה לו ית׳“, ווערט מען אַ „שותף להקב״ה במעשה בראשית“].\nועפ״ז יש לומר, אַז דער „חיוב“ צו צאָלן אידן שכר מצות בעוה״ז (להסיר הדברים המונעים ולהשפיע הטובות המחזיקות את ידינו לעשות התורה) איז מיוסד על הלכה זו ד„הנותן ביצים לבעל התרנגולים כו׳ ויהי׳ הריוח ביניהם“, וואָס דער דין איז43, אַז נוסף אויף דעם חלק הריוח, וואָס דער „נותן“ טיילט צו דעם „בעל התרנגולים“ לאחרי ש„יגדל אותן“, איז ער מחוייב „(צריך) להעלות שכר עמלו ומזונו . . בכל יום“.\nוכן הוא בעניננו, אַז אויסער דעם חיוב פון חלוקת הריוח לעתיד לבא (נאָך דעם ווי אידן פאַרענדיקן זייער עבודה צו מאַכן פון וועלט אַ דירה לו יתברך), איז אויך בזמן הזה — במשך זמן העבודה — פאַראַן דער חיוב צו געבן אידן דעם שכר פון „עמלם ומזונם“, כדי זיי זאָלן קענען דורכפירן עבודתם כדבעי („נשב פנויים ללמוד בחכמה ולעשות המצוה“).\nז. ענין הנ״ל האָט אַ שייכות מיוחדת צום זמן אין וועלכן מען געפינט זיך איצט — חודש אלול, דער חודש ההכנה צום יום הדין, וואָס הדין פון ר״ה איז אויף ענינים גשמיים49:\nע״פ כל הנ״ל איז פאַרשטאַנדיק, אַז לבד זאת וואָס זייענדיק עבדיו של הקב״ה, דאַרף דער אויבערשטער אונז געבן אַלע אונזערע צרכים אין מזון לבוש ובית (ביז אין אַן אופן פון „להשוותן לו“, כביכול);\nאון לבד זאת וואָס אויך מצד דעם יחס פון „בעה״ב“ און „פועל“, איז ווען אַ איד טוט עבודתו אין שדהו וכרמו של הקב״ה, דאַרף אים געגעבן ווערן די אפשריות פון „ואכלת גו׳ כנפשך שבעך גו׳“ פון דעם אויבערשטנ׳ס כרם, עוה״ז [און דאָס אפילו אויך מצד דעם גוף ונפש הבהמית, „בהמה“ שבאדם, היות אַז מקרא מלא דבר הכתוב „לא תחסום שור בדישו“];",[["45","45","ספרי (ורש״י) פינחס כח, ח. ובכ״מ."],["46","46","ל׳ הכתוב — תהלים כז, ד. וראה אגה״ק סכ״ט."],["47","47","שבת קיט, ריש ע״ב. ועד״ז בדן דין אמת לאמיתו (שבת י, א. וש״נ) ועוד."],["48","48","ראה חדא״ג מהרש״א שם. אוה״ת בראשית עה״פ ויכולו (מג, ב ואילך. שם כרך ג תקו, ב ואילך). לקו״ש ח״ז ע׳ 22 הערה 73."],["49","49","לקו״ת ר״ה (נט, ב) — מהגהמ״י (הל׳ תשובה פ״ג אות א) בשם הרמב״ן."]]],[1300291159,"הנה נוסף על כל זה, איז דאָ אַ חיוב כביכול אויף דעם אויבערשטן צוצושטעלן די אידן און זיי באַזאָרגן נאָך פון פריער מיט שכר „עמלם ומזונם“ כדי זיי צו געבן די מעגלעכקייט דורכצופירן עבודתם.\nובפשטות — אַז שוין בתחילת השנה איז יעדער איד זוכה בדין און ווערט נכתב ונחתם לאלתר50 בספרם של צדיקים גמורים לשנה טובה ומתוקה בטוב הנראה והנגלה — בבני חיי ומזוני רוויחי, ובכולם רויחי, אויך בגשמיות כפשוטה,\nאון בשעת דער אויבערשטער גיט אידן גשמיות, מאַכן זיי דערפון רוחניות51, און פירן דורך תפקידם — לעשות לו יתברך דירה בתחתונים.\n(משיחות ש״פ וארא וש״פ בא תשמ״ו; ש״פ תצא תשמ״ה)",[["50","50","ר״ה (טז, ב) וב„מדרש“ (ירושלמי ר״ה פ״א ה״ג. ועוד) הובא בטאו״ח (סו״ס תקפא) שכבר בער״ה בטוחין שזוכין כו׳ ועד שמתעטפין כו׳."],["51","51","כפתגם אדה״ז („היום יום“ כז טבת)."]]],[1300291160,"<h3>תבא</h3>\nא. בנוגע צו מצות בכורים, וואָס „הבכורים טעונין כלי”1, זאָגט דער רמב”ם2: הביאם בכלי מתכות נוטל הכהן הבכורים וחוזר הכלי לבעליו ואם הביאם בכלי ערבה וחלף3 וכיוצא בהן הרי הבכורים והסלים לכהנים.\nדאַרף מען פאַרשטיין: דער מקור פון דעם דין איז (ווי מפרשים צייכענען אָן) די משנה אין בכורים4 „העשירים מביאים בכוריהם בקלתות של כסף ושל זהב והעניים מביאין אותם בסלי נצרים של ערבה קלופה והסלים והבכורים ניתנין לכהנים”. און פון דער משנה לערנט די גמרא5 אַרויס — „מנא הא מילתא דאמרי אינשי בתר עניא אזלא עניותא דתנן עשירים כו' והעניים כו' הסלים והבכורים נותנים6 לכהנים”.\nפון דעם איז משמע בפשטות, אַז דער חילוק צווישן „קלתות של זהב” און „סלי נצרים” ווענדט זיך אין דעת הנותן: וויבאַלד אַז ע”ד הרגיל פלעגן די עשירים ברענגען די ביכורים אין טייערע כלים „של כסף ושל זהב”, האָבן די נותנים ניט געהאַט בדעה אַוועקצוגעבן די טייערע כלים — ווי רש”י זאָגט מפורש7 „והעשירים לא היו נותנין קלתותיהן לכהן”, בפשטות צוליב זייער טייערקייט — און דערפאַר געהערן זיי צו די בעלים; משא”כ די עניים, וועלכע ברענגען די ביכורים אין כלים פון „סלי נצרים” (ווייל אין ידם משגת צו טייערע כלים), האָבן זיי אין זינען אַוועקצוגעבן אויך די כלים — און דעריבער באַלאַנגען אויך די „סלים” צו די כהנים. ואתי שפיר וואָס די גמרא ברענגט דערפון אַ ראי' צום כלל „דאמרי אינשי בתר עניא אזלי עניותא”, אַז צוליב דעם וואָס ער איז אַן",[["1","1","לשון הרמב”ם הל' בכורים פ”ג ה”ז — מספרי פרשתנו כו, ב."],["2","2","שם ה”ח."],["3","3","במשנה וספרי (דלקמן) ליתא*. — הלשון „חלף” נמצא גם ברמב”ם הל' בכורים כאן בהלכה שלפנ”ז**. וכן בהלכות (כמצויין בקונקורדנציא לס' משנה תורה): שבת פ”י ה”ח; סוכה פ”ה ה”ד וה”ו; מאכלות אסורות פי”א הכ”ג; כלים פ”א הי”ג, פכ”ה הי”ג. ומקורו במשנה כלים פי”ז מי”ז, תוספתא סוכה פ”א, ז (ובסוכה כ, א לגירסת הר”ח), תו”כ מצורע (טו, ד). וראה סוכה לד, א. ערוך ערך חלף (הב'). *) אולי הייתה כן בגירסת הרמב”ם במשנה, או בספרי. — העירוני ז”ע אשר בפיה”מ הוצאת קאפח, שכותב שהעתיק נוסח המשנה מכת”י הרמב”ם — הגירסא היא כלפנינו. וגם מפירוש המשנה שם משמע לכאורה שלא גרס תיבה זו במשנה (שהרי העתיק בפירושו לשון המשנה „ערבה קלופה” ולא כתב „וחלף”). וכן בכל שינויי נוסחאות דמשניות (הן שנדפסו על גליון המשניות וכן ב„משנה עם שינויי נוסחאות” (ירושלים, תשל”ה)) לא הובאה גירסא כזו (ולא בראשונים). ואולי אפ”ל שבהיד צ”ל „בכלי ערבה קלופה” ועפ”ז בטלה ג”כ השאלה למה השמיט הרמב”ם תיבה זו בחיבורו. — ולהעיר דבכת”י הרמב”ם בחיבורו חילוק התיבות „קלופה” ו„חלף” קטן משבדפוס או משבכת”י אחרים ובפרט אשכנזים. ויש להוסיף: יתכן דגם זה שבהלכה הקודמת נמצא ברמב”ם הלשון „וחלף” (ראה פנים ההערה) גרם לטעות המעתיק בהלכה זו. **) ובמקור ההלכה (תוספתא בכורים פ”ב, ח, ירושלמי בכורים פ”ג ה”ה) איתא רק הדין שצריכים להפסיק בין המינים ב„דבר אחר”, בלי פירוט הדוגמאות (שברמב”ם) „כגון הוצין וחלף כו'”."],["4","4","פ”ג מ”ח."],["5","5","ב”ק צב, סע”א."],["6","6","ולא כבמשנה „ניתנין”. וראה לקמן הערה 19 ובשוה”ג."],["7","7","ב”ק שם ד”ה הסלין."]]],[1300291161,"עני ברענגט ער די ביכורים אין „סלי נצרים” — איז „אזלי עניותא” — וואָס אויך די „סלים” בלייבן ביים כהן.\nדער רמב”ם אָבער איז מדגיש דעם חילוק צווישן „כלי מתכות” און „כלי ערבה”, ניט דערמאָנענדיק דעם אונטערשייד צווישן עשיר און עני — איז דערפון משמע, אַז לדעת הרמב”ם איז דאָס ניט תלוי אין דעת הנותן [וואָס ווענדט זיך אין דער טייערקייט אָדער ביליקייט פון די כלים, ובפרט אַז „כלי מתכות” קען אויך זיין אַזאַ וואָס האָט ניט קיין גרויסע שווי8], נאָר דער חילוק איז פאַרבונדן מיטן סוג הכלי כשלעצמו — צי דאָס איז אַ „כלי מתכות” אָדער „כלי ערבה וחלף”.\nוא”כ הוא צ”ל לפי שיטת הרמב”ם, אַז דאָס וואָס די גמרא זאָגט דעם מקור צום כלל „דאמרי אינשי בתר עניא וכו'”, פון דער משנה אין ביכורים „עשירים מביאין כו'” — מיינט עס (ניט דערפאַר וואָס ביי אַ כלי של עני איז דעת הנותן צו געבן די כלי צום כהן, נאָר) פון דעם מסובב פון דער הלכה: אַן עני כרגיל ברענגט אין „כלי נצרים”, און אַזאַ מין כלי דאַרף בלייבן ביים כהן.\n— וצריך ביאור בדעת הרמב”ם.\nב. אויפן פסוק9 „ולקח הכהן הטנא מידך” שטייט אין ספרי: מכאן אמרו העשירים מביאים ביכורים בקלתות של כסף ושל זהב ועניים בסלי נצרים של ערבה קלופה וסלים ניתנים לכהנים לזכות10 מתנה לכהנים.\nלערנען מפרשים11 דעם פירוש בדברי הספרי: פון דעם וואָרט „הטנא”, וואָס לכאורה איז ער איבעריק, לערנט מען אָפּ אַז דער דין „ולקח הכהן” (און ס'ווערט זיינע) איז דוקא „כשהוא טנא, סל בעלמא”12, משא”כ אויב ס'איז אַ „כלי מתכות” וכיו”ב.\nאון דער טעם הדבר איז „לזכות מתנה לכהנים”, ווי דער תוס' יו”ט איז מבאר13: היות אַז די ביכורים־פירות פון די עניים זיינען „מעט”, דעריבער האָט מען מתקן געווען אַז אַן עני זאָל אַוועקגעבן אויך דעם סל, וואָס „עם הסל יהי' נחשב מתנה”14.\nס'איז אָבער מובן אַז מ'קען אַזוי ניט לערנען אין דעת הרמב”ם, וואָרום לפ”ז איז דאָך דאָס תלוי בעיקר (ניט אין דער כלי אין וועלכער מ'ברענגט די בכורים, נאָר) אין כמות הפירות וואָס מען ברענגט לביכורים — און דאָס ווענדט זיך ווידער אין דעם חילוק צווישן עשירים און עניים — בעת אַז דער רמב”ם איז נאָר מחלק, כנ”ל, בין סוגי הכלים עצמם און ניט דעם חילוק בין עניים ועשירים אין כמות הפירות וועלכע געפינען זיך אין די כלים.\nג. וי”ל דעם ביאור בזה:\nדעם גדר החיוב פון נתינת הסל צו די",[["8","8","להעיר שבפיהמ”ש בכורים שם כתב הרמב”ם: וענין אמרם של כסף מחושקים ומצופים כסף או זהב."],["9","9","פרשתנו כו, ד."],["10","10","כ”ה גם בדפוס ראשון דספרי. וי”ג „(בשביל) לרבות מתנה לכהנים” (ראה ספרי הוצאת האראוויץ כו' נ.י. תשכ”ט. ושם כו”כ גירסאות). — עוד גירסא „לזכות לעניים” (מלבי”ם כאן. וראה ספרי דבי רב — נעתק בהערה 14). ואכ”מ."],["11","11","ספרי דבי רב לספרי שם. וראה חדושי מהרי”ח למשנה בכורים שם בסופה."],["12","12","ספרי דבי רב שם."],["13","13","במשנה בכורים שם."],["14","14","ל' התוי”ט שם. ובספרי דבי רב: מאחר דהעני מסתמא פירות מועטין אית לי' הלכך רבי לי' רחמנא לזכותו שיתן מתנה מעוטה נוספת לכהן על הבכורים."]]],[1300291162,"כהנים צוזאַמען מיט די בכורים קען מען לערנען בכמה אופנים15. ומהם:\nא) די שייכות פון די סלים מיט די בכורים איז נאָר בהבאתם, אָבער דער דין אַוועקצוגעבן די סלים צו די כהנים איז אַ באַזונדער חיוב נתינה, וועלכער האָט קיין שייכות ניט צו חיוב נתינת הביכורים עצמם.\nב) די נתינת הסלים האָט אַ שייכות צו דער נתינה פון די ביכורים, אָבער די שייכות איז נאָר בנוגע דעם חיוב הנתינה, אַז דער חיוב נתינת הביכורים להכהן איז גורר אויך די נתינת הסלים — אָבער ניט אַז די מעשה הנתינה פון די סלים איז אינעם זעלבן גדר ווי נתינת הביכורים.\nג) אָדער נאָכמער — אַז די שייכות איז ניט נאָר אין דעם חיוב הנתינה, נאָר אויך אין דער מעשה הנתינה: די ביכורים און די סלים דאַרפן געגעבן ווערן בחדא מחתא אין איין מעשה נתינה.\nוי”ל אַז ס'איז דאָ אַ נפק”מ לדינא צווישן די אופנים:\nלויטן ערשטן אופן, אַז די שייכות פון די סלים מיט די ביכורים איז נאָר אין דער הבאה ל„בית ה”א”16, די נתינת הסלים האָט קיין שייכות ניט מיט נתינת הביכורים — במילא קען דאָס געגעבן ווערן צו וועלכן כהן עס זאָל נאָר זיין, ואולי י”ל אַז אויך לאו דוקא פון אנשי המשמר17.\nלויטן צווייטן אופן, אַז דער חיוב פון נתינת הסלים איז אַ תוצאה פון דעם חיוב נתינת ביכורים, איז מסתבר אַז עס דאַרף געגעבן ווערן צו די כהנים שבאותו המשמר, אַזוי ווי די ביכורים עצמם; אָבער לאו דוקא צו דעם זעלבן כהן (כהנים) וואָס באַקומט די ביכורים;\nלויטן אופן הג' אָבער, אַז די שייכות איז אויך אין דעם אַז עס דאַרף זיין איין מעשה נתינה, איז פשוט אַז דאָס ווערט געגעבן צו דעם זעלבן כהן (כהנים) ובמעשה אחד מיט די ביכורים.\nד. ועפ”ז יש לומר אַז אין דעם באַשטייט דער חילוק צווישן דרשת הספרי לפי מובנה כפשוטו, דרשת הגמ' אין ב”ק לפי פרש”י, און דעם פירוש התוי”ט כו' בספרי:\nא) פון דעם וואָס דער דין, אַז די סלים גיט מען אָפּ צו די כהנים, ווערט אין ספרי אָפּגעלערנט פון פסוק „ולקח הכהן הטנא מידך” אַלס אַ דין מיוחד אויפן „טנא”, און אויך דערפון וואָס בסיום הענין אין ספרי שטייט „וסלים נותנין לכהנים” (און זאָגט ניט בלשון המאחדם „וסלים ובכורים ניתנין לכהנים”, ע”ד ווי אין דער משנה)18 — איז משמע, אַז דער חיוב צו געבן די סלים צו די כהנים איז אַ באַזונדער ענין בהנתינה, ניט די נתינת הבכורים. און דאָס איז כוונת הספרי בסיומו — „לזכות מתנה לכהנים”, אַז ס'איז אַ באַזונדער „זכות מתנה לכהנים” וואָס דער עני האָט, מיט דעם וואָס ער גיט דעם „טנא” צום כהן.",[["15","15","כמו בכל דבר שבא כטפל וכלי ולבוש לעיקר. לכללות ג' (ד') אופנים דלקמן להעיר גם ממשנ”ת (לקו”ש חכ”ג ע' 143 ואילך) ג' האופנים בהגדר דמטפחת ס”ת (ושייכותה להס”ת). וש”נ."],["16","16","נסמן בהערה 28."],["17","17","וע”ד ומעין התורין ובני יונה שהיו מביאין בידם כשהיו מביאין את הבכורים, שאף שהיו ניתנין לכהנים (רמב”ם שם ה”ט), אין נתינה זו שייכת לנתינת הבכורים לכהנים (ראה רדב”ז לרמב”ם שם: אותם שבידם היו דורון לכהנים) — ולכאורה אין חיוב ליתנם לאנשי אותו המשמר דוקא."],["18","18","כ”ה גם בדפוס א' דספרי, יל”ש ובכ”מ. וכן הובא מספרי בתוי”ט שם. ובספרי הנ”ל הערה 10 „והסלים והבכורים”."]]],[1300291163,"ב) אין גמרא ב”ק וואו די משנה ווערט געבראַכט אַלס מקור אויף דעם וואָס „אמרי אינשי בתר עניא אזלי עניותא”, איז מוכח פון דעם וואָס רש”י באַוואָרנט דאָרט בפירושו „והעשירים לא היו נותנין קלתותיהן לכהן” — אַז די נתינת הסלים פון די עניים צום כהן האָט אַ שייכות מיט זייער עניות'דיקער נתינה פון בכורים; ומזה, אַז זיי גיבן אַוועק די סלים בנוסף צו נתינת הבכורים19. אָבער מאידך, איז דערביי ניטאָ קיין הוכחה צו זאָגן, אַז די סלים זאָלן האָבן אַ שייכות צו די ביכורים עצמם עד כדי כך אַז זייערע נתינות זאָלן דאַרפן זיין אַ מעשה אחד (ואדרבה: עס וואָלט ניט אַזוי מתאים געווען דער לשון „אזלי עניותא” אויב די סלים וואָלטן געווען אַ חלק הנתינה פון די ביכורים).\nג) לויטן פירוש התוי”ט וכו' אין ספרי „שהעניים מביאין מעט ועם הסל יהי' נחשב מתנה” — והיינו, אַז דער סל איז (אַזוי ווי) משלים די ביכורים אַז זיי זאָלן זיין „נחשב מתנה” — איז מסתבר צו זאָגן, אַז נתינת הסלים דאַרף זיין בנתינה („מתנה”) אחת מיט די ביכורים, בכדי אַז די בכורים זאָלן זיין „כדי נתינה”20.\nה. וי”ל, אַז דער רמב”ם לערנט אין דעם אַ פערטן אופן — ובחידוש נוסף אויף די אופנים הנ”ל:\nניט נאָר איז דער סל פאַרבונדן מיט די בכורים אין דער מעשה הנתינה, נאָר ער ווערט ווי איין זאַך אין די בכורים (והבאת הבכורים)21: ווען22 איז די שלימות הבכורים ושל קיום מצותם — הבאת בכורים, בשעת די פירות ווערן געבראַכט אין אַ כלי און די כלי ווערט ווי אַ טייל23 פון די בכורים. בסגנון אחר: די שייכות איז ניט נאָר אין דעם פועל און פעולה (ווי לויט דעם צווייטן און דריטן אופן), נאָר אויך אין דעם נפעל, עס ווערט איין זאַך.\nאון דאָס מאַכט דער רמב”ם קלאָר מיט דעם וואָס ער שטעלט די הלכה „הביאם בכלי מתכות כו'” בהמשך צו דער פריערדיקער הלכה „הבכורים טעונין כלי” (ניט ווי אין דער משנה, וואו דאָס ווערט געבראַכט אַלס אַ באַזונדער דין והלכה אינעם אופן ההבאה פון עשירים ועניים), ד.ה. אַז די כלי (איז פאַרבונדן, און) ווערט איין זאַך מיט די בכורים; און אין דעם דין איז ניטאָ קיין חילוק צווישן איין סוג כלי און אַ צווייטן.\nאון דאָס וואָס דער רמב”ם איז מחלק צווישן „כלי מתכות” און „כלי ערבה וחלף” איז נאָר דערפאַר וואָס ביי „כלי מתכות” איז דאָ אַ דין מיוחד24, כדיוק לשון הרמב”ם „חוזר הכלי לבעליו”25 —",[["19","19","שהובא שם לשון המשנה הסלים והבכורים נותנים* לכהנים."],["20","20","משנה ראשונה בכורים שם. *) כ”ה בש”ס לפנינו. וראה דק”ס שם, שבכל הכ”י ובדפוסים ישנים כו' ניתנין, כבמשנה (או נתונים)."],["21","21","אבל לא בקדושתם (והקליפות וכו' יוכיח) — שלא נמצא בשום מקום חידוש גדול זה."],["22","22","להעיר מחדא”ג מהרש”א ב”ק שם."],["23","23","להעיר מדין תוספת ועיטור בכורים (שברמב”ם שם פ”ב הי”ח) לפי הצפע”נ מהד”ת (ח, ד). וי”ל דשאני עיטור בכורים דמצד חשיבותם אין לומר עליהם דבטלים אגב בכורים לגמרי. ולהעיר גם מב' סוגים בהתורים ובני יונה שהיו מביאים עם הבכורים (ראה רמב”ם הנ”ל הערה 17). ואכ”מ."],["24","24","להעיר ממאירי ב”ק שם: כבר ידעת שהבכורים טעונים הבאה בכלי כו' ומכל מקום אם היו מביאין אותם בכלי מתכות היו הכלים חוזרין לבעלים ואם כו' הסלים לכהנים. שמלשונו משמע שמצד הדין ש„הבכורים טעונים כלי” הי' צ”ל כל הכלים לכהנים."],["25","25","וברע”ב שם: וקלתות של עשירים מחזירים"]]],[1300291164,"ד.ה. מצד די בכורים ומצות הבאתם ווערט די כלי, אויך כלי מתכות25*, איין זאַך מיט די בכורים26, וואָס דוקא דורך דעם ווערט אויפגעטאָן די „מצות עשה להביא בכורים למקדש”27 — ס'איז נאָר וואָס נאָכדעם איז „חוזר הכלי לבעליו”, ער ווערט ניט ממון כהן; משא”כ ביי „כלי ערבה וחלף וכיוצא בהן” — אינו חוזר, די כלי בלייבט איין זאַך מיט די ביכורים אויך שפעטער.\n[און דעם טעם ההפרש יש לומר: ביי כלי מתכות, וויבאַלד אַז די שייכות ביניהם איז נאָר מצד דעם דין „הבכורים טעונין כלי”, דעריבער איז אויך דער פאַרבונד פון דער כלי מיט די פירות פון בכורים נאָר בנוגע לקיום המצוה — הבאת בכורים „בית ה' אלקיך”28; אָבער ביי „כלי ערבה וחלף וכיוצא בהן”, וואָס אויך במציאותם (הטבעית) ועכ”פ בחשיבותם (השווי שלהם) האָבן זיי אַ שייכות, איז דאָס „אהני” צום גדר הכלי שבהם („בכורים טעונין כלי”), אַז דאָס ווערט לגמרי ווי איין זאַך מיט די פירות, ע”ד ווי די קליפה פון די פירות בכורים עצמם].\nו. ע”פ הנ”ל וועט צוקומען הסברה והמתקה אין נאָך כמה שינויים ודיוקים בדברי ובלשון הרמב”ם:\nא) ער איז משמיט די הדגשה וועגן דעם גברא המביא — עשיר ועני, און רעדט נאָר וועגן מעשה ההבאה ביחס להחפצא של הבכורים, „הביאם בכלי מתכות . . הביאם בכלי ערבה וחלף וכו'” — וואָס דאָס איז מובן בפשטות, כנ”ל.\nב) ער איז משנה (און משמיט) דעם לשון המשנה (און אויך פון ספרי וגמרא) „והסלים והבכורים נותנין (ניתנים)29 לכהנים”, זאָגנדיק „הרי הבכורים והסלים לכהנים” — להדגיש, אַז זייער שייכות זל”ז איז ניט מוגבל אין (און צוליב) דער נתינה (להכהן), נאָר זיי זיינען ווי איין זאַך, „הבכורים והסלים”, וואָס באַלאַנגט צום כהן.\nג) ער איז מהפך דעם סדר ווי זיי שטייען אין דער משנה „הסלים והבכורים”30, און שרייבט „הבכורים והסלים”30* — אע”פ אַז „הסלים” איז דער חידוש — ווייל דער לשון „הסלים והבכורים” גיט אַן אָרט צו מדייק זיין אַז די סלים (שטייענדיק פריער) איז אַ באַזונדער ענין פון די ביכורים, און דערפאַר שרייבט דער רמב”ם „הבכורים והסלים”, וואָס דערמיט איז מודגש אַז די סלים זיינען נמשך און כרוך (ווי אַ פרט) פון די בכורים.\nד) ער איז מסיים די הלכה „ואם נטמאו הבכורים אין הסלים לכהנים”31",[["","","להן. וראה תוי”ט וחידושי אנשי שם למשנה בכורים שם. 25*) משא”כ להאופנים הנ”ל (ס”ג), מלכתחילה אין בכלי מתכות דין נתינה לכהן. — ומובן בפשטות הא שבמשנה וספרי לא נזכר כלל מה עושים עם קלתות של כסף כו' דהעשירים."],["26","26","להעיר מהל' שבת שהכלי בטל להנמצא בו ותלוי אך בשיעורו (משנה שבת צג, סע”ב. רמב”ם הל' שבת ספי”ח), גם כלי זהב."],["27","27","לשון הרמב”ם הל' ביכורים רפ”ב. וראה רמב”ם שם ה”כ וברדב”ז שם."],["28","28","משפטים כג, יט. תשא לד, כו. הובא ברמב”ם שם פ”ב ה”כ."],["29","29","ראה לעיל שוה”ג להערה 19. חלופי נוסחאות לספרי (הנ”ל הערה 10)."],["30","30","ועד”ז הובא בב”ק שם. ברדב”ז לרמב”ם שם פ”ג ה”ח מעתיק לשון המשנה „והבכורים והסלים”. אבל לכאורה אין לדייק בזה ברדב”ז, שבפשטות כתב כן אגב שיגרא דלישנא דהרמב”ם, ובפרט דלא מצינו בכל הש”נ דהמשנה שהובאו (בס' המשניות) „הבכורים והסלים”. וגם בסיום לשונו דהרדב”ז שם כתב „והסלים והבכורים”. 30*) כן דייק גם בהון עשיר לבכורים שם."],["31","31","והוא מירושלמי בכורים פ”א ה”ז (לפי גירסת הרמב”ם — ראה כס”מ)."]]],[1300291165,"— בהתאם וכתוצאה פון דעם תוכן ההלכה אַז די „סלים” זיינען איין זאַך מיט די בכורים32, וואָס דערפאַר איז ביי די סלים נוגע ומכריע דער מצב הביכורים וכו'33.\nז. מ'דאַרף נאָך אָבער פאַרשטיין די שייכות (בפנימיות הענינים עכ”פ) צווישן בכורים מיט דער כלי, ובפרט „כלי ערבה וחלף”:\nבכורים זיינען מדגיש דעם תכלית המעלה והשלימות, בפשטות בגשמיות בהם עצמם — מראשית34 גו', „אין מביאין בכורים אלא משבעת המינים האמורים בשבח הארץ . . ואם הביא חוץ משבעת המינין לא נתקדשו”35; וכן בכללות וברוחניות — „אינם נוהגים אלא בפני הבית ובארץ ישראל בלבד”36, די „ארץ אשר גו' תמיד עיני ה”א בה מרשית השנה ועד אחרית שנה”37.\nוכנ”ל אין די מינים גופא, דאַרפן זיי זיין מראשית פון די פירות הכי מובחרים — „אין מביאין לא מתמרים שבהרים ולא מפירות שבעמקים ולא מזיתי שמן שאינם מן המובחר אלא מתמרים שבעמקים ומפירות שבהרים לפי שהן מן המובחר ואם הביא . . לא נתקדשו”38 —\nוביחד עם זה זאָגט מען, אַז „בכורים טעונין כלי”, אַז קדושת בכורים וקיום מצותם איז פאַרבונדן מיט אַ כלי (והגבלה); און נאָכמער: פון סיום ההלכה ברמב”ם „ואם נטמאו הבכורים (וואָס דעמאָלט פעלט אין שלימות המצוה פון בכורים — ס'איז ניטאָ די הנחה לפני המזבח<sup data-n=\"39\">39</sup> אין הסלים לכהנים”, איז מובן אַז ווען די סלים בלייבן יע ביי די כהנים, איז דאָס אַ שלימות און מעלה אין ביכורים, וואָס דאָס איז שייך, כנ”ל, דוקא ביי אַ „כלי ערבה וחלף” — דברים פשוטים (ע”ד פסולת גורן ויקב)!\nובסגנון קצר, ווי קומט עס, אַז ביי בכורים, וואָס זיינען כשמם בכורים, די ערשטע און די בעסטע בשבח הארץ, וואָס דאַרפן געבראַכט ווערן אין בית ה”א, ביז לפני מזבח ה' אלקיך, זאָל די שלימות זיין פאַרבונדן דוקא מיט כלי (ובגלוי יותר — בכלי ערבה וחלף)?!\nח. וי”ל דעם ביאור אין דעם:\nס'איז ידוע40 אַז בכורים זיינען מרמז אויף אידן, וכמ”ש41 „כבכורה בתאנה בראשיתה ראיתי אבותיכם”, און ווי דער צ”צ42 איז מבאר בארוכה, אַז דער ענין פון בכורים ווייזט אויף נשמות ישראל ווי זיי זיינען בשרשן למעלה, וואָס",[["32","32","ועפ”ז יומתק זה שהרמב”ם מכריע כגירסא זו ולא כגירסת הר”ש והרא”ש בבכורים פ”א מ”ח — הובא בכס”מ שם. וע”פ הנ”ל י”ל דלפי הירושלמי (וכגירסת הר”ש והרא”ש) ד„נטמאו הבכורים הסלים נתנין לכהנים דכתיב כו'” — הוי כאופן הא' (או הב') הנ”ל ס”ג. ועצ”ע."],["33","33","ראה (מ”ש בדעת הרמב”ם) מהר”י קורקוס (בביאורו הב') וכס”מ כאן."],["34","34","— כפשש”מ (רש”י, ספורנו ועוד). וע”ד ההלכה ראה: מנחות פד, ב ובפרש”י שם. ספרי ריש פרשתנו (כו, ב). ירושלמי בכורים פ”א ה”ג. פיהמ”ש להרמב”ם בכורים שם."],["35","35","רמב”ם שם ה”ב."],["36","36","רמב”ם שם רפ”ב."],["37","37","עקב יא, יב."],["38","38","רמב”ם שם ה”ג."],["39","39","ראה מהר”י קורקוס לרמב”ם כאן ה”ח (בביאורו הא'). מרה”פ לירושלמי שם."],["40","40","זח”ג רנג, א. וראה ב”ר רפמ”ו. זח”ב קכא, א. ועוד."],["41","41","הושע ט, י."],["42","42","אוה”ת פרשתנו (ע' תתרלג ואילך. תתרלט ואילך). וראה בהנסמן שם."]]],[1300291166,"דאָרטן איז „מחשבתן של ישראל קדמה לכל דבר”43, אויך („קדמה”) לתורה\n[וואָס דערפאַר42 איז דער דין אַז בכורים זיינען קודמים אויך לתרומה44: אע”פ אַז ביידע, סיי תרומה און סיי בכורים, ווערן אָנגערופן „ראשית”45, פונדעסטוועגן זיינען בכורים קודמים לתרומה — ווייל דער ראשית פון תרומה (אותיות „תורה מ”) איז דער ענין התורה (וואָס אויף תורה שטייט46 „ה' קנני ראשית דרכו”), און דער ראשית פון בכורים איז מרמז אויף אידן (וואָס אויף זיי שטייט47 „קדש ישראל לה' ראשית תבואתה”), און כשם ווי „ישראל קדמו לתורה”48, אַזוי זיינען בכורים קודמים לתרומה].\nאון אע”פ אַז די נשמה ווי זי איז למעלה איז „קדמה לכל דבר”, זי שטייט דאָרט אין אַ דביקות באלקים חיים, כמ”ש49 „חי ה' . . אשר עמדתי לפניו”, ביז בבחי' „טהורה היא” — אעפ”כ קומט די נשמה אַראָפּ דאָ למטה דוקא אין אַ „כלי”, נשמה בגוף, וואָס איז מגביל איר גילוי הקשר מיטן אויבערשטן, און נאָכמער — די „כלי” איז מעלים ומסתיר אויף דער דביקות הנשמה באלקות.\nאיז דאָך אָבער ידוע, אַז די ירידה גדולה מאיגרא רמא לבירא עמיקתא איז כדאי, דאָס איז אַ ירידה צורך עלי': און דוקא על ידי ירידתה למטה בכלי הגוף, ווערט אויפגעטאָן אין דער נשמה אַזאַ עלי', אַז זי ווערט דורך דעם נתעלה נאָך העכער פון דעם מצב ווי זי איז געווען בשרשה למעלה50. דורך דעם ווערט אין איר אַנטפּלעקט די אמת'ע בחי' „בכורים” שבה, דאָס וואָס זי איז איין זאַך51 כביכול מיט עצמותו יתברך, ישראל וקוב”ה כולא חד.\nאון כשם ווי דאָס איז בנוגע כללות ירידת הנשמה למטה, אַזוי איז דאָס בפרט אין עבודת האדם דאָ למטה: דער תכלית הכוונה אין עבודת האדם דריקט זיך אויס בעיקר ניט אַזוי אין איר עבודה בענינים רוחניים — אהבה ויראה של הנשמה52 — נאָר דוקא בקיום מצות מעשיות53; דורך מקיים זיין מצות במעשה בפועל, וואָס ווערט געטאָן דוקא מיטן כח הכי תחתון פון גוף, אַזוי אַז די גאַנצע מציאות פונעם גוף ווערט אַ כלי וחלק של קדושת הנשמה — טוט זיך אויף די שלימות העלי' של הנשמה, ובאופן אַז דער גילוי העצמות לעתיד לבא54 בזמן התחי' (בית ה”א) וועט זיין לנשמות בגופים דוקא55.",[["43","43","ב”ר פ”א, ד."],["44","44","וכמו שאומרים בוידוי מעשר שבפרשתנו — ראה פרש”י כו, יג."],["45","45","בכורים: משפטים כג, יט. תשא לד, כו. תרומה: קרח יח, יב (ובפרש”י). שופטים יח, ד (ובפרש”י). פרש”י פרשתנו שם."],["46","46","משלי ח, כב. הובא בפרש”י עה”ת ר”פ בראשית."],["47","47","ירמי' ב, ג. הובא בפרש”י שבהערה הקודמת."],["48","48","תדא”ר פי”ד."],["49","49","מ”א יז, א. יח, טו. מ”ב ג, יד. ה, טז. זח”א רלג, ב. ח”ג סח, ריש ע”ב. וראה לקו”ש חכ”ה ע' 147 הערה 53."],["50","50","ראה לקו”ת במדבר ב, סע”א ואילך. ראה כה, א. כו, א ואילך (ועוד). ושם — שהיא הבחי' ד„לאשתאבא בגופא דמלכא”."],["51","51","ראה המשך תרס”ו ע' תצא ואילך. תקנ ואילך. ועוד."],["52","52","ראה תניא ספ”מ. ובכ”מ."],["53","53","ראה אגרות קודש אדמו”ר מהוריי”צ ח”ג ריש ע' שה. וראה אגה”ק סוס”כ."],["54","54","ראה לקו”ת במדבר שם „כי עיקר גילוי בחי' זו (לאשתאבא בגופא דמלכא) יהי' לעתיד”."],["55","55","לקו”ת בהר מב, ב. ובכ”מ."]]],[1300291167,"וואָס דער טעם דערויף איז, ווי דער אַלטער רבי איז מבאר אין תניא56 (לגבי כללות העולמות), אַז „תכלית השתלשלות העולמות וירידתם ממדרגה למדרגה אינו בשביל עולמות העליונים הואיל ולהם ירידה מאור פניו ית', אלא התכלית הוא עוה”ז התחתון”, וואָס ער איז דער „תחתון במדרגה שאין תחתון למטה ממנו” ווייל „נתאוה הקב”ה להיות לו דירה בתחתונים”. און דוקא דורך דעם וואָס עוה”ז התחתון ווערט אַ דירה לו ית', לו לעצמותו, ווערט אַן עלי' אויך אין גאַנץ סדר השתלשלות, אויך אין די עולמות הכי עליונים57.\nועד”ז איז דאָס בנוגע להנשמה, אַז דוקא דורך ירידתה למטה אין עוה”ז התחתון — בכלי הגוף — און זי פירט דורך די כוונה פון לעשות לו ית' דירה בתחתונים, וואָס דאָס איז דוקא דורך דער פעולה אין עוה”ז, און דאָרט גופא אין דער בחי' „תחתון” שבו, קיום המצות במעשה, ווערט אויפגעטאָן די שלימות ה„טהרה” וה„קדושה”58 פאַר דער נשמה און דעם גוף וגם יחד, און אין דעם גופא באַשטייט איר עלי', וואָס איז נאָך העכער ווי איר מעלה ועילוי לפני ירידתה.\nט. און כשם ווי דאָס איז דער תוכן רוחני (ופנימי) פון ענין הבכורים, עד”ז איז דאָס אין דעם קיום מצות בכורים כפשוטה, אַז דער אופן ווי די בכורים קומען אין „בית ה”א”, „אל המקום אשר יבחר ה”א לשכן שמו שם”59, וואָס דאָס איז שלימות קדושתם, איז דוקא על ידי כלי, און אין „כלי” גופא איז התאחדות הכלי לתמיד אין אַ כלי פון דברים הכי פשוטים ופחותים (אין תחתון למטה ממנו) כלי ערבה וחלף.\nאון דורך דעם עסק אין הלכות בכורים, ווי דאָס איז איין תורה אחת, נגלה דתורה ופנימיות התורה60, און אין דעם זמן ווען מ'לערנט און מען לייענט דאָס אין תורה, וואָס דאָס איז אויך דער זמן פון הבאת בכורים כדבעי (ווען מ'איז מביא וקורא) „בשעת שמחה מחג השבועות עד סוף החג”61, איז מען ממהר קיום הברכה (מיד — במילא62 וועט זיין) אַז „תשנה לשנה הבאה”63, הבאת בכורים בפשטות אין דעם ביהמ”ק השלישי,\nשיבנה במהרה בימינו על ידי משיח צדקנו, ושמחת בכל הטוב64, ושמחת עולם על ראשם65.\n(משיחת ש”פ תבא תשד”מ)",[["56","56","פל”ו."],["57","57","ראה ד”ה ת”ר נר חנוכה תרמ”ג (נדפס בסה”מ תרמ”ג ע' לה ואילך, ובהתמים (חוברת ג') ע' 278 ואילך) ספ”א. לקו”ש חי”ח ע' 33."],["58","58","ראה לקו”ת ראה שם (כו, א). וראה גם המשך תרס”ו שם (ע' תקב ואילך). ועוד."],["59","59","פרשתנו כו, ב."],["60","60","כבזח”ג (קנב, א) דהם גוף ונשמה."],["61","61","לשון הרמב”ם שם פ”ד הי”ג."],["62","62","כידוע פירוש כ”ק מו”ח אדמו”ר ב„לשנה הבאה בני חורין” (ספר השיחות תש”ה ע' 83)."],["63","63","פרש”י פרשתנו כו, טז."],["64","64","פרשתנו כו, יא. הובא ברמב”ם שם."],["65","65","ישעי' לה, יוד. נא, יא."]]],[1300291168,"<h3>תבא ב</h3>\nא. אין הלכות בית הבחירה1 זאָגט דער רמב\"ם: „כל אבן שנפגמה כדי שתחגור בה הציפורן כסכין של שחיטה הרי זו פסולה לכבש ולמזבח שנאמר2 אבנים שלימות תבנה את מזבח ה'\". און פירט אויס די הלכה: „וכן אבני ההיכל והעזרות שלמות היו\".\nדערנאָך זאָגט דער רמב\"ם3: אבני היכל ועזרות שנפגמו או שנגממו פסולין ואין להן פדיון כו' (און ערשט נאָכדעם זאָגט ער דעם דין פון פגימה במזבח לאחרי שנבנית, כדלקמן סעיף ב).\nבפשטות לערנט מען אַז ב„אבני היכל ועזרות שנפגמו\" איז דער שיעור הפגימה אויך „כדי שתחגור בה הציפורן\" פונקט ווי אין דער ערשטער הלכה ביי „אבן שנפגמה\" וואָס איז פסול לבנין הכבש והמזבח. און דאָס וואָס דער רמב\"ם זאָגט ניט דעם שיעור אין דער הלכה, איז עס ווייל עס קומט בהמשך צו דער פריערדיקער הלכה, במילא איז ניט נויטיק צו איבער'חזר'ן דעם שיעור תיכף נאָכאַמאָל.\nס'איז אָבער דאָ מפרשים4 וואָס זיינען מדייק ניט אַזוי: פון דעם וואָס ביי די „אבני ההיכל והעזרות\" זאָגט דער רמב\"ם נאָר „שלימות היו\" און זאָגט ניט (אין דער הלכה שלאח\"ז) דעם שיעור פון חגירת הציפורן (ובריש דבריו שרייבט ער מפורש, אַז דער שיעור פגימה באבן (כדי שתחגור כו') פסל'ט (נאָר) לכבש ולמזבח) איז מוכח, אַז ביי זיי איז דער שיעור ניט פאַרבונדן מיט חגירת הצפורן5.\n(און מ'ברענגט אַ ראי' לזה: ביי די אבני ביהמ\"ק שטייט מפורש6, אַז זיי זיינען אויסגעהאַקט געוואָרן דורך אַ שמיר — און אין תוס'7 איז מבואר אַז דורך אַ שמיר קענען די אבנים ניט אַרויסקומען אינגאַנצן גלאַט אַז אין זיי זאָל אפילו ניט זיין קיין פגימה „כדי שתחגור בה הציפורן\")8.\nב. נאָך די צוויי הלכות הנ\"ל (ולאחרי וואָס ער זאָגט דעם דין פון „אבן שנגע בה הברזל . . והבונה כו'\") זאָגט דער רמב\"ם בהלכה בפ\"ע9: אבן שנפגמה או שנגע בה ברזל אחר שנבנית במזבח או בכבש אותה האבן פסולה והשאר כשירות.\nדערפון וואָס דער רמב\"ם זאָגט אויך דאָ ניט קיין שיעור, ובפרט אַז ער איז מפסיק מיט „אבני היכל ועזרות שנפגמו כו'\" וואָס (לפי המפרשים הנ\"ל) באַ זיי",[["1","1","פ\"א הי\"ד."],["2","2","פרשתנו כז, ו."],["3","3","הלכה טו."],["4","4","מים חיים (להפר\"ח) על הרמב\"ם כאן."],["5","5","וממשיך (הפר\"ח): ולא נתבאר בתלמוד כמה שיעור פגימתן ולפיכך לא הזכירו הרב."],["6","6","גיטין סח, א־ב. סוטה מח, ב."],["7","7","ד\"ה וכמה — חולין יח, א (וש\"נ) — הובא בכס\"מ לרמב\"ם הל' ביהב\"ח כאן (וראה חידושים וביאורים מהיעב\"ץ לרמב\"ם שם פ\"א הי\"ג)."],["8","8","אמנם מתוס' שם בסופו (ובסוכה מט, א סד\"ה שכל; זבחים נד, ב סד\"ה אבנים) משמע, דגם באבני ביהמ\"ק פסול בחגירת הצפורן — ראה שירי קרבן לירושלמי סוטה פ\"ט הי\"ג שהקשה על הפר\"ח הנ\"ל. וראה מנ\"ח מצוה צה בתחלתה מש\"כ בדעת הרמב\"ם. אבל כדברי הפר\"ח (במים חיים) כתב גם במהר\"י קורקוס על הרמב\"ם כאן (נדפס מכת\"י ברמב\"ם הוצאת שולזינגער נ.י. תש\"ז, ובספר בפ\"ע נ.י. תשל\"ג)."],["9","9","הט\"ז."]]],[1300291169,"איז דער שיעור פגימה אַנדערש ווי פריער, איז משמע, אַז אויך באַ אבן מזבח לאחרי שנבנית במזבח, איז דער שיעור פגימה ניט דער זעלבער.\nואע\"פ אַז בפשטות וואָלט מען געדאַרפט אָננעמען אַז ס'איז דער זעלבער שיעור ווי אין דער ערשטער (געבראַכטער) הלכה, וואו דער רמב\"ם זאָגט דעם שיעור „כל אבן שנפגמה כדי שתחגור כו' פסולה לכבש ולמזבח\" — יש לומר אַז עס איז דאָ אַ חילוק צווישן די אבנים ווי זיי שטייען לבנין המזבח או — לאחרי שנבנו:\nווייבאַלד אַז דער פסול פון פגימה ווערט אָפגעלערנט (ווי דער רמב\"ם ברענגט) פון פסוק „אבנים שלימות תבנה את מזבח ה'\" וואָס רעדט וועגן בנין המזבח10, איז יש מקום לומר אַז אחר שנבנה המזבח איז דער שיעור הפגימה ניט דער זעלבער11.\nאמת טאַקע אַז אין גמרא12 שטייט דער שיעור „כדי שתחגור בה הצפורן\" לגבי „פגימת המזבח\" — וואָס בפשטות רעדט זיך וועגן די אבני המזבח לאחרי שנבנו בהמזבח13 —\nאָבער פון דעם גופא וואָס דער רמב\"ם איז דאָ משנה פון לשון הגמרא (כאָטש בדרך כלל איז ער מעתיק דיני הגמרא „כצורתם וכלשונם\"<sup data-n=\"14\">14</sup> און זאָגט דעם שיעור פון פסול פגימה „כדי שתחגור בה הציפורן\" דוקא בשייכות לבנין הכבש והמזבח, ע\"פ הפסוק „אבנים שלימות תבנה את מזבח ה'\" — און האָט ניט אויסגעשטעלט די דינים באופן אַז דער שיעור פון חגירת הצפורן זאָל כולל זיין בפירוש15 אויך די אבנים לאחרי שנבנו בהמזבח ווי אין גמרא — איז משמע, אַז ביי די אבנים איז דער שיעור (לדעת הרמב\"ם) ניט „כדי שתחגור בה הצפורן\".\nג. עס איז אָבער שווער צו אָננעמען חילוק הנ\"ל בדעת הרמב\"ם (אַז אבנים שלימות תבנה גייט נאָר אויף די אבנים לבנין המזבח), וואָרום דער רמב\"ם ברענגט דאָך ניט קיין אַנדער לימוד אויף דעם פסול פון אַן אבן שנפגמה אחר שנבנית במזבח.\n— דער רמב\"ן16 ברענגט אַז אויף די אבני מזבח לאחר שנבנו במזבח האָט מען טאַקע אַן אַנדער לימוד „וזבחת עליו את עולותיך ואת שלמיך וגו'17 וכי עליו אתה זובח אלא בזמן שהוא שלם ולא בזמן שהוא חסר\"18, ובלשונו „דאי מאבנים שלימות ה\"א ה\"מ בשעת בנין לכך נאמר עליו\".\nאון ווייבאַלד דער רמב\"ם (דאָ — בהל'",[["10","10","ראה רמב\"ן שהובא לקמן בפנים."],["11","11","להעיר מהפירוש במפרשים (פי' הא' בחי' היעב\"ץ להל' ביהב\"ח כאן הט\"ז. צפע\"נ תרומות ד, ג. השלמה יח, א (נעתקו בצפע\"נ המלוקט להל' ביהב\"ח כאן)) בדברי הרמב\"ם כאן, דזה שרק אותה האבן פסולה והשאר כשרות הוא דוקא כשנבנה בכשרות ונפגם אחר שנבנית במזבח, אבל בנאו מתחלה אפי' באבן אחת פגומה (שבהלכה יד) כולו נפסל כיון שנעשה בפסול."],["12","12","חולין יז, סע\"ב ואילך."],["13","13","פרש\"י חולין שם בסוף העמוד. וברגמ\"ה חולין שם (יח, רע\"א): כדי פגימת המזבח שאם הי' מזבח פגום נפסל מלהקריב עליו. וראה להלן בפנים (מרמב\"ן) ובהערה 20."],["14","14","יד מלאכי כללי הרמב\"ם אות ה. וש\"נ."],["15","15","ובפרט שהפסיק ביניהם באבני היכל ועזרות אשר (לפי המפרשים הנ\"ל) שיעורם שונה, וכנ\"ל סעיף א."],["16","16","חולין שם סד\"ה וכולן פגימתן („וי\"מ\"). וראה גם ריטב\"א חולין שם (יח, רע\"א סד\"ה כדי)."],["17","17","יתרו כ, כא."],["18","18","לשון רש\"י חולין שם יז, סע\"ב — מזבחים נט, א (כמ\"ש רש\"י)."]]],[1300291170,"ביהב\"ח) לערנט עס ניט אָפ פון יענעם פסוק19 דאַרף מען בפשטות זאָגן, כנ\"ל, אַז אויך בנוגע די אבנים לאחר שנבנו במזבח איז דער מקור פון פסול פגימה פונעם פסוק20 „אבנים שלימות תבנה את מזבח ה'\", וואָס ער ברענגט אין דער פריערדיקער הלכה21.\nוהדרא קושיא לדוכתא — פאַרוואָס זאָגט ניט דער רמב\"ם דאָ דעם שיעור הנ\"ל „אבן שנפגמה כשיעור זה\" (וכיו\"ב)22,\nוואָס דערפון איז משמע אַז דאָ איז ניט דער זעלבער שיעור?\nד. ויש לומר, דהנה ידוע, אַז (אויך) אין דעם שיעור „כדי שתחגור בה הציפורן\" (בנוגע סכין של שחיטה) איז דאָ אַ שקו\"ט ודיעות23 אין דעם גודל השיעור, ביז אַז יש אומרים, אַז דער שיעור פון חגירת הצפורן מיינט אפילו אַ פגימה כל שהיא, אָבער אפילו לויט די דיעות24 וואָס זיינען מפרש (אין רמב\"ם) אַז דאָס איז דער שיעור הכי קטן, אַ „כל שהוא\"25, אעפ\"כ דערפון וואָס דער רמב\"ם זאָגט דאָ ניט דעם לשון „כל שהוא\"26 וכיו\"ב נאָר „כדי שתחגור בה הציפורן כסכין של שחיטה\" איז מובן אַז דאָס מיינט דער רמב\"ם מדייק זיין אַז דאָס האָט אַ שיעור מסוים27.\nוי\"ל די הסברה בזה: דעם שיעור כל שהוא געפינט מען אין רמב\"ם כמה פעמים, ולדוגמא: „יין שנתנסך לעכו\"ם אסור בהניי' והשותה ממנו כל שהוא לוקה . . וכן האוכל כל שהוא מתקרובת עכו\"ם מבשר או מפירות אפילו מים ומלח האוכל מהן כל שהוא לוקה\"28. ועד\"ז זאָגט דער רמב\"ם אין הל' עבודה זרה לגבי ע\"ז29 ולגבי שלל פון עיר הנדחת30.\nדער ראָגאַטשאָווער31 איז מוסיף לציין צום רמב\"ם הל' שבת32 וואָס דאָרטן",[["19","19","והביאו (הא דזבחים שם) רק בהל' פסולי המוקדשין (פ\"ג הכ\"ב — נעתק לקמן סוס\"ז) לגבי הפסול דקדשים „שהיו שם שחוטין\"."],["20","20","וכפשטות דברי רש\"י חולין (יח, רע\"א), הובא בתוס' סוכה מט, א רד\"ה שכל — בתחלתו. וכהפי' ברמב\"ן שם. חי' הרשב\"א חולין שם ד\"ה פגימת. וראה גם תוס' חולין יז, ב. פי' הרא\"ש מדות פ\"ג מ\"ד. ריטב\"א חולין שם."],["21","21","ולהעיר ממאירי חולין שם שכתב הדרשה דאבנים שלימות לגבי הבנין ואח\"כ ממשיך „ואף אם נפגמה בשיעור זה אחר הבנין נפסל\"."],["22","22","ודוחק גדול לומר, שלא הוצרך לומר כאן שיעור הפגימה (הפוסלת) — כי החידוש בהלכה זו הוא (לא ד„אותה האבן פסולה\" — שזה מובן מאליו מהלכה יד — כ\"א) רק ד„השאר כשרות\" (וראה בהנסמן לעיל הערה 11) — כי מפשטות לשון הרמב\"ם משמע שבא להודיע גם דין זה ד„אותה האבן פסולה\"."],["23","23","ראה ראשונים לחולין שם. נ\"כ הטושו\"ע יו\"ד סי\"ח ס\"ב. וראה בפרטיות קו\"א לשו\"ע אדה\"ז יו\"ד שם. שו\"ת הצ\"צ יו\"ד סט\"ז ובפסקי דינים מא, ב ואילך (הנסמן עה\"ג בשו\"ע שם)."],["24","24","ראה דרישה (סק\"א) ופר\"ח (השלם — סק\"ה) יו\"ד שם. פמ\"ג (משב\"ז) שם סק\"ב. פלתי סק\"א. וראה שו\"ת צ\"צ שם."],["25","25","ל' השו\"ע שם. אלא שבשו\"ע שם „ובלבד שתאגור בה כל שהוא אפי' חוט השערה\", והוא מהרשב\"א בתורת הבית בית א' שער ב. וראה בהנסמן בהערה 23, 24."],["26","26","ובקרית ספר להמבי\"ט הל' ביהב\"ח כאן כתב „ובפגימה כל שהיא כחגירת הצפורן לא הויא אבן שלימה\"."],["27","27","ובפרט שבהל' שחיטה (פ\"א הי\"ד. הכ\"ג. וראה מ\"מ להי\"ד) לא כתב הרמב\"ם דהשיעור פגימה בסכין הוא כדי שתחגור. וראה תבואת שור שם סק\"ה־ו. צפע\"נ הל' שחיטה שם (נעתק בצפע\"נ (המלוקט) להל' ביהב\"ח כאן). וראה המובא בלשד השמן על הרמב\"ם הל' ביהב\"ח כאן."],["28","28","הל' מאכלות אסורות פי\"א ה\"א."],["29","29","פ\"ז הט\"ו."],["30","30","פ\"ד ה\"ז."],["31","31","הל' מאכלות אסורות שם בסופו (צב, ד)."],["32","32","פי\"ח ה\"ה."]]],[1300291171,"ברענגט דער רמב\"ם כמה דברים וואָס דער איסור הוצאה שלהם איז „בכל שהוא\"33.\nאמנם (לכאורה) איז דאָ אַ חילוק ביניהם, ובהקדם, אַז דעם גדר איסור כל שהוא קען מען לערנען אויף צוויי אופנים:\nא) אַז דאָס איז אַ שיעור אין דעם באַשטימטן איסור — ס'זיינען דאָ איסורים וואָס שיעורם בגרוגרות, בכזית כו' און אויך אַזעלכע וואָס זייער שיעור האיסור איז ב„כל שהוא\".\nב) ס'איז אַן איסור שאין לו שיעור, און דערפאַר איז דער איסור „בכל שהוא\", — ניט בגדר שיעור34.\nה. און דאָס איז דער חילוק פון גדר כל שהוא באַ איסור הוצאה בשבת און כל שהוא אין איסור ע\"ז:\nבנוגע להוצאה בשבת וואָס איסור הוצאה האָט בדרך כלל אַ שיעור איז מובן, אַז אָט די דברים וואָס איסורם איז בכל שהוא איז עס דערפאַר וואָס ביי זיי איז „כל שהוא\" אַ שיעור — צי ווייל אויך „כל שהוא\" פון די דברים איז חשוב מצ\"ע, וע\"ד „פלפל כל שהוא, עיטרן כל שהוא ריח טוב כל שהוא וכו'\"35, אָדער דערפאַר וואָס „מצניעין אותם לגניזה\"35 — בני אדם זיינען מחשיב (מצניע) די דברים אויך אַ כל שהוא.\nמשא\"כ בנוגע לעיר הנדחת ועד\"ז בע\"ז בכלל, וואָס אויף דעם שטייט36 „ולא ידבק בידך מאומה מן החרם\"37, איז דער איסור פון „כל שהוא\" ניט דערפאַר וואָס „כל שהוא\" איז אַ גדר פון שיעור, נאָר ווייל ביים איסור ע\"ז איז ניטאָ קיין שיעור — „מאומה\". ובלשון הרמב\"ם38: כיון שאיסור זה משום עכו\"ם הוא אין לו שיעור ונאמר בעבודת כו\"ם ולא ידבק בידך מאומה מן החרם.\nו. עפ\"ז יש לבאר אויך דברי הרמב\"ם אין הל' ביהב\"ח, ובהקדם:\nס'איז ידוע39 אַז ס'איז ניט דרכו של הרמב\"ם צו זאָגן בפירוש דינים מחודשים (מלבד די מקומות וואו ער זאָגט „ויראה לי\", וואָס מ'געפינט זיי אין רמב\"ם במספר מצומצם, כיוצאים מן הכלל<sup data-n=\"40\">40</sup>, אָבער בכ\"מ איז ער משנה לשונו ומסדר דבריו באופן כזה, אַז מ'קען פון דעם אַרויסלערנען אַ חידוש בדין פרטי.\nועד\"ז יש לומר בנדו\"ד: מיט דעם וואָס דער רמב\"ם איז מדייק צו זאָגן דעם שיעור פון פגימת האבן „כדי שתחגור בה הציפורן\" דוקא בנוגע לבנין אבן במזבח ובכבש — אַנדערש ווי אין ש\"ס, כנ\"ל, און ביי „אחר שנבנית",[["33","33","וראה בהמשך דברי הצפע\"נ הל' מאכא\"ס שם."],["34","34","י\"ל הנפק\"מ: בשיעור — גדרו שאפשרי שיוגרע; כל שהוא — גדרו להיפך: כל שהוא. ונפק\"מ כשנפל מהתערובה לתערובה שני' וכו'. וראה פלוגתת הט\"ז (יו\"ד סצ\"ב סקט\"ז) והש\"ך (נקודת הכסף שם). ועפ\"ז אי\"ז פלוגתא במציאות. וראה פמ\"ג (משב\"ז) שם. שו\"ע אדה\"ז או\"ח סתמ\"ז סט\"ז. ואכ\"מ."],["35","35","ל' הרמב\"ם הל' שבת שם."],["36","36","ראה יג, יח. הובא ברמב\"ם הל' מאכא\"ס שם (ה\"ב) כדלקמן בפנים (וכן בהל' ע\"ז פ\"ד שם)."],["37","37","ראה ציוני מהר\"ן על הרמב\"ם הל' מאכא\"ס שם (ה\"א)."],["38","38","הל' מאכא\"ס שם ה\"ב."],["39","39","ראה יד מלאכי שבהערה 14."],["40","40","מאה פעמים ועוד כתב הרמב\"ם בספרו „יראה לי\" (נסמנו במבוא לרמב\"ם צילום דפוס רומי רמ (ירושלים תשט\"ז — ע' ו)) שאינו בערך לרבבות ההלכות שבספרו. ועוד ועיקר — בהנ\"ל כולל גם מה שפסק והכריע כו', ובפנים מדובר ע\"ד חידושי דינים."]]],[1300291172,"במזבח\" איז ער ניט מוסיף „אבן שנפגמה כשיעור זה\" וכיו\"ב (און אויך דערמיט וואָס ער שטעלט אַריין צווישן ביידע הלכות בנוגע אבני המזבח דעם דין פון „אבני היכל ועזרות שנפגמו או שנגממו פסולין כו'\") —\nאיז ער מרמז (ומדגיש) אַז באַ „אבן שנפגמה כו' אחר שנבנית במזבח\" קומט צו נאָך אַ פסול וואָס איז ניט פאַרבונדן מיטן שיעור „כדי שתחגור בה הציפורן כסכין של שחיטה\", נאָר דער פסול איז ב„כל שהוא\", בגדרי „כל שהוא\" כנ\"ל.\nוהטעם לחילוק זה: דער רמב\"ם זאָגט אין הל' ביהב\"ח אין דער הלכה שלאח\"ז41 „הנותץ אבן אחת מן המזבח או מכל ההיכל או מבין האולם ולמזבח דרך השחתה לוקה שנאמר42 ונתצתם את מזבחותם וגו' לא תעשון כן לה\"א\". און ווייבאַלד אַז דער איסור איז פאַרבונדן און קומט בקשר לע\"ז\n— און ווי דער רמב\"ם איז מדגיש אין הלכות יסודי התורה43: „הסותר אפילו אבן אחת דרך השחתה מן המזבח או מן ההיכל או משאר העזרה לוקה שנאמר בעבודת כוכבים כי את מזבחותם תתוצון44 וכתוב לא תעשון כן לה\"א\" —\nקומט אויס אַז דער איסור איז חל אויך ווען מען איז „נותץ\" אפילו כל שהוא מאבן אחת מן המזבח וכיו\"ב — און נותץ כל שהוא איז היינו פוגם (אפילו כל שהוא), און ווי עס שטייט אין אוה\"ח45 „שלא אמר בדיוק אבן אחת אלא שעושה בנתיצתו רושם בבנין\"46.\nז. ועפ\"ז איז מובן דער חילוק צווישן אבן שנפגמה פאַרן איינגעבויט ווערן אין מזבח און כבש, און אבן שנפגמה כו' אחר שנבנית במזבח או בכבש:\nדער פסול פון אבן שנפגמה קודם הבנין איז מצד דעם ציווי וחיוב „אבנים שלימות תבנה את מזבח ה'\", אַז די אבנים דאַרפן זיין „שלימות\" ביי דער בני' — און דערפאַר איז דאָ אַ שיעור אין דער פגימה, אַז דאָס זאָל זיין גענוג צו פאַררעכנט ווערן ווי אַ חסרון וקלקול אין „שלימות\" האבן47, און דער שיעור איז „כדי שתחגור בה הציפורן כסכין של שחיטה\".\nמשא\"כ אבן שנפגמה אחר שנבנית במזבח, ווייבאַלד דאָס רירט אָן דעם ענין פון „לה\"א\", ס'איז „מזבח ה'\", איז דאָס פאַרבונדן ניט נאָר מיט'ן חיוב פון „אבנים שלימות תבנה את מזבח ה'\"48 נאָר אויך מיטן גדר פון נתיצת המזבח, וואָס איז פאַרבונדן מיט „לא תעשון כן (ווי צו מזבח דע\"ז) לה\"א\":",[["41","41","פ\"א הי\"ז."],["42","42","ראה יב, ג־ד."],["43","43","פ\"ו ה\"ז."],["44","44","תשא לד, יג (ועד\"ז ואתחנן ז, ה). וצ\"ע שאינו מביא הפסוק דראה — ובפרט שבהמשך ההלכה מביאו. וראה ספר המדע (ירושלים, תשכ\"ד) מב' דפוסים, שהכוונה להפסוק דראה. ואכ\"מ."],["45","45","עה\"ת ראה שם."],["46","46","הובא במנ\"ח מצוה תלז (מה, ב). ובהמשך לזה מביא מתוס' מכות (כב, רע\"א) שכתבו גבי עצי הקדש דהשורף חייב אף שאינו שוה פרוטה ופשוט דה\"ה א\"צ שום שיעור כלל דעל כל שהוא חייב כו' דאיסורי ע\"ז הוא בכ\"ש ועז\"נ לא תעשון וכו' וחייבים על כ\"ש\"."],["47","47","ולפ\"ז מש\"כ ברש\"י חולין (הנ\"ל הערה 20) „באבנא כל דהוא כדכתיב אבנים שלימות\" (וראה רמב\"ן, רשב\"א וכו' שבהערה הנ\"ל), אין הכוונה כל שהוא ממש — שלא בגדר „שיעור\", כ\"א „כל שהוא\" לגבי השיעור דטפח או כזית שבפגימת „סיד\" המבואר שם."],["48","48","שבזה הוא המדובר בחולין (בשיעור כדי שתחגור בה הצפורן)."]]],[1300291173,"ובמילא איז כשם ווי ביי ע\"ז איז דער איסור בכל שהוא, ניט אַ גדר שיעור כנ\"ל, עד\"ז איז די פגימה אין אבן שנבנית במזבח ניט בגדר שיעור, אפילו ניט אַ שיעור הכי קטן „כדי שתחגור בה הציפורן\" (אפילו לויט די דיעות אַז עס איז אַ כל שהוא), נאָר אבן שנפגמה סתם, אָן קיין שיעור48*, איז „אותה האבן פסולה\"49.\n[ועפ\"ז יש לומר אַז אויך בנוגע דאָס וואָס דער רמב\"ם זאָגט ניט אַ שיעור ביי „אבני היכל ועזרות שנפגמו או שנגממו\", איז עס ניט דערפאַר וואָס שיעור פגימתן איז גרעסער ווי „כדי שתחגור בה הציפורן\" (כנ\"ל ס\"א), נאָר אדרבא, ווייבאַלד אַז די אבנים זיינען געוואָרן אַ חלק פון היכל ועזרות50 — איז דער איסור פגימה ניט בגדר שיעור, נאָר בכל שהוא50*].\nואע\"פ אַז דער לאו ומלקות פון נתיצת אבן איז געזאָגט געוואָרן דוקא ביי פעולת האדם: הנותץ אבן אחת מן המזבח . . שנאמר . . לא תעשון כן לה\"א, און נאָכמער — דוקא „דרך השחתה\" — איז אָבער מובן אַז אויך די נתיצה (פגימה) הנפעלת אין דער חפצא, כשלעצמה, אפילו ניט דורך פעולת הגברא ובדרך השחתה, האָט אַ שייכות און איז ע\"ד ווי בגדר ביטול ע\"ז:\nכשם ווי די מצוה פון „ונתצתם את מזבחותם גו'\" באַשטייט ניט נאָר אין מעשה הניתוץ פון דעם גברא, נאָר אויך אין ביטול מציאותו פון „מזבחותם\", עד\"ז איז דאָס אויך בהאיסור פון „לא תעשון כן לה\"א\", אַז דער לאו ומלקות איז טאַקע אויף עשיית האדם, אָבער דער תוכן וגדר האיסור איז כולל און שולל יעדן אופן פון נתיצת האבן, אַז יעדע זאַך פון „מזבח לה' אלקיך\" זאָל ניט ווערן נתוץ ובטל.\n[ויש להוסיף בזה ע\"פ דברי הצפע\"נ51 אין דעם גדר פון „לא תעשון כן לה\"א\", אַז דער חיוב דערביי איז ניט נאָר וואָס ער איז מפקיע די קדושה52 פון דעם אבן, נאָר אויך וואָס עי\"ז ווערט נפסל דער מזבח (אָדער עס ווערט אַ חסרון",[["","","48*) ואף ש„מזבח שנפגם מבניינו [היינו מסיד המזבח כו'] . . פחות מטפח כשר\" (רמב\"ם הל' ביהב\"ח ספ\"ב) — י\"ל ע\"פ מ\"ש הריטב\"א (חולין שם) ד„סיד שהוא מקובץ מדברים נפרדים וטבעו להפריד כל דהו כשמתיבש ואם אדם מקפיד בו הרבה לא תמצא מעולם מזבח כשר\". וי\"ל, דכיון שסיד אינו דבר שלם אלא מקובץ מדברים נפרדים, לא חל עליו גדר „פגימה\" בפחות מטפח, משא\"כ באבן דגם אם נפגם כ\"ש הוי אבן פגומה. ועצ\"ע."],["49","49","אפילו את\"ל (ראה לעיל ס\"ב־ג) שלהרמב\"ם גם באבני מזבח לאחרי שנבנית במזבח הפגימה היא „כדי שתחגור בה הציפורן\", יש לומר, דזה גופא שלא כתבו מפורש בדין זה הוא, לפי שבאבני מזבח, זה שהפגימה פוסלת כדי שתחגור בה צפורן, הוא לא בגדר שיעור פגימה, אלא סימן על פגימה כל שהיא."],["50","50","ועל דין זה לא קשה קושיית התוס' (דלעיל הערה 8) איך נבנה ביהמ\"ק ע\"י שמיר, כי דין זה באבני היכל כו' הוא רק לאחרי שנבנית, משא\"כ בהשמיר שהי' לפני הבנין. 50*) אבל זה שהרמב\"ם סתם (בהלכה יד) „וכן אבני ההיכל והעזרות שלימות היו\" (וקאי על האבנים קודם שנבנו) — הוא לפי ששיעור פגימתן גדול יותר מ„כדי שתחגור בה הצפורן\", דאל\"כ איך בנו המקדש ע\"י שמיר (כנ\"ל ס\"א מהפר\"ח). ועוד י\"ל, שכאן לא הוצרך הרמב\"ם לפרש השיעור, כי סמיך על מ\"ש בתחילת הלכה זו (משא\"כ הדין ד„אבני היכל ועזרות שנפגמו\" שבא בהלכה בפ\"ע). וראה מנ\"ח הנ\"ל הערה 8 (שתי' קושיית התוס' לדעת הרמב\"ם)."],["51","51","הל' יסודי התורה שם. וראה גם מהד\"ת לד, סע\"ד. עד, ג. ועוד (נעתקו בצפע\"נ המלוקט להל' ביהב\"ח כאן)."],["52","52","וראה מנ\"ח שבהערה 46."]]],[1300291174,"<h3>אין דער עזרה כו')53 —</h3>\nאיז עד\"ז ביי „אבן שנפגמה . . אחר שנבנית במזבח\", זיינען דאָ די ביידע פרטים: סיי די הפקעת הקדושה פון דעם אבן — „אותה האבן פסולה\"; און סיי דער ביטול פון קדושת מזבח בנוגע להקרבה54, ווי דער רמב\"ם זאָגט אין הל' פסולי המוקדשין55 „שהרי אין שם מזבח לזרוק עליו ונאמר וזבחת עליו . . בתקונו לא פגום\"56.\n(ומעין זה ועד\"ז ביי „אבני היכל ועזרות שנפגמו או שנגממו\" שבהלכה טו)].\nח. דער ענין פון שיעור פגימת האבן לאחר שנבנית במזבח איז פאַרבונדן אויך מיטן נאָמען פון די הלכות — „בית הבחירה\"57:\nבית הבחירה איז דאָך ע\"ש „המקום אשר יבחר ה'\"58, און דער רמב\"ם איז דערמיט מדגיש (ווי גערעדט שוין פיל מאָל)59 אַז דער עיקר מעלת המקדש איז דאָס וואָס ער איז אַ „בית הבחירה\", בחירת הקב\"ה:\nס'איז ידוע60 אַז אמת'ע בחירה איז דוקא ווען דער אויסקלייב פון אַ זאַך קומט דורכאויס מצד בחירתו החפשית פונעם בוחר — ניט צוליב וועלכער ס'איז מעלה וחשיבות וואָס איז דאָ אין דעם דבר הנבחר, און בכלל ניט צוליב וועלכע ס'איז סיבות וטעמים ונטיות, וועלכע זיינען מכריח דעם בוחר.\nוואָס מצד דעם קומען אַרויס צוויי ענינים:\nא) ווען אַ מענטש קלייבט אויס אַ זאַך צוליב איר מעלה וחשיבות, איז מובן אַז די מדה ותוקף פון איר בחירה דורכ'ן בוחר איז לויט דער מאָס פון איר מעלה און חשיבות:\nווען די בחירה איז אָבער ניט מצד מעלת הדבר, נאָר ווייל דער בוחר האָט אויסגעקליבן די זאַך בבחירתו החפשית, איז דאָס באופן אַז ס'איז ניט פאַרבונדן מיט קיין מדה ושיעור (און במילא אויך אַן ענין תמידי).\nב) דערפון איז אויך פאַרשטאַנדיק אַז בשעת עס ווערט אַ חסרון אין דעם דבר הנבחר — איז אויב דער רצון ובחירה פון דער זאַך איז צוליב איר מעלה, ווענדט זיך דאַן אין דעם „שיעור\", אויף וויפל דער חסרון איז פוגם אין דער מעלה הנבחר; אָבער אויב די בחירה צו דער זאַך קומט מצד דעם בוחר, איז דעמאָלט ניטאָ קיין חילוק אין דעם שיעור החסרון — ס'איז ניט די זאַך וועלכע ער האָט בוחר געווען.",[["53","53","ועיין בצפע\"נ שם שעפ\"ז מתרץ שינוי ל' הרמב\"ם בין הל' יסוה\"ת שכתב „הסותר\" ומוסיף „או משאר העזרה\", ובהל' ביהב\"ח כ' „הנותץ\" ולא כתב „מן העזרה\"."],["54","54","ראה מאירי שבהערה 21, שמוסיף שם „(נפסל) כלו\"."],["55","55","נסמן בהערה 19."],["56","56","ומטעם זה הוסיף הרמב\"ם כאן בהט\"ז „והשאר כשרות\", כי אף שאין שם מזבח לזרוק עליו, דהמזבח נפסל, שאר האבנים נשארו כשרות, ובמילא אפשר להכשיר המזבח ע\"י חליפת אבן הפגומה. וראה בהנסמן לעיל הערה 11."],["57","57","כן קוראם הרמב\"ם, אף דלשון הכתוב שהביא לראי' (ריש הל' ביהב\"ח) הוא „ועשו לי מקדש\" (תרומה כה, ח), ובעצמו כותב בכ\"מ הלשון „(בית ה)מקדש\". וראה לקו\"ש חי\"ט ע' 143 ואילך; חכ\"ד ע' 83 ואילך — ובהנסמן שם."],["58","58","ראה יב, יא. וכן בפרשתנו כו, ב. ועוד. וראה לקו\"ש חכ\"ד שם (ע' 79 ואילך). וש\"נ."],["59","59","ראה לקו\"ש שבהערה 57."],["60","60","ראה לקו\"ש חי\"ז ע' 89 ואילך. וש\"נ."]]],[1300291175,"ט. ועפ\"ז יובן אויך בנוגע לביהמ\"ק: ווייבאַלד אַז עיקר מעלתו של הבית איז דאָס וואָס ער איז „בית הבחירה\", דערפאַר איז אַ חסרון און פגם אינעם בית ניט פאַרבונדן מיט אַ שיעור, נאָר אפילו אַ משהו חסרון רירט אָן אין עיקר ענינו פון בית הבחירה.\nועפ\"ז יומתק אויך וואָס דער ענין הנ\"ל, אַז די פגימה איז בכל שהוא, איז מודגש בעיקר בנוגע למזבח (וכנ\"ל וואָס דער רמב\"ם איז משנה און זאָגט דעם שיעור „כדי שתחגור בה הציפורן\" ניט (ווי אין גמרא) בנוגע „אבן אחר שנבנית במזבח\", נאָר בנוגע אבן לבנין המזבח),\nווייל בנוגע למזבח59 איז געווען אַ בחירה מיוחדת סיי בנוגע למקומו ווי דער רמב\"ם61 איז מדגיש במזבח „המזבח מקומו מכוון ביותר ואין משנין אותו ממקומו לעולם\", סיי בנוגע דעם מזבח גופא62 כמודגש אין פסוק63 „וזה מזבח לעולה לישראל\",\nאון ווי דער רמב\"ם ברענגט אין אָנפאַנג הלכות בית הבחירה64 ביידע פרטים פון פסוק „זה הוא בית ה' האלקים וזה מזבח לעולה לישראל\", אַ באַזונדער דיוק ובחירה („זה\") בנוגע דעם מזבח.\n(משיחת ש\"פ דברים תשד\"מ)",[["61","61","הל' ביהב\"ח רפ\"ב. — וראה בארוכה לקו\"ש ח\"ל ע' 68 ואילך."],["62","62","ראה לקו\"ש חכ\"ד שם ע' 83 הערה 38*."],["63","63","דה\"א כב, א."],["64","64","פ\"א ה\"ג."]]],[1300291176,"<h3>ח\"י אלול</h3>\nא. וועגן דעם טאָג פון ח\"י אלול — דער יום ההולדת פון דעם בעש\"ט (ח\"י אלול שנת נח\"ת) און יום ההולדת פון אלטן רבי'ן (ח\"י אלול שנת קה\"ת) — האָט כ\"ק מו\"ח אדמו\"ר געזאָגט אין אַ שיחה1, וז\"ל:\n„ביי חסידים איז פאַראַן אַן אַלטער חסידישער וואָרט אין צוויי אויס־שפראכן: א) ח\"י אלול איז דער טאָג וואָס האָט געבראַכט און ברענגט אַ לעבן אין אלול. ב) ח\"י אלול גיט אַ חיות אין דער עבודה פון אני2 לדודי ודודי לי\".\nפון דעם וואָס כ\"ק מו\"ח אדמו\"ר האָט איבערגעזאָגט ביידע נוסחאות איז מובן, אַז זיי זיינען ביידע אויסגעהאַלטן, און אַז אין יעדן נוסח איז דאָ אַן אויפטו לגבי דעם צווייטן3.\nועוד: דערפון וואָס כ\"ק מו\"ח אדמו\"ר האָט זיי געזאָגט מיט דעם סדר דוקא, ובפרט אַז ער האָט זיי מסמן געווען מיט „אל\"ף\" און „בי\"ת\" — איז מובן, אַז פריער קומט דער ענין אין ח\"י אלול וואָס ער „איז דער טאָג וואָס האָט געבראַכט און ברענגט אַ לעבן אין אלול\", און ערשט דערנאָך קומט דער „בי\"ת\" — דער צוויי־טער (נוסח —) ענין אין ח\"י אלול, וואָס ער „גיט אַ חיות אין דער עבודה פון אני לדודי ודודי לי\".\nב. די שינויים צווישן די צוויי נוס־חאות הנ\"ל זיינען:\nא) אין ערשטן נוסח איז דער לשון „(ח\"י אלול) איז דער טאָג וואָס כו'\", משא\"כ אין צווייטן נוסח שטייט „ח\"י אלול\" סתם, אָן דער הדגשה — „דער טאָג\".\nב) אין ערשטן נוסח — „האָט גע־בראַכט און ברענגט אַ לעבן\", משא\"כ אין צווייטן נוסח — „גיט אַ חיות\", וואָס אין דעם זיינען פאַראַן צוויי שינויים5: (א) אין ערשטן נוסח „ברענגט\", אין צווייטן „גיט\". (ב) אין ערשטן נוסח איז עס בלשון עבר און בלשון הוה: „האָט געבראַכט און ברענגט\", און אין צווייטן נוסח איז עס נאָר בל' הוה — „גיט\".\nג) אין ערשטן נוסח — „(אַ לעבן) אין אלול\"; אָבער אין צווייטן נוסח — „(אַ חיות) אין דער עבודה פון אני לדודי ודודי לי\".\nג. וי\"ל אַז די שינויים הנ\"ל, זיינען ניט נאָר שינויים (קלים) בלשון, נאָר שינויים עיקריים אין תוכן:\nא) דער ביטוי „ח\"י אלול איז דער טאָג וואָס כו'\" איז מדגיש דעם ענין הזמן —",[["1","1","לקוטי דיבורים ח\"ג ע' 946. ספר השיחות תש\"ה ע' 122."],["2","2","שה\"ש ו, ג — ר\"ת אלול (אבודרהם סדר תפלת ר\"ה (קרוב לתחלתו). פע\"ח שער ר\"ה פ\"א. שער הפסוקים עה\"פ. ב\"ח לטאו\"ח סתקפ\"א. ראשית חכמה ש' התשובה פ\"ד ד\"ה עוד יש. ועוד)."],["3","3","ראה לקו\"ש חי\"ט (ע' 250 ואילך) — עוד ביאור בב' הנוסחאות. וראה לקמן הערה 22."],["4","4","שמזה מובן, דמה שהקדים נוסח אחד להשני הוא לא רק מפני שא\"א לומר שניהם כאחד (אבל — שקולים הם*) — עדמשנ\"ת כמ\"פ בנוגע לפרש\"י עה\"ת (ראה ס' כללי רש\"י (ירושלים, תש\"מ. תנש\"א) פ\"ד. וש\"נ) — כ\"א שסדרם הוא בדיוק כו'. *) ובפרט שהקדים „אין צוויי אויסשפראכן\" — ראה ס' כללי רש\"י שם בנוגע לפרש\"י עה\"ת כשמקדים „יש לתרגמו בשני פנים\" וכיו\"ב."],["5","5","ועוד שינוי שלישי (אבל — רק בלשון): „לעבן\" (בל' אידית) או „חיות\" (בלה\"ק). וראה לקמן הערה 23."]]],[1300291177,"ס'איז אַ „טאָג\", איינער פון די ימות השנה, אָבער אַ יום מיוחד, „דער טאָג וואָס האָט געבראַכט און ברענגט אַ לעבן אין אלול\"; ווען מען זאָגט אָבער „ח\"י אלול\" סתם, איז דערביי ניט (אַזוי) מודגש דער ענין הזמן שבו, נאָר בעיקר דער אינהאַלט פון דעם טאָג6.\nאין אַנדערע ווערטער: אין זמן זיינען פאַראַן צוויי ענינים: א) עצם הזמן, ב) תוכן הזמן. לדוגמא — יום השבת, וואָס אין זמן איז ער (א) איינער פון די שבעת ימי השבוע, נאָר זייענדיק דער יום השביעי — דכל השביעין חביבין7 — איז עס אַ יום מיוחד. (ב) דער יום השביעי פאַרמאָגט אין זיך קדושת שבת, וואָס די קדושה (מצ\"ע) איז „למעלה מגדר המקום והזמן\"8, נאָר די קדושה איז מאיר8 אין דעם זמן פון יום השביעי.\nאון דאָס איז דער ערשטער חילוק צווישן די צוויי נוסחאות: לויטן ערשטן נוסח קומט דער „לעבן\" פון דעם זמן („דער טאָג\") פון ח\"י אלול, ס'איז אַן אויסגעטיילטער טאָג וואָס ברענגט אַ „לעבן אין אלול\"; משא\"כ לויטן צווייטן נוסח, קומט דער חיות פון דעם תוכן היום, פון „ח\"י אלול\" עצמו.\nב) דער חילוק הנ\"ל איז נאָך מער בולט אין דעם דריטן שינוי הנ\"ל (ס\"ב) צווישן די צוויי נוסחאות — אין ערשטן נוסח איז דער לשון „(אַ לעבן) אין אלול\", און אין צווייטן נוסח — „(אַ חיות) אין דער עבודה פון אני לדודי ודודי לי\":\nאין ערשטן נוסח רעדט זיך וועגן דעם „לעבן\" וואָס ווערט אַריינגעבראַכט אין דעם זמן פון (חודש) אלול:\nמשא\"כ אין צווייטן נוסח רעדט זיך מלכתחילה וועגן דעם תוכן הענין (עבודה) — דער „חיות\" פון (תוכן פון) ח\"י אלול, וואָס גיט חיות אינעם תוכן פון חודש אלול, „אין דער עבודה פון אני לדודי ודודי לי\" (וואָס איז ר\"ת אלול9, אָבער דער וואָרט „אלול\" עצמו ווערט דאָ ניט דערמאָנט).\nג) אויך דער צווייטער שינוי הנ\"ל — „ברענגט\" אָדער „גיט\" — איז אַ חילוק עיקרי: „ברענגט אַ לעבן\" ווייזט, אַז דער „לעבן\" גופא געפינט זיך במקום אחר, און דער טאָג פון ח\"י אלול איז דער „ממוצע\", וואָס ברענגט דעם לעבן (ממקום אחר) אין אלול; משא\"כ „גיט אַ חיות\" מיינט, אַז ער (ח\"י אלול) גיט חיות מדילי'.\nד. ויש לומר הביאור בזה:\nבנוגע צו חודש אלול געפינט מען צוויי ענינים:\nדי עבודה פון אלול איז בדרך אתערותא דלתתא10. אלול איז ר\"ת (כנ\"ל) „אני לדודי ודודי לי\" — פריער קומט „אני לדודי\" (עבודת האדם), און דער־נאָך „ודודי לי\" (די אתערותא דלעילא). ד.ה. די אתערותא דלעילא („ודודי לי\") איז אַ תוצאה פון עבודת האדם11\n[ניט ווי חודש ניסן וואָס ענינו איז",[["6","6","אף שח\"י אלול מציין יום בחודש (בשנה) — הרי: א) אינו דומה להלשון „דער טאָג\", לשון המדגיש ענין הזמן. ב) ההדגשה ב„ח\"י אלול\" היא לא בזה שהוא יום (בשנה), כי אם על הייחוד שביום זה, שזה קשור עם תוכן היום."],["7","7","ויק\"ר פכ\"ט, יא: בימים . . ויברך אלקים את יום השביעי. וראה פדר\"א ספי\"ח."],["8","8","שו\"ע אדה\"ז חאו\"ח מהד\"ת ס\"א ס\"ח. ע\"ש. ולהעיר מד\"ה תקעו תרצ\"א (בסה\"מ קונטרסים ח\"א) פ\"א."],["9","9","נסמן לעיל הערה 2."],["10","10","לקו\"ת ראה רד\"ה אני לדודי (הא'). מקומות שנסמנו בהערה 12. ועוד."],["11","11","ראה ד\"ה אני לדודי באוה\"ת שה\"ש ח\"ב (ע' תקמג), ע\"פ זח\"א פח, א־ב."]]],[1300291178,"אתערותא דלעילא, בלשון הפסוק12: דודי לי ואני לו — פריער „דודי לי\", און דער־נאָך (דורך דער אתערותא דלעילא) „ואני לו\"].\nנאָך מער: דער אַלטער רבי זאָגט אין לקו\"ת13, אַז דער „ודודי לי\" פון „אלול\" — די „המשכת אלקותו ית' למטה בבחי' התגלות\" — איז ניט אין חודש אלול, נאָר דערנאָך בראש השנה כו', ווייל דער ענין פון חודש אלול איז — די אתערותא דלתתא.\nלאידך אָבער, זאָגט דער אַלטער רבי (דאָרט גופא<sup data-n=\"14\">14</sup>, אַז אלול איז אַ זמן פון עת רצון, „זמן התגלות י\"ג מדות הרחמים\", וואָס דער גילוי מלמעלה ווערט אויפ־געטאָן (ניט דורך עבודת האדם, נאָר) בדרך אתערותא דלעילא. ווי פאַר־שטאַנדיק פון דעם משל וואָס דער אַלטער רבי זאָגט דאָרט אויף דעם — אַז דאָס איז ווי אַ מלך וואָס „מקבלין פניו בשדה ואז רשאין כל מי שרוצה לצאת להקביל פניו והוא מקבל את כולם בסבר פנים יפות ומראה פנים שוחקות לכולם\".\n— ווייל אע\"פ15 אַז אלול איז ענינו אתערותא דלתתא (כנ\"ל), מוז אָבער יעדע עבודה פון אַ נברא אָנקומען צו אַ סיוע מלמעלה (אתעדל\"ע) אויף דער עבודה (כמרז\"ל עה\"פ16 מי הקדימני ואשלם). און דאָס איז דער ענין פון די הארת י\"ג מדות הרחמים בחודש אלול — דאָס איז17 די אתעדל\"ע אויף דער עבודה פון אלול, „אני לדודי ודודי לי\".\nה. אע\"פ אַז אלול האָט אין זיך ביידע ענינים (הארת י\"ג מדות הרחמים מלמעלה און אתעדל\"ת) כנ\"ל — דאָך, זיינען די ר\"ת פון וואָרט אלול (אני לדודי ודודי לי) מרמז דוקא אויפן ענין פון אתעדל\"ת.\nוי\"ל דעם ביאור אין דעם:\nדי אתעדל\"ע פון אלול — הארת י\"ג מדות הרחמים — איז פאַרבונדן מיט דעם זמן18 פון אלול: עס זיינען פאַראַן כמה זמנים בשנה וועלכע זיינען אַן עת רצון — וואָס איז ניט פאַרבונדן מיט עבודת האדם, נאָר דער אויבערשטער האָט מלכתחילה איינגעשטעלט אין (טבע פון) וועלט, אַז די זמנים זיינען מצד עצמם אַן עת רצון. ועד\"ז בנוגע חודש אלול, אַז די הארת י\"ג מדות הרחמים בחודש אלול איז מצד דעם וואָס חודש אלול איז אַן עת רצון למעלה, וואָס דעמאָלט גייט דער מלך אַרויס אין „שדה\".\nאָבער דער תוכן ומהות החודש19 (וואָס איז אַריינגעגעבן געוואָרן אין דעם זמן) איז, אדרבה — דוקא דער ענין פון",[["12","12","שה\"ש ב, טז. וראה אוה\"ת ראה (ריש ע' תשצא). שה\"ש שם (ועוד). ד\"ה דודי לי תרכ\"ז בתחלתו. סד\"ה אני לדודי עטר\"ת. ד\"ה אני לדודי ה'ש\"ת פ\"א. ס' השיחות תש\"ג ע' 177. ועוד."],["13","13","שם."],["14","14","שם לב, סע\"א ואילך (משא\"כ שם כ, ריש ע\"ב; כה, ב; לג, א; וכן במאמרי אדה\"ז־פרשיות ח\"ב ע' תתכה — שאין מודגש שם שאלול ענינו אתעדל\"ת. וראה לקמן הערה 21)."],["15","15","ראה ג\"כ לקו\"ש חי\"ט ע' 159. ולהעיר מאוה\"ת ראה (ע' תתב): אלול המשכת י\"ג מדה\"ר מלמעלה א\"כ מהו אני לדודי, ומתחלה דודי לי מבעי'."],["16","16","איוב מא, ג. ויק\"ר פכ\"ז, ב. וראה לקו\"ש שם הערה 10."],["17","17","לקו\"ת ד\"ה אני לדודי הב' (לג, ג)."],["18","18","ראה לקו\"ת שם (כ, ריש ע\"ב. לג, א). — ועפ\"ז יומתק לשון הלקו\"ת כאן (לב, א) „באלול הוא זמן התגלות י\"ג מדה\"ר\"."],["19","19","דשמו אשר יקראו לו בלה\"ק מורה על תוכן הדבר (ראה שעהיוה\"א פ\"א. או\"ת להה\"מ (ד, ג). ובכ\"מ)."]]],[1300291179,"אתערותא דלתתא20, עבודת האדם21.\nו. ע\"פ הנ\"ל וועט מען אויך פאַר־שטיין דעם חילוק צווישן די צוויי נוסחאות הנ\"ל בנוגע צו ח\"י אלול —\nווייל כשם ווי עס זיינען פאַראַן די צוויי ענינים (הארת י\"ג מדות הרחמים און אתעדל\"ת) אין אלול, איז עד\"ז אַזוי בנוגע צו ח\"י אלול. אַז דער חיות וואָס ח\"י אלול ברענגט אַריין אין אלול, איז אין ביידע פרטים שבו, סיי בנוגע דער אתעדל\"ע שבו (די הארת י\"ג מדות הרחמים), און סיי אין דער אתעדל\"ת שבו (די עבודה פון אלול):\nדער טאָג פון ח\"י אלול — יום ההולדת פון דעם בעש\"ט און פון אלטן רבי'ן — איז אַ יום סגולה און זמן פון עת רצון; און דערפאַר האָט עס געבראַכט אַ נייעם „לעבן\" אין דעם עת רצון פון אלול, אין דער התעוררות פון אלול וואָס קומט מלמעלה (מצד דער הארת י\"ג מדות הרחמים).\nאון דערנאָך איז פאַראַן וואָס ח\"י אלול מצד תוכנו — פאַרבונדן מיט עבודת האדם ע\"פ תורת החסידות — גיט אַ חיות אין דעם תוכן פון חודש אלול, אין דער עבודה פון אני לדודי ודודי לי, אַז די עבודה פון חודש אלול איז מיט אַ גאָר אַנדער חיות.\nז. און דער חילוק איז מודגש אין די שינויי הלשונות אין די צוויי נוסחאות הנ\"ל (און בסדרם):\nדער ערשטער נוסח — נוסח הא' — רעדט וועגן דעם ערשטן ענין און אויפטו אין אלול, די הארת י\"ג מדות הרחמים (וואָס קומט אויף צו מעורר זיין די אתעדל\"ת). וואָס כשם ווי די הארת י\"ג מדות הרחמים איז אַן ענין פון אתעדל\"ע, עד\"ז אויך דער „לעבן\" פון ח\"י אלול וואָס איז דערמיט פאַרבונדן, קומט בדרך אתעדל\"ע (מלמעלה למטה<sup data-n=\"22\">22</sup>, מצד דעם טאָג כנ\"ל.\nאון דערפאַר שטייט דערביי דער לשון „דער טאָג וואָס האָט געבראַכט און ברענגט אַ לעבן23 אין אלול\":\n(א) ס'איז מודגש דער זמן — „ח\"י אלול איז דער טאָג . . אַ לעבן אין אלול\".",[["20","20","ראה גם קובץ מכתבים שנדפס בסו\"ס תהלים אהל י\"י (קה\"ת) ע' 206: אף כי בחדש הזה שערי רחמים נפתחים . . כללות העבודה הוא בדרך אתערותא דלתתא כהר\"ת דאלול שתחלה הוא אני לדודי ואח\"כ ודודי לי. וראה לקו\"ש שם (ע' 160), שמטעם זה ענין האתעדל\"ע דחודש אלול שייך לחודש ניסן (שענינו אתעדל\"ע) ונמשך ממנו. ע\"ש."],["21","21","ע\"פ המבואר בפנים יומתק השינוי בלקו\"ת, שבד\"ה אני לדודי הראשון אינו מעתיק התיבות „הרועה בשושנים\" (המרמזות על י\"ג מדות הרחמים), ובד\"ה אני לדודי השני מעתיקן — אף שגם במאמר הא' מבאר אודות הארת י\"ג מדות הרחמים — כי נקודה העיקרית של מאמר הראשון (שהיא המודגשת תיכף בתחילת המאמר) היא ע\"ד תוכנו של חודש אלול — אתעדל\"ת (אלא שאח\"כ מבאר ג\"כ ע\"ד האתעדל\"ע (לעורר עבודת אלול) — הארת י\"ג מדות הרחמים); משא\"כ במאמר השני, שעיקרו בא לבאר ענין הארת י\"ג מדות הרחמים דאלול."],["22","22","ויש להתאים המבואר בפנים עם המבואר במק\"א (לקו\"ש שם ע' 250 ואילך) שב' הנוסחאות הם בהתאם לב' הענינים שבח\"י אלול: נוסח הא' — ליום הולדת הבעש\"ט (מייסד חסידות הכללית), ונוסח הב' — יום הולדת אדה\"ז (מייסד חסידות חב\"ד) — כי הבעש\"ט המשיך החיות דחסידות (הכללית) בעיקר בדרך מלמעלמ\"ט (מופתים וכו'), ואדה\"ז — בעיקר בדרך מלמטה למעלה (ראה לקו\"ש שם ע' 255. ח\"ד ע' 1353)."],["23","23","עפ\"ז יש לפרש גם השינוי, דבנוסח הא' אומר „לעבן\" ובנוסח הב' „חיות\" — כי נוסח הא' הוא בעיקר לאלו שהם בתחילת העבודה (או בסגנון הלקו\"ת — מלך בשדה, ואלול „הם ימות החול\"), ולכן נאמר „לעבן\" בלשון אידית; משא\"כ נוסח הב' שהוא בעיקר לאלו שכבר ישנה אצלם העבודה דאני לדודי ודודי לי — נאמר „חיות\", בלה\"ק. וראה לקמן סעיף ח."]]],[1300291180,"(ב) „ברענגט\" ווייזט (כנ\"ל סוס\"ג) אַז דער „לעבן\" קומט ממקום אחר — פון דער אתעדל\"ע, דער לעבן קומט (ניט פון „טאָג\" עצמו, נאָר) מלמעלה, ח\"י אלול איז (נאָר) דער טאָג וועלכער ברענגט דעם לעבן.\n(ג) מ'איז מדגיש אויך דעם עבר — „האָט געבראַכט\" — ווייל דער ענין פון אתעדל\"ע איז (לגבי עבודת האדם) אַן ענין פון „עבר\"24, וואָס קומט לפני (און אַלס נתינת כח צו) דער עבודה.\nמשא\"כ אין צווייטן נוסח — נוסח הב' — רעדט זיך וועגן דעם חיות וואָס ח\"י אלול גיט אין דעם תוכן פון חודש אלול — „אין דער עבודה פון אני לדודי ודודי לי\", וואָס דער חיות קומט (ניט פון „זמן\" — „דער טאָג\" — נאָר) פון תוכן היום, פאַר־בונדן מיט גילוי תורת החסידות22. און דערפאַר שטייט דער לשון „גיט אַ חיות\" — ווייל דער תוכן פון ח\"י אלול „גיט אַ חיות (מדילי') אין דער עבודה פון אני לדודי ודודי לי\".\n[ועד\"ז לגבי דעם אדם, אַז דער חיות וואָס ח\"י אלול „גיט . . אין דער עבודה פון אני לדודי ודודי לי\" ווערט נמשך (ניט בדרך אתעדל\"ע, נאָר) בדרך מלמטה למעלה22: דער אדם דאַרף עס אַרויס־ברענגען מן הכח אל הפועל דורך זיין עבודה].\nח. די הוראה דערפון אין עבודת ה' — איז אין ביידע קצוות:\nפאַר די וועלכע האַלטן בתחילת העבודה — ביים „אל\"ף\" פון אלול — זאָגט מען אַז „ח\"י אלול איז דער טאָג וואָס האָט געבראַכט און ברענגט אַ לעבן אין אלול\":\nאַ איד קען דאָך טענה'ן — ווי איז שייך, אַז ער, וויסנדיק מעמדו ומצבו, זאָל קענען מקבל (וקולט) זיין חיות פון ח\"י אלול? וואָס פאַר אַ שייכות האָט ער צו אַזאַ יום נעלה!\nזאָגט מען אים, אַז אע\"פ אַז דו ביסט נאָך בתחילת העבודה (און דו האָסט ניט אָנגעהויבן אפילו די עבודה פון אלול, „אני לדודי ודודי לי\", ובמילא איז דאָך לכאורה ניט שייך אַז דו זאָלסט אויפטאָן אַ חיות אין עבודת ה' („גיט אַ חיות\")) — אעפ\"כ, האָסטו בכח, דורך דעם יום סגולה פון ח\"י אלול, צו (עכ\"פ) ברענגען אַ לעבן אין אלול.\nנאָכמער: ח\"י אלול האָט דיר שוין גע־בראַכט אַ לעבן אין אלול — דו האָסט עס בירושה מאבותיך ואבות אבותיך; און דערפאַר ברענגט עס דיר חיות אויך אין דעם הוה.\nולאידך, איז דאָ די הוראה פאַר „ראשיכם שבטיכם\", אַז עס איז ניט גענוג פאַר אים דאָס וואָס ח\"י אלול ברענגט אַ לעבן אין אלול, נאָר ער מוז אויפטאָן אַ חיות („גיט אַ חיות\") אין זיין עבודה פון אלול.\nולדוגמא — בלימוד התורה: ס'איז ניט גענוג דער ענין פון „ליגמר איניש\"25 — „לגרוס שמעתא מרבי'\"26 (בדוגמא צו „ברענגט אַ לעבן\", וואָס דער לעבן איז פריער ניט זיינער, עס קומט ממקום אחר) — נאָר עס דאַרף זיין דער „והדר ליסבר\"25: נוסף וואָס ער חזר'ט איבער תורת רבו, האָרעוועט ער בשכלו הוא, צו מסביר זיין „טעמי'\"26. ביז אַז ער איז (אויך) מחדש27 אין תורה — בדוגמא וואָס",[["24","24","להעיר גם מלקו\"ת ויקרא (ג, רע\"א) בפירוש „הביאני לשון עבר\"."],["25","25","שבת סג, א."],["26","26","פרש\"י שם."],["27","27","ראה הל' ת\"ת לאדה\"ז (פ\"ב ס\"ב) דכ\"א מחוייב לחדש בתורה. וכן באגה\"ק סכ\"ו (קמה, א). ובלשון הזהר (ח\"א יב, ב) „לאפשא לה\"."]]],[1300291181,"ח\"י אלול גיט אַ חיות אין דער עבודה פון אני לדודי ודודי לי.\nט. וויבאַלד אַז כ\"ק מו\"ח אדמו\"ר האָט געזאָגט ברבים ביידע נוסחאות און געהייסן אָפדרוקן זיי און מפיץ זיין זיי, איז מובן, אַז באמת זיינען ביידע נוסחאות שייך צו כאו\"א מישראל.\nוואָרום אפילו דער וואָס האַלט ערשט בתחילת העבודה, מוז ער וויסן אַז סו\"ס קען ער צוקומען דערצו אַז ער זאָל געבן (און אויפטאָן) אַ חיות בעבודת ה' מדילי';\nולאידך גיסא, אפילו די וואָס האַלטן שוין אין דער דרגא אַז זיי טוען אין דער עבודה פון אני לדודי ודודי לי, און נאָכ־מער: זיי זיינען בכח צו אויפטאָן אַ חיות אין זייער עבודה — דאַרפן זיי וויסן, אַז דאָס אַלץ איז ניט (אינגאַנצן) זייער אויפטו, נאָר דאָס הויבט זיך אָן פון דעם „לעבן\" וואָס ח\"י אלול ברענגט (מלמעלה) אין אלול.\nוע\"ד — אין דער דוגמא הנ\"ל פון לימוד התורה — ווי די גמרא28 דער־ציילט בנוגע לר' עקיבא, אַז בשעת משה רבינו האָט געהערט ווי ר' עקיבא לערנט מיט זיינע תלמידים „ולא הי' יודע מה הן אומרים\" איז „תשש כחו\", ביז „אמרו לו תלמידיו רבי מנין לך אמר להם הלכה למשה מסיני\" איז דעמאָלט „נתיישבה דעתו\".\nד.ה. אַז אפילו די ענינים וואָס ר' עקיבא האָט מחדש געווען (וואָס דערפאַר איז משה „לא הי' יודע מה הן אומרים\") איז מקורם פון משה רבינו29, „הלכה למשה מסיני\".\n(משיחת ש\"פ תבא, ח\"י אלול, תשמ\"ג)",[["28","28","מנחות כט, ב."],["29","29","ראה לקו\"ש חי\"ט ע' 253."]]],[1300291182,"<h3>נצבים</h3>\nא. אויפן פסוק1 „ומל ה׳ אלקיך את לבבך ואת לבב זרעך“ שטייט אין תרגום2 „ויעדי ה״א ית טפשות לבך“.\nבפשטות באַוואָרנט דערמיט דער תרגום: ווי פּאַסט דער לשון „ומל גו׳ את לבבך ואת לבב זרעך“? דער ענין פון „ומל“ איז שייך דוקא ביי ערלת הלב, ניט בנוגע הלב עצמו. און ווי עס שטייט טאַקע אין אַ פריערדיקער סדרה3 „ומלתם את ערלת לבבכם“ — האָט אויך דאָ געדאַרפט לכאורה שטיין „ומל ה״א את ערלת לבבך ואת ערלת לבב זרעך“.\nדערפאַר איז דער תרגום מוסיף — כתרגומו בסדרה הנ״ל — דעם וואָרט „טפשות (לבך)“, ד.ה. אַז עס איז ווי אַ „מקרא קצר“ און ס׳איז כאילו ווי דער פסוק וואָלט געזאָגט בפירוש „ערלת לבבך“.\nמען דאַרף אָבער פאַרשטיין: פאַרוואָס באַוואָרנט ניט רש״י די שאלה — ע״ד ווי דער תרגום (וכמדובר כמה פעמים4, אַז רש״י פאַרענטפערט יעדע שאלה וואָס ווערט נתעורר בלימוד פשוטו של מקרא)?\nמוז מען זאָגן, אַז לויט שיטת רש״י דאַרף מען די שאלה ניט באַוואָרענען (צי ווייל קושיא מעיקרא ליתא5, אָדער ווייל רש״י האָט שוין באַוואָרנט די שאלה אין אַ פריערדיקן פירוש6, כמדובר כמה פעמים<sup data-n=\"4\">4</sup>.",[["1","1","פרשתנו ל, ו."],["2","2","אונקלוס. ועד״ז בתרגום יונתן."],["3","3","עקב י, טז."],["4","4","ראה ס׳ כללי רש״י (קה״ת תש״מ) פ״א ס״ב. פי״ז ס״א. וש״נ. ועוד."],["5","5","לכאורה אפשר לתרץ שהוא ע״ד שמצינו בכ״מ הלשון „המול“ (פעולת המילה) בנוגע האדם עצמו*, כמו בפ׳ לך (יז, י) „המול לכם כל זכר“, וכיו״ב בכ״מ (ראה לך שם: יב, יג, כו, כז. וירא כא, ד. וישלח לד, טו. שם, כב. כד. בא יב, מד. שם, מח) — ועד״ז בעניננו, שמתאים הלשון „ומל“ גם בשייכות להלב עצמו. אבל אינו. כי במילה כפשוטה שענינה ידוע (הסרת בשר ערלתכם) אין הכרח לפרש בכ״מ הלשון „ערלה“ [ובפרט שברוב המקומות שנאמר הלשון „מל“ על האדם עצמו, נאמר בסמיכות לפעולת מילת בשר הערלה, כבפ׳ לך שם: „המול לכם כל זכר (ותיכף לאח״ז — שם, יא) ונמלתם את בשר ערלתכם“ (וראה גם לך שם, יד. שם, כג־כה. וכן בפ׳ וישלח שם (פסוק יד) מקדים „לאיש אשר לו ערלה“. ובפ׳ בא שם (פסוק מח) „וכל ערל לא יאכל בו“)], משא״כ בנדו״ד, „מילת“ הלב, שנזכר (לעיל) בחומש רק פעם אחת (עקב שם)** — דוחק גדול לומר שהכתוב יסתום „ומל גו׳ לבבך“, מבלי לפרט „ערלת לבבכם“. — ועכ״פ הי׳ לו לרש״י לפרש זה (ובמכש״כ מת״א שמפרשו)."],["6","6","ולכאורה דוחק לומר שרש״י סומך על פירושו (ר״פ בראשית. ועוד) שיש מקראות „שמקצרים לשונם וממעטים תיבה אחת“ (וראה פרש״י נח (ט, ו), ויחי (מח, ב) „הרבה במקרא“, „הרבה מקראות כו׳“) — שהרי בכו״כ מקומות מפרש רש״י „מקרא קצר“ וכיו״ב (ראה לדוגמא פרש״י: בראשית ד, טו (ב״פ). לך יג, ו. ויצא כט, ב. וישב לט, ד. מקץ מא, יג. שם, *) אין הכרח לומר שהוא „מקרא קצר“ (ראה הערה הבאה) — כ״א שמכיון שע״י פעולת המילה נעשה האדם „מהול“, מתאים ע״ז הלשון „המול גו׳ כל זכר“ וכיו״ב (היינו — שעושים אותו כולו ל„מהול“). (אלא שבנדו״ד קשה לפרש „ומל גו׳ לבבך“ שהקב״ה יעשה שהלב יהי׳ „מהול“ — מכיון שהמושג ד„מילת“ הלב נמצא רק פ״א בחומש (כבפנים ההערה בסופה)). **) בפ׳ בחוקותי (כו, מא) „לבבם הערל“, אבל שלילת ערלת הלב מתוארת שם באופן (בלשון) „יכנע“ (לא „מילה“)."]]],[1300291183,"ב. בנוגע דעם טעם פאַרוואָס דער פסוק זאָגט ניט „ערלת לבבך“ — יש לומר, אַז דאָס איז פאַרשטאַנדיק פון המשך הכתובים גופא:\nפריער שטייט7 „והי׳ כי יבואו עליך גו׳ ושבת עד ה״א ושמעת בקולו גו׳ אתה ובניך בכל לבבך ובכל נפשך“, און דערנאָך איז די תורה ממשיך „(ושב ה״א את שבותך גו׳ והביאך ה״א אל הארץ גו׳) ומל ה״א את לבבך גו׳“, ד.ה. אַז דער „ומל ה״א את לבבך“ וועט זיין לאחרי ווי אידן זיינען שוין אין אַ מצב פון „ושבת גו׳ בכל לבבך ובכל נפשך“;\nהאָט קיין אָרט ניט צו זאָגן אַז „ומל גו׳“ — ערלת הלב, ווייל אידן זיינען אין אַ מצב פון „ושבת גו׳ בכל לבבך ובכל נפשך“, איז שוין ניטאָ ביי זיי „ערלת הלב“8 (טפשות (כפי׳ התרגום), אָדער ווי רש״י איז מפרש „ערלת לבבכם“ — „אוטם לבבכם וכיסויו“9, אַז דער לב איז אטום „מהבין“<sup data-n=\"10\">10</sup>!\nמוז מען זאָגן, אַז „ומל גו׳ לבבך“ מיינט אַ העכערן ענין אין עבודת השם11 — בנוסף אויף דער פריערדיקער שלילה (העדר הטפשות, אַראָפּנעמען דעם „אוטם“ הלב), זאָל זיין אַן ענין חיובי ועשי׳, כהמשך הכתוב — „(ומל גו׳) לאהבה את ה״א גו׳“.\nבנוסח אחר קצת: פריער שטייט אַז אידן וועלן תשובה טאָן און פאָלגן דעם אויבערשטן „בכל לבבך ובכל נפשך“, וואָס דאָס קען זיין אפילו ווען זיי דינען דעם אויבערשטן מיראה12; אָבער „ומל ה״א גו׳“ וועט ביי זיי אויפטאָן — „לאהבה13 את ה״א בכל לבבך ובכל נפשך“14.\n— עס בלייבט אָבער צו פאַרשטיין: וואָס פאַר אַ שייכות האָט „ומל“ — אַ פעולה פון כריתה (הסרה<sup data-n=\"15\">15</sup> — מיט דער פעולה אויפן לב „לאהבה גו׳“16?!\nאויך איז ניט מובן: פון לשון הכתוב „ומל ה״א גו׳“ קומט אויס, אַז דאָס איז אַן ענין וועלכער ווערט אויפגעטאָן ניט דורך דעם אדם עצמו, נאָר על ידי פעולת הקב״ה17; אָבער אויב דער אויפטו פון „ומל גו׳“ באַשטייט בלויז אין „לאהבה גו׳“ — איז דאָך אהבת השם אַ",[["","","מט. ויחי מח, א־ב) — ולא סמך על פירושו בר״פ בראשית וכו׳. ואכ״מ."],["7","7","ל, א ואילך."],["8","8","כקושיית האוה״ח כאן. וראה גם תו״ח ס״פ לך (צג, סע״ג ואילך). ועוד."],["9","9","פרש״י עקב שם."],["10","10","פרש״י וארא ו, יב."],["11","11","ראה ע״ד החסידות — אגה״ק ס״ד (קה, ב ואילך). תו״א ס״פ לך. תו״ח שם. לקו״ת ראה יח, ג ואילך. אוה״ת פרשתנו עה״פ (ע׳ א׳רכג). ועוד."],["12","12","ראה צרור המור כאן (ל, א). — וכן מובן מהכתובים עצמם, שה„ושבת גו׳“ הוא תוצאה מזה ש„יבואו עליך . . הברכה והקללה גו׳“, עבודה מיראה."],["13","13","ראה כלי יקר כאן."],["14","14","ומ״ש אח״כ (פסוק ח־י) „ואתה תשוב ושמעת גו׳ ועשית גו׳ כי תשמע גו׳ בכל לבבך ובכל נפשך“ (וראה אוה״ח וצרור המור כאן) — י״ל שלפרש״י ה״ז ביאור ופירוט למ״ש לפנ״ז (פסוק ב) „ושבת גו׳ ושמעת גו׳“, דבתחילה נאמר רק כללות הענין שע״י „ושבת גו׳“ — „והטיבך והרבך מאבותיך“ (פסוק ה), ואח״כ (פסוק ז ואילך) מפרט ההטבה כו׳ — „ונתן גו׳ האלות האלה על אויביך גו׳ ואתה תשוב גו׳ והותירך ה״א בכל מעשה ידך בפרי בטנך וגו׳ כי תשמע גו׳“. וראה כלי יקר כאן."],["15","15","כבתרגום כאן (ועד״ז בעקב שם) „ויעדי“."],["16","16","לאחרי שכבר הוסרו אוטם וטפשות הלב והאדם שומע בקול ה״א בכל לבבו ובכל נפשו — וחסרה לכאורה רק פעולה חיובית שתפעול בו האהבה."],["17","17","ראה רמב״ן, צרור המור ועוד כאן. וראה (ע״ד החסידות) במקומות שנסמנו בהערה 11."]]],[1300291184,"ציווי אויף כאו״א מישראל, „ואהבת18 את ה״א גו׳ בכל לבבך ובכל נפשך“19 ופעמיים בכל יום!\nג. ויש לומר, אַז אויך די שאלה ווערט באַוואָרנט אין המשך הכתובים:\nדי פסוקים „והי׳ כי יבואו עליך גו׳ ושבת גו׳ ושב גו׳ ומל גו׳“ קומען בהמשך צו דער אריכות פריער, וועגן דעם מצב בלתי טוב אין גלות, וואָס קומט מצד דעם וואָס „עזבו את ברית ה׳“20; און די תורה איז מתאר די סיבה פון אַזאַ הנהגה — „כי21 אתם ידעתם גו׳ בארץ מצרים גו׳ ותראו את שקוציהם גו׳ פן יש גו׳ אשר לבבו פונה גו׳ לעבוד את אלקי הגוים ההם גו׳“.\nאיז דערפון פאַרשטאַנדיק, אַז דער „ומל ה״א את לבבך גו׳“ (וואָס וועט זיין לאחרי ווי „והביאך ה״א אל הארץ גו׳“) איז אויף צו אַראָפּנעמען די סיבה פון דער ירידה רוחנית — די אפשריות פון „ותראו את שקוציהם גו׳ לבבו פונה גו׳“.\nאון די הסברה אין דעם:\nאין דעם וואָס דער לב פון אַ אידן קערט זיך אָפּ מאחרי השם, זיינען דאָ צוויי סיבות כלליות (וועלכע דריקן זיך אויס אין די צוויי לשונות: ערלת הלב און „לבבו פונה“):\nא) אַ חסרון אין דער מציאות הלב עצמו — עס איז דאָ ערלת הלב (טפשות אָדער אַן אוטם), און מצד דעם איז דער לב נמשך צו דברים רעים ואסורים.\nב) אַ סיבה שחוץ הימנו — מהלב, ובלשון רש״י22 — „העין רואה והלב חומד“, וואָס דאָס איז אופן הירידה של האדם: נאָך איידער עס ווערט אַ שינוי (לגריעותא) אין מציאות הלב גופא — ער האָט נאָך ניט קיין טפשות אָדער אוטם, אַזוי אַז מצד עצמו וואָלט ער ניט געהאַט קיין חמדה צו ניט גוטע זאַכן — קומט ראיית העין און איז מוליד אַ חמדה בלבו.\nאון דאָס איז דער דיוק לשון הכתוב בפרשתנו, אַז די סיבה ראשונה צו דער ירידה רוחנית פון בנ״י איז „איש גו׳ אשר לבבו פונה“ — דער לשון („לבבו פונה“) ווייזט אויף אַ חסרון (ניט אין דעם לב עצמו — ווי „לבבם הערל“23 — נאָר) בלויז אין נטיית הלב (וואָס קען קומען מצד אַ סיבה שמבחוץ); וכמפורש בקרא די השתלשלות המצב — „כי אתם ידעתם את אשר ישבנו בארץ מצרים גו׳ ותראו את שקוציהם גו׳ לבבו פונה גו׳ לעבוד את אלקי הגוים ההם“ (דער אופן פון „העין רואה והלב חומד“).\nד. ע״פ הנ״ל איז פאַרשטאַנדיק:\nא) ווי פּאַסט דערויף דער לשון „ומל“ (כריתה) — ווייל דער אויפטו פון „ומל“ איז צו אַראָפּנעמען די אפשריות פון „לבבו פונה“, וואָס דערצו דאַרף מען אָפּשניידן דעם קשר צווישן דער ראי׳ — מיטן לב (אַזוי אַז דער לב זאָל ניט חומד זיין דעם „ותראו (מיט דעם עין) את שקוציהם“).\nב) „ומל ה״א גו׳“ דוקא — מען דאַרף אָנקומען צו פעולת הקב״ה בזה: אַן אדם איז בכחו צו מסיר זיין די ערלת הלב —",[["18","18","ואתחנן ו, ה. וראה גם פרשתנו ל, טז. ועוד."],["19","19","וגם: מכיון ש„ואהבת גו׳“ הוא ציווי על האדם — לכאורה נכלל במ״ש לפנ״ז „ושמעת בקולו גו׳ בכל לבבך גו׳“ (אבל ראה הערה 12)."],["20","20","כט, כד."],["21","21","שם, טו־יז."],["22","22","שלח טו, לט (בפ׳ ציצית שאומרים בכל יום). ולהעיר מפרש״י פרשתנו כט, יח."],["23","23","בַחוקותי כו, מא."]]],[1300291185,"זיין אוטם און טפשות; אָבער דער קשר צווישן ראית עיניו ולבו איז אַן ענין וואָס דער אויבערשטער האָט אין אים מטביע געווען, און ס׳איז נאָר בכחו יתברך דאָס צו מבטל זיין24.\nאון דאָס איז אויך וואָס דער פסוק איז ממשיך „(ומל ה״א את לבבך ואת לבב זרעך) לאהבה את ה״א בכל לבבך גו׳ למען חייך“: וויבאַלד אַז עס וועט אינגאַנצן צוגענומען ווערן די אפשריות אויף „לבבו פונה“25, וועט ממילא זיין26 „לאהבה את ה״א בכל לבבך ובכל נפשך למען חייך“: ניט סתם אהבת ה׳27, נאָר אין אַן אופן אַז דאָס וועט ווערן דער גאַנצער לעבן פון אַ אידן28.\nה. פון דעם ענין הנ״ל קומט אַרויס אַ נפק״מ אין דעם תוכן העבודה פון דעם זמן ווען מען לייענט פרשת נצבים — חותם חודש אלול:\nאויפן פסוק „ומל גו׳ את לבבך ואת לבב זרעך“ שטייט אין בעל הטורים29, אַז „את לבבך ואת לבב ר״ת אלול, לכך נהגו להשכים להתפלל סליחות מר״ח אלול ואילך“.\nפון דעם וואָס דער בעה״ט פאַרבינדט די ר״ת פון דעם פסוק מיט אמירת סליחות איז מובן, אַז ער איז מפרש דעם תוכן הפסוק פון „ומל גו׳“ אַלס עבודת התשובה30.\nויש לומר, אַז דאָס איז בהתאם מיטן פירוש התרגום אַז „ומל גו׳ את לבבך“ מיינט אַז מען נעמט אַראָפּ די טפשות הלב.\nמשא״כ לויטן אויבנדערמאָנטן ביאור (לויט שיטת רש״י, בפשוטו של מקרא), אַז דער אויפטו פון „ומל גו׳“ דריקט זיך אויס אין דעם המשך הכתוב — „לאהבה גו׳ למען חייך“ (וואָרום די הסרת טפשות ואוטם הלב האָט זיך שוין אָפּגעטאָן נאָך פאַר׳ן „ומל ה״א“) — קומט אויס, אַז די עבודה פון אלול (המרומז אין פסוק „ומל גו׳ את לבבך ואת לבב זרעך“) איז ניט עבודת התשובה והסליחה, נאָר עבודת האהבה31.\nוואָרום דער אויפטו פון אלול איז אויך אין קו האהבה, כמובן פון די ר״ת32 „אני33 לדודי ודודי לי“, וואָס „דודי“ איז דאָך אַן ענין פון אהבה. און ווי פאַרשטאַנדיק אויך פונעם משל הידוע וואָס דער אַלטער רבי34 זאָגט אויף הארת י״ג",[["24","24","ולהעיר מרש״י לך (יז, א): והי׳ תמים, עכשיו אתה חסר ה׳ איברים ב׳ עינים כו׳."],["25","25","להעיר מרמב״ן כאן [אלא שהוא מבאר ש„ומל גו׳“ היינו הסרת ערלת הלב, היינו היצה״ר, שאז יהי׳ ביטול היצה״ר לגמרי (וכ״ה בתיב״ע כאן). ולהעיר מפרש״י ואתחנן שם: בשני יצריך (היינו שג״ז נכלל בהציווי דואהבת גו׳). ואכ״מ]."],["26","26","ראה ספורנו כאן."],["27","27","ובפרט את״ל שזה נכלל כבר במ״ש לפנ״ז „ושמעת גו׳ בכל לבבך גו׳“, כנ״ל הערה 19."],["28","28","ראה אגה״ק שם. ועוד. ועפ״ז מובן ג״כ זה שהתורה מוסיפה „ואת לבב זרעך“ (וגם: נקט „זרעך“, ולא „בניך“ — כלעיל פסוק ב „אתה ובניך“) — להדגיש שזה יהי׳ ענין נצחי בעם ישראל (ראה תיב״ע כאן: עד עלמין), לא רק לדור ההוא אלא לכל יו״ח (זרעם)."],["29","29","וכ״ה באבודרהם ס׳ תפלת ר״ה. ב״ח לטור או״ח סתקפ״א. ר״ח ש׳ התשובה פ״ד (ד״ה עוד). של״ה ריש מס׳ ר״ה (ריג, א). ועוד."],["30","30","וכמפורש בב״ח, ר״ח ושל״ה שם — ש„ומל גו׳“ הוא סמך לתשובה."],["31","31","וכן משמע בלקו״ת ראה (לג, ד): ומל . . ר״ת אלול והיינו לבוא לבחי׳ פנימית הלב. ועייג״כ לקו״ת שם יט, א (בהקיצור לפ״ג. וראה שם בפנים המאמר). וראה אוה״ת פרשתנו עה״פ (ע׳ א׳רכג)."],["32","32","אבודרהם שם. פע״ח ש׳ ר״ה פ״א. ב״ח, ר״ח ושל״ה שם. ובכ״מ."],["33","33","שה״ש ו, ג."],["34","34","ד״ה אני לדודי — לקו״ת פ׳ ראה לב, ריש ע״ב. מאמרי אדה״ז — פרשיות (ח״ב) ע׳ תתכה."]]],[1300291186,"מדות הרחמים בחודש אלול, אַז דאָס איז בדוגמא צו אַ מלך וואָס „מקבלין פניו בשדה . . והוא מקבל את כולם בסבר פנים יפות ומראה פנים שוחקות לכולם“ — וואָס כמובן, איז דאָס מעורר ביי כולם אַן אהבה צום מלך, כמים הפנים לפנים גו׳35.\nו. ויש לומר, אַז דאָס וואָס לויטן בעה״ט איז אין עבודת אלול (המרומזת אין פסוק „ומל גו׳“) ניט נכלל דער המשך הכתוב „לאהבה גו׳“, איז ווייל לויטן לימוד ע״ד הרמז (פירוש הבעה״ט), איז דער „לאהבה גו׳“ אַ העכערע מדריגה ווי די אהבת השם שבחודש אלול.\nובהקדמה: דער אַלטער רבי איז מבאר36 דעם חילוק צווישן עבודת חודש אלול און עבודת ימים נוראים שלאח״ז, אַז אלול איז בעיקר דער זמן פון „אני לדודי“, אתעדל״ת37; משא״כ די ימים נוראים איז דער עיקר זמן פון „ודודי לי“ — „זמן התגלות מלכותו ית׳“ (בדוגמא ווי איינער וואָס איז „מקבל38 פני המלך בהיכל מלכותו“ — וואָס צו דעם זיינען זוכה נאָר די „מובחרים שבעם ויחידי סגולה“<sup data-n=\"39\">39</sup>, וואָס דוקא דעמאָלט ווערט אהבתו40 ית׳ „נטוע בלב האדם“.\nדאָס הייסט, אַז די מדריגת האהבה פון חודש אלול איז ניט אַזוי הויך ווי די אהבה וואָס ווערט דערגרייכט אין די ימים נוראים, דעם (עיקר ה)זמן פון „ודודי לי“.\nועפ״ז יש לבאר דעם חילוק צווישן די צוויי אופנים הנ״ל (צי דער „לאהבה גו׳“ איז אַ טייל פון חודש אלול):\nדער לימוד ע״ד הפשט — לימוד השווה לכל נפש — איז בהתאם צו די ניט אַזוי הויכע מדריגות אין עבודת השם, מדריגות צו וועלכע אַלע אידן זיינען שייך. ובעניננו — דער „לאהבה את ה״א גו׳“ אין „עולם הפשט“ איז אַ מדריגה אין אהבה צו וועלכער אַלע אידן זיינען שייך — און דערפאַר איז דאָס אַ טייל פון עבודת אלול, ווייל דאָס איז אַן אהבה צו וועלכע מען קען דערגרייכן אפילו ווען מ׳געפינט זיך „בשדה“41;\nמשא״כ אין לימוד ע״ד הרמז — העכערע42 מדריגות אין (לימוד התורה, ובמילא אין) עבודת השם — איז דער „לאהבה את ה״א גו׳“ אַ העכערע",[["35","35","ראה תניא פמ״ו, מט (אלא ששם מובא בנוגע ל„מכניסו להיכלו כו׳“)."],["36","36","לקו״ת שם בריש המאמר."],["37","37","והארת י״ג מדות הרחמים בחודש אלול הוא רק מפני שלפני כל אתעדל״ת צ״ל אתעדל״ע לפני׳ (ראה לקו״ת פ׳ ראה כה, ב־ג. אוה״ת שם ע׳ תשסט. לקו״ש חי״ט ע׳ 159. לעיל ע׳ 163)."],["38","38","ל׳ הלקו״ת שם כה, ג."],["39","39","לקו״ת שם לב, ריש ע״ב."],["40","40","בד״ה אני לדודי בלקו״ת שם, דבר״ה ויוהכ״פ הוא בחי׳ יראה (מצד התגלות מלכותו ית׳). אבל מזה גופא שמקשר זמן זה עם „ודודי לי“ מובן, שאז הוא (גם) ענין האהבה (וכן מפורש בלקו״ת ס״פ תבא (שצויין בד״ה אני לדודי שם): מקבלים . . דחילו ורחימו מלמעלה. וראה לקו״ת שם מב, א). וראה מאמרי אדה״ז — פרשיות שם (ע׳ תתכו): ביוה״כ . . כמשל האוהב של המלך המופלג כשמקבל הארת פנים של אהבה עזה בחדר מיוחד."],["41","41","ראה סה״מ — מלוקט ח״א ע׳ תסח ד„שדה“ משווה כל הנמצאים בו (וראה מאמרי אדה״ז פרשיות שם)."],["42","42","כידוע דפרד״ס שבתורה הם כנגד ד׳ עולמות (ש׳ הגלגולים הקדמה יז בסופה. ע״ח (הובא בנגיד ומצוה בתחלתו. נהר שלום בהקדמת רחובות הנהר בסופה). משנת חסידים מס׳ חיוב הנשמות פ״א מ״ב. ועוד)."]]],[1300291187,"מדריגה אין אהבה, וואָס קומט ערשט (לאחרי די עבודה פון אלול —) אין דעם (עיקר ה)זמן פון „דודי לי“43 (בימים נוראים);\nאון דערפאַר איז התחלת הכתוב — „ומל גו׳ את לבבך ואת לבב זרעך“ די עבודה פון סליחות ( — מר״ח ואילך, פון כל ימים) דחודש אלול, און דערנאָך, אין די ימים נוראים (שלאחרי חודש אלול) דערגרייכט מען צו „לאהבה את ה״א בכל לבבך ובכל נפשך למען חייך“.\n(משיחות ש״פ נצבים תשל״ד, ש״פ נצו״י תשמ״ג)",[["43","43","אהבה הבאה מלמעלה (כנ״ל בפנים) — מתאים לתוכן הכתוב „ומל ה״א גו׳ לאהבה גו׳“, הבאה מלמעלה."]]],[1300291188,"<h3>נצבים - וילך</h3>\nא. בנוגע דעם שבת פאַר ראש השנה איז ידוע1 דער וואָרט פון אַלטן רבי'ן וואָס ער האָט געהערט פון מגיד אין נאָמען פון דעם בעש\"ט, אַז דעם „חודש השביעי\" איז „הקב\"ה בעצמו מברכו2 בשבת מברכים שהוא השבת האחרון דחודש אלול, ובכח3 זה ישראל מברכים את החדשים י\"א פעמים בשנה\".\nאין וואָס באַשטייט ברכתו של הקב\"ה אין דעם „שבת מברכים\" פון חודש תשרי? איז דער בעש\"ט ממשיך:\n„כתיב אתם נצבים היום דהיום קאי על ר\"ה4 שהוא יום הדין וכמ\"ש5 ויהי היום גו' ותרגם והוה יום דינא רבא6. ואתם נצבים קיימים ועומדים7 והיינו שזוכים בדין, ובשבת שלפני ר\"ה שהוא השבת האחרון דחדש אלול קורין אז פרשת אתם נצבים8 דזהו ברכתו של הקב\"ה כו'\".\nפון דעם דיוק הלשון „קורין אז פרשת אתם נצבים דזהו ברכתו של הקב\"ה\" — און ניט „קורין אז אתם נצבים (היום)\" (ווי ער זאָגט פריער אין דער תורה, וואו ער איז מבאר אַז דאָס מיינט „קיימים ועומדים והיינו שזוכים בדין\") — איז פאַרשטאַנדיק, אַז „ברכתו של הקב\"ה\" איז ניט נאָר די (דריי) ווערטער „אתם נצבים (היום)\", נאָר כללות „פרשת אתם נצבים\", די גאַנצע סדרה.\nוע\"פ המבואר במקום אחר9, אַז די צוויי סדרות אתם נצבים און וילך זיינען בעצם איין סדרה, נאָר לפעמים איז מען מחלק די איין סדרה לשתים (כדיוק לשון הרס\"ג10: „ומהן (פון די נ\"ג פרשיות) פרשה המתחלקת לשתים ונקראת בשתי שבתות אם יש צורך בכך והיא אתם נצבים הנחלקת בוילך משה\").\n[ניט ווי אַנדערע סדרות המצטרפות, וואָס בעצם זיינען זיי באַזונדערע סדרות, נאָר „מצטרפות לפעמים שתים שתים\"11],\nדאַרף אויסקומען, אַז אויך „וילך משה\" גייט אַריין אין ברכתו של הקב\"ה,",[["1","1","קובץ מכתבים לתהלים אהל י\"י ע' 193. היום יום כה אלול. אגרות קודש אדמו\"ר מהוריי\"ץ ח\"ג ס\"ע תל ואילך. וראה בביאור תורה זו — לקו\"ש ח\"ד ע' 1139 ואילך. ח\"ט ע' 184 ואילך."],["2","2","עוד ביאור ע\"פ נגלה שאין ישראל מברכים החודש הזה — ראה לקו\"ש חכ\"ד ע' 222 ואילך."],["3","3","ראה לקו\"ש ח\"ט ע' 187 — הרמז לזה בנגלה."],["4","4","ראה פענח רזא ס\"פ נצבים. לקו\"ת ר\"פ נצבים."],["5","5","איוב ב, א."],["6","6","וראה אוה\"ת נ\"ך עה\"פ (ע' תרנא), מזח\"ב לב, ב (ועוד)."],["7","7","ראה תנחומא ר\"פ נצבים (עומדין . . ואנו קיימין — אבל אינו מפורש על הל' „נצבים\". וראה שם, ד: נצבים . . קיומו של עוה\"ז ושל עוה\"ב). ובפרש\"י (נצבים כט, יב) מפרש מ„מ\"א\": נצבים . . קיימין."],["8","8","רמב\"ם הל' תפלה פי\"ג ה\"ב. תוס' מגילה לא, סע\"ב. טושו\"ע או\"ח סתכ\"ח ס\"ד. לקו\"ת שם. שם הפרשה „אתם נצבים\" (כבתורה הנ\"ל) הוא גם ברמב\"ם שם. סידור הרס\"ג (דלקמן בפנים). תוס' מגילה שם ד\"ה ראש. ועוד. ובטושו\"ע מתחיל „אתם נצבים\", אבל בהמשך הלשון שם נצבים (וילך) סתם. וכ\"ה בתוס' מגילה שם בסוף העמוד: למה מחלקים פרשת נצבים וילך. ועד\"ז השינויים בכמה מפרשי התורה. ואכ\"מ."],["9","9","ראה לקו\"ש חי\"ט ע' 298. וש\"נ."],["10","10","בסדורו „קריאת התורה\"."],["11","11","ל' הרס\"ג שם. ועיי\"ש בלקו\"ש בפרטיות — עוד הוכחות לזה שנצבים־וילך הוי פרשה אחת."]]],[1300291189,"וואָרום אויך דאָס איז אַ טייל פון „פרשת אתם נצבים\".\nאָבער לאידך גיסא: דערפון גופא וואָס עס זיינען פאַראַן יאָרן ווען מ'צעטיילט די סדרה לשתים12, און „וילך משה\" ווערט געלייענט ערשט נאָך ראש השנה — און זיכער אַז אויך אין יענע יאָרן פעלט ניט ח\"ו בברכתו של הקב\"ה אין „שבת מברכים\" פון חודש תשרי — איז מוכרח צו זאָגן, אַז דער עיקר ברכתו של הקב\"ה איז „פרשת אתם נצבים\" עצמה, ד. ה. דער טייל פון דער פרשה ביז „וילך משה\", וואָס במנהג ישראל ווערט דוקא דאָס אָנגערופן פרשת (אתם) נצבים, און ווי געדרוקט אין חומשים; און דאָס וואָס אויך „וילך משה\" איז אַ טייל פון ברכתו של הקב\"ה, איז אַזאַ ענין של ברכה, וואָס אַמאָל קען עס אַרויסקומען בפועל — בגילוי ערשט לאחרי ראש השנה.\nב. וי\"ל הביאור בזה:\nאין דער תורה הנ\"ל איז ער מסיים (כנ\"ל): „ובכח זה (פון ברכת הקב\"ה) ישראל מברכים את החדשים י\"א פעמים בשנה\". ויש לומר, אַז אין דעם איז מרומז דער ענין הברכה וואָס איז פאַרבונדן מיט פרשת וילך:\nדער עצם ענין פון „הקב\"ה בעצמו מברכו\", איז פאַרבונדן (בעיקר) מיט פרשת אתם נצבים וועלכע ווערט געלייענט בכל שנה ושנה אין דעם שבת האחרון פון חודש אלול; און דאָס וואָס ברכת הקב\"ה גיט אַריין אַ כח אַז אידן זאָלן קענען דערנאָך מברך זיין די חדשים י\"א פעמים בשנה — דאָס איז פאַרבונדן בעיקר מיט וילך (משה).\nאון דערפאַר לייענט מען לפעמים וילך משה נאָך ראש השנה13 — אע\"פ אַז אויך וילך משה איז פאַרבונדן מיט דער ברכה פון „שבת מברכים\" חודש תשרי כנ\"ל — ווייל דער ענין אין דער ברכה (אַז „בכח זה ישראל מברכים את החדשים י\"א פעמים בשנה\") איז ניט אַזויפיל נוגע אין דעם שבת שלפני ר\"ה, היות דער „כח זה\" קומט אַרויס בגלוי ערשט אין די ש\"מ שלאח\"ז, און דעריבער קען עס געלייענט ווערן אַמאָל — אויך נאָך ראש השנה.\nג. יעדער ענין דריקט זיך אויס בשמו אשר יקראו לו בלשון הקודש. עד\"ז איז מובן בפשטות בנוגע שם הסדרות „נצבים\" און „וילך\", אַז זייער תוכן גיט זיך אַרויס אין זייערע באַטרעפנדע נעמען. די ווערטער „נצבים\" און „וילך\" ענטהאַלטן צוויי פאַרשידענע — און נאָכמער: היפכ'דיקע — מושגים.\nדער טייטש פון נצבים איז (ווי דערמאָנט אין דער תורה הנ\"ל) „קיימים ועומדים\". ניט אַן עמידה סתם, נאָר אַן עמידה חזקה בתוקף. ווי עס ווערט נתבאר14 אַז נצבים איז מלשון „נצב מלך\"15, וואָס ווייזט16 אויף אַן עמידה בתוקף הכי גדול, בדוגמא ווי „נצב\" פון אַ מלך;",[["12","12","כידוע הסימן (בעה\"ט עה\"פ וילך. טושו\"ע שם) „פתבג המלך\" (ל' הכתוב — דניאל א, יג. שם, טו) — כאשר „ב\"ג המלך (אז) פת וילך\", דכאשר ר\"ה הוא ביום ב' או ג' בשבת, אז „פת וילך\" מלשון פתות אותה פיתים שמחלקים נצבים וילך לשתים (ל' המג\"א שם. וכ\"ה בכ\"מ — ראה לקו\"ש שם)."],["13","13","היינו קריאת כל הפרשה כולה בשבת. אבל גם אז (כשנצבים וילך נפרדות), קוראין פ' וילך במנחה דש\"ק נצבים. וכן הלימוד דפ' וילך (בשיעורי חת\"ת) — הוא לפחות יום א' לפני ר\"ה (או — ב' ימים)."],["14","14","אוה\"ת נצבים ס\"ע א'רא."],["15","15","לשון הכתוב — מ\"א כב, מח."],["16","16","אוה\"ת שם ס\"ע א'רב ואילך."]]],[1300291190,"משא\"כ „וילך\" איז תוכנו — הליכה, היפך פון עמידה בכלל, ועאכו\"כ היפך פון נצבים — עמידה בתוקף.\nאון אעפ\"כ זאָגט מען, אַז נצבים און וילך, איז ניט נאָר וואָס מ'איז זיי מחבר יחד (ווי אַנדערע סדרות המצטרפות), נאָר נאָכמער: זיי זיינען בעצם איין סדרה.\nד. ונקודת הביאור בזה: כללות עבודת ה' איז מיוסד אויף דעם אַז עס מוזן זיין ביידע קוים (תנועות) הנ\"ל17 — „נצבים\", אַן עמידה בתוקף, בלתי שינוי; און „וילך\" — הליכה מחיל אל חיל, ביז אין אַן אופן פון „אין18 להם מנוחה\"19, שינוי תמידי20.\nאון דאָס איז אין אַלע דריי עמודים21 (קוים), פון תורה, עבודה (תפלה), און גמילות חסדים (מצות)22:\nה. בתורה:\nתורה איז בכללות פאַנאַנדערגעטיילט אין צוויי23 — תורה שבכתב און תורה שבעל פה. וואָס אע\"פ אַז ביידע „ניתנו לו למשה בסיני\", ובלשון הרמב\"ם בתחלת הקדמתו לס' היד: כל המצות שניתנו לו למשה בסיני בפירושן ניתנו . . תורה זו תורה שבכתב והמצוה זו פירושה . . הנקראת תורה שבעל פה\" — איז אָבער אַ חילוק אין זייער אופן הנתינה:\nתורה שבכתב איז ניתנה באופן מדוד ומוגבל, אין אותיות און תיבות, אין וועלכע עס קען ניט זיין קיין שינוי24;\nמשא\"כ תושבע\"פ — „פירושה\", איז געקומען ע\"י החכמים, וועלכע האָבן איר מפרש געווען דורך די יג (לב וכו') מדות שהתורה נדרשת בהן (וכיו\"ב)25,",[["17","17","ראה גם מכתב ו' תשרי תשד\"מ (נדפס בלקו\"ש חכ\"ד ע' 632)."],["18","18","ל' חז\"ל — סוף ברכות ומו\"ק. וראה הערות הבאות."],["19","19","ויש לומר, שזהו הטעם לחילוק דב' המסכתות — מו\"ק ותמיד: בסיום דמס' מו\"ק — ת\"ח אין להם מנוחה כו' שנאמר ילכו מחיל אל חיל; ומס' תמיד סיומה — מזמור שיר ליום השבת כו' ליום שכולו שבת ומנוחה לחיי העולמים — כי תמיד — העבודה התמידית, והרי במס' זו מדובר ע\"ד „סדר התמיד לעבודת בית אלקינו\" (תמיד פ\"ז מ\"ג בסופה. ובפשטות קאי על כל המס' שלפנ\"ז), ולכן סיומה הוא בענין שבת ומנוחה, העדר השינוי (ראה לקמן סעיף ז); ואילו מס' מועד קטן, תוכנה (כשמה) ע\"ד הזמן שנשתנה מהרגיל, וזמן — בכלל, תנועה ושינוי — עבר הוה ועתיד [ובזמן גופא בפרט ע\"ד זמן בלתי רצוי, שהכוונה לשנותו להפכו לטוב, כסיום המס' במשניות דמו\"ק], ולכן סיומה בענין של עלי' ושינוי — ת\"ח אין להם מנוחה . . ילכו מחיל אל חיל."],["20","20","ראה הערה הקודמת בנוגע להחילוק דסיום מס' מו\"ק ותמיד. ומה שבמס' ברכות מסיים בב' הענינים — אין להם מנוחה, ושלום (מנוחה) — נת' בשיחת ו' תשרי תשד\"מ (ס' השיחות תשנ\"ב ח\"ב ע' 502 ואילך). *) ואולי י\"ל, שזהו ג\"כ טעם החילוק, דסיום מס' מו\"ק — שינוי — הוא בגמרא, וסיום תמיד — מנוחה — במשנה. כי החילוק בין משנה וגמרא הוא ע\"ד החילוק בין תושב\"כ ותושבע\"פ (דלקמן ס\"ה): משנה היא (בעיקר) הלכות פסוקות — בלתי משתנה, ולכן סיומה (במס' תמיד) בענין המנוחה; גמרא היא שקו\"ט בהלימודים והסברות (ובפרט בבבלי) — סיומה (במו\"ק) הוא בענין דהליכה כו'."],["21","21","אבות פ\"א מ\"ב."],["22","22","ומכיון שביהמ\"ק הוא המקום העיקרי דעבודת ישראל מובן שגם בו ב' נקודות אלו. וכמודגש בשיעור היומי דש\"ק זו (תשד\"מ) ברמב\"ם (הל' ביהב\"ח רפ\"א) „מ\"ע לעשות בית לה' מוכן להיות מקריבים בו הקרבנות (עבודה תמידית) וחוגגין אליו שלש פעמים בשנה\" — עבודה בשינויים (ראה לעיל הערה 19). וי\"ל שזהו גם החילוק דכלי המקדש: הארון הי' באופן תמידי במקדש (ראה רמב\"ם הל' ביהב\"ח רפ\"ד — נתבאר בארוכה בלקו\"ש חכ\"א ע' 158 ואילך) — נצחי והעדר השינוי שבמקדש (וראה לקו\"ש חט\"ז ע' 471 ואילך); שאר הכלים — שינויים."],["23","23","ראה יומא כח, ב: א' תושב\"כ וא' תושבע\"פ."],["24","24","ראה המשך הלשון ברמב\"ם שם."],["25","25","ראה רמב\"ם בהקדמה שם. וראה בריש הל' ממרים. קרית ספר להמבי\"ט בהקדמה פ\"א ופ\"ב."]]],[1300291191,"פון אַ וואָרט אָדער אפילו אַן אות בתורה קומט אַן אריכות אין תושבע\"פ26, און פון די אריכות פון די תנאים — קומט נאָך אַ גרעסערע אריכות פון די אמוראים א. ז. וו. — ביז דער לאפשה לה פון אַ תלמיד ותיק, וואָס דאָס אַלעס ווערט אַ חלק פון תושבע\"פ, וכמחז\"ל27 כל מה שתלמיד ותיק עתיד לחדש הכל ניתן למשה בסיני.\nאון דערמיט איז אויך פאַרבונדן דער חילוק אין אופן למודן: בתורה שבכתב מאַכט מען ברכת התורה בקריאתה, ווען אפילו לא ידע מאי קאמר28; בלימוד תורה שבע\"פ אָבער איז אויב לא ידע מאי קאמר קען מען קיין ברכת התורה ניט מאַכן29. לימודה30 איז פאַרבונדן מיט הבנת האדם, וועלכע איז פאַרשידן ביי בית שמאי אָדער בית הלל, כאָטש ביידע קיבלו פון די זעלבע שמעי' ואבטליון, וועלכע קיבלו דור מדור ביז צו משה רבנו וועלכער קיבל תורה פון דעם אויבערשטן — און מיט דער צייט איז דאָך צוגעקומען באַ יעדערן פון זיי בחכמה בינה ודעת התורה.\nועד\"ז זיינען דאָ די צוויי תנועות אין תורה שבע\"פ גופא: עס דאַרף זיין „לאפשה לה בכל יומא\"31, מחדש זיין אין תורה, אָבער עס מוז זיין פאַרבונדן און מיוסד נאָר אויף די כללים ויסודות פון תורה און אין פולסטער איינשטימונג מיט הלכה — וואָס אין זיי (די יסודות כללים והלכות) איז ניט שייך קיין שינוי, התורה זו לא תהי' מוחלפת32.\nאון כמרז\"ל הנ\"ל „כל מה שתלמיד ותיק עתיד לחדש הכל ניתן למשה בסיני\". דלכאורה איז דאָס אַ סתירה מיני' ובי': לחדש מיינט דאָך אַז דער תלמיד האָט עס מחדש33 געווען בשכלו, איז ווי זאָגט מען אַז דאָס איז ניתן למשה בסיני?\nנאָר דער ביאור בזה (ווי גערעדט פיל מאָל<sup data-n=\"34\">34</sup>: די סברא פרטית איז אַ חידוש פון דעם תלמיד ותיק\n[וואָס כל איש מישראל איז מחוייב צו לערנען אַלס וואָס עס שטייט בתושב\"כ און בתושבע\"פ און ער דאַרף אויך „לחדש . . הן בהלכות הן באגדות הן בנגלה הן בנסתר\"35];\nגעבויט אויף די כללים וועלכע משה האָט מקבל געווען בסיני, און דער „חידוש\" באַשטייט — אין דעם וואָס ער איז מגלה די סברא והלכה פרטית מן הכלל36 — כהלכה\nאויב ניט, ר\"ל, איז עס כפשוט היפך התורה, און כדבר המשנה37 „המגלה פנים בתורה שלא כהלכה, אף על פי שיש בידו תורה ומעשים טובים, אין לו חלק לעולם הבא\".",[["26","26","לקו\"ת ברכה צה, ד."],["27","27","ראה מגילה יט, ב. ירושלמי פאה פ\"ב ה\"ד. שמו\"ר רפמ\"ז. ויק\"ר רפכ\"ב. ובכ\"מ. וראה הערה 33."],["28","28","הל' ת\"ת לאדה\"ז פ\"ב סי\"ב. לקו\"ת ויקרא ה, ב — מפרדס שכ\"ז פ\"א."],["29","29","שו\"ע אדה\"ז או\"ח ס\"נ ס\"ב (ממג\"א שם סק\"ב). וראה הל' ת\"ת שלו ספ\"ב."],["30","30","ראה לקו\"ת שם."],["31","31","זח\"א יב, ב."],["32","32","ראה לקמן ריש ס\"ז. וש\"נ. וראה בארוכה לקו\"ש חכ\"ג ע' 33 (ואילך)."],["33","33","במקומות שבהערה 27 לא נאמר הלשון „לחדש\" כ\"א „להורות\", „לומר\" וכיו\"ב. אבל כן הוא בכ\"מ — ראה הנסמן בלקו\"ש חי\"ט ע' 252 הערה 21. וראה שם ע' הנ\"ל ואילך."],["34","34","ראה לקו\"ש שם."],["35","35","אגה\"ק סכ\"ו (קמה, א). וראה הל' ת\"ת לאדה\"ז פ\"ב ס\"ב."],["36","36","ו(לפעמים) חידוש גדול הוא זה ועד ש„תשש כחו\" של בעל הכלל (מנחות כט, ב)."],["37","37","אבות פ\"ג מי\"א."]]],[1300291192,"ו. בתפלה:\nכללות התפלה איז אַ ציווי לכל נפש38, און בכל יום ויום; לאידך איז תפלה — עבודה שבלב39. וואָס לב כאו\"א איז בשווה ער הוא להקב\"ה40, נאָכדעם קומען פרטי הרגש שבלב וואָס אין דעותיהן שוות41 און דערפאַר איז פרטי הכוונה ועבודת הלב זיינען פאַרשידן42 אויך פאַרשידן בעבודתם מיום ליום.\n[ועד\"ז אין דער תפלה שבכל יום גופא: אַ איד איז הולך ועולה במשך היום ובפרט אין זיין עבודה בהתפלה מדרגא לדרגא בכוונת הלב ובדביקותו בה', ביז ער קומט צו דער עבודה פון שמו\"ע ווען ער שטייט „כעבדא קמי' מרי'\"43].\nדי צוויי ענינים זיינען אויך דאָ אין נוסח התפלה גופא: די ג' ראשונות וג' אחרונות זיינען בשוה44 בכל התפלות ובכל ימות השנה; משא\"כ די ברכות אמצעיות מוז אין זיי זיין שינויים: ימות החול — י\"ב אמצעיות דבקשת צרכיו (ובהם גופא שינוי מזמן לזמן), שבת, ר\"ח, יו\"ט, ר\"ה, יוהכ\"פ וכו'.\nאָבער די שינויי נוסח גופא קומען בהמשך און זיינען אַלע פאַרבונדן מיט די זעלבע ג' ראשונות וג' אחרונות וואָס זיינען גלייך בכל תפלה ותפלה.\nז. במצות:\nמנין המצות וקיומן איז באופן פון לא תוסיף עליו ולא תגרע ממנו45 — „דבר46 ברור ומפורש בתורה שהיא מצוה עומדת לעולם ולעולמי עולמים אין לה לא שינוי ולא גרעון ולא תוספת\": דערנאָך קומט די זאַך פון הידור מצוה, וואָס דער מענטש דאַרף מהדר זיין און מעלה זיין בקודש47 בקיום המצות48: ניט נאָר כדבעי למעבד49 נאָר מהדרין, מהדרין מן המהדרין50; ע\"פ דין — לפנים משורת הדין, וכיו\"ב.\nח. דער טעם וואָס די עבודה פון אידן איז אויסגעשטעלט אין די צוויי קוין: וויבאַלד תורה און מצות זיינען געגעבן געוואָרן פון דעם אויבערשטן צו אידן, זיינען דאָ אין דעם ביידע ענינים כביכול: דאָס איז תורתו ומצותיו של הקב\"ה; און ס'איז די עבודה פון אידן, מקבלי התורה והמצות51.",[["38","38","ראה רמב\"ם ריש הל' תפלה. שם ה\"ד."],["39","39","נאמר (עקב יא, יג) ולעבדו בכל לבבכם אמרו חכמים (תענית ב, א) אי זו היא עבודה שבלב זו תפלה (רמב\"ם ריש הל' תפלה)."],["40","40","ראה שהש\"ר עה\"פ (שה\"ש ה, ב) אני ישנה ולבי ער."],["41","41","ברכות נח, א."],["42","42","להעיר מתניא פכ\"ט (לו, ב) „והלב יש בו בחי' ומדריגות רבות\". וראה קונטרס העבודה פ\"ד ואילך ובהמכתב שבסוף הקונטרס שם (נדפס גם באגרות קודש אדמו\"ר מהוריי\"ץ ח\"ב ע' שי ואילך) — כמה מדריגות באהבת ה' שבתפלה."],["43","43","שבת י, רע\"א. שו\"ע אדה\"ז סו\"ס צה."],["44","44","אלא שיש בהן הוספות בעשי\"ת."],["45","45","ראה יג, א. וראה גם ואתחנן ד, ב."],["46","46","ל' הרמב\"ם הל' יסוה\"ת רפ\"ט (ומביא הכתוב דפ' ראה). וראה גם רמב\"ם הל' מעה\"ק ספ\"ב. הל' מלכים פי\"א סה\"ג. פיהמ\"ש סנהדרין הקדמה לפ' חלק היסוד התשיעי."],["47","47","ברכות כח, א. וש\"נ."],["48","48","וי\"ל שזהו גם ב' הפרטים במצות תק\"ש שכתב הרמב\"ם (הל' תשובה פ\"ג ה\"ד) „אע\"פ שתק\"ש בר\"ה גזירת הכתוב רמז יש בו כו' עורו ישנים משנתכם וכו'\": גזה\"כ מדגיש שזוהי גזירה מלמעלה, בחי' „נצבים\" ובלתי משתנה שבשופר; וענין התשובה המרומז בשופר (שפרו מעשיכם) הוא עבודת ישראל, בחי' שינוי „וילך\"."],["49","49","להעיר מכתובות סז, רע\"א."],["50","50","שבת כא, ב."],["51","51","וראה בארוכה הדרן (הא') על מס' פסחים (נדפס בהגש\"פ עם לקוטים טעמים כו' וביאורים — קה\"ת, תשמ\"ז ושלאח\"ז — ע' תסד ואילך), הדרן על אבות (נדפס בס' ביאורים לפרקי אבות (קה\"ת) בסופו. לקו\"ש חי\"ז ע' 395 ואילך) — שלכן יש"]]],[1300291193,"און דאָס דריקט זיך אויס אין די צוויי קוין הנ\"ל: אין דעם בלתי שינוי פון תורה ומצות איז מודגש דער נותן התורה ומצווה המצות — דער אויבערשטער, וואָס איז בלתי משתנה, אני ה' לא שניתי52; און מצד דעם וואָס דער ענין פון תורה ומצות איז די עבודה פון אידן (בלימוד התורה וקיום המצות) — וואָס דער גדר פון אַ נברא איז וואָס ער איז אַ בעל שינויים און דאַרף זיין אַ מהלך, ניט ווי העומדים האלה53, וואַקסן — איז די עבודה פון תומ\"צ אויסגעשטעלט באופן אַז עס איז דאָ די הליכה מחיל אל חיל בעבודת ה', דער שינוי (ועלי') תמידי.\nאון דאָס איז אויך דער טעם וואָס אתם נצבים און וילך זיינען ניט נאָר צוויי סדרות וואָס ווערן לפעמים נצטרף, נאָר זיי זיינען בעצם איין סדרה — ווייל דער כללות הענין פון עבודת ה' „מאָנט\" ביידע זאַכן: „נצבים\" — דער בלתי שינוי, מצד דעם נותן התורה ומצווה המצות (און דערפאַר שטייט „נצבים\" לשון נפעל54 — ווייל דער אמת'ר תוקף ובלי שינוי קומט מלמעלה); און „וילך\" — די הליכת האדם מחיל אל חיל.\nאון דערפאַר איז דאָס איין סדרה, ווייל אין יעדער עבודה פון „וילך\" — תנועה פון שינוי, מוז דער יסוד זיין דער חלק פון תומ\"צ פון „נצבים\", ווי עס קומט פון (נצבים —) „אני ה' לא שניתי\".\nט. וי\"ל אַז דאָס איז אויך דער ביאור אין תורת הבעש\"ט הנ\"ל בנוגע לברכתו של הקב\"ה אין דעם שבת האחרון דחודש אלול — אַז די ברכה איז וואָס „קורין אז פרשת אתם נצבים\" — און ווי גערעדט פריער (סעיף ב) אַז אין דעם זיינען פאַראַן צוויי ענינים: די עצם ברכה איז פאַרבונדן מיט „אתם נצבים\"; און דאָס וואָס „בכח זה ישראל מברכים את החדשים י\"א פעמים בשנה\" איז פאַרבונדן מיט (דעם צווייטן טייל פון „פרשת אתם נצבים\" —) „וילך משה\":\nדי עצם ברכה איז „ברכתו של הקב\"ה\" — ס'איז אַ ברכה וואָס דער אויבערשטער אַליין בענטשט דעם חודש. דערפאַר וואָס דאָס איז אַ ברכה וואָס איז העכער פון גדר הנבראים. און דערפאַר איז די ברכה פאַרבונדן מיט דעם מצב אַז „אתם (זיינען) נצבים\" — דער בלתי שינוי וועלכער איז פאַרבונדן מיט „לפני ה' אלקיכם\", „אני ה' לא שניתי\"55.\nאון דערנאָך ווערט די ברכה נמשך אין אַן אופן וואָס „בכח זה ישראל מברכים את החדשים\" — וואָס דאָס איז פאַרבונדן מיט עבודת ישראל. און דערפאַר איז דער ענין שייך צו „וילך\", די עבודה פון אידן, הליכה מחיל אל חיל; אָבער אויך דאָס איז אַ המשך (אַ טייל) פון ברכתו של הקב\"ה56 — וכנ\"ל, אַז",[["","","בתורה ומצות גדרים מצד הנותן וגדרים מצד המקבלים, ראה שם כמה דוגמאות."],["52","52","מלאכי ג, ו."],["53","53","זכרי' ג, ז ובמפרשים שם. שמו\"ר פכ\"ה, ב. זח\"ב קע, א. זח\"ג רס, א. תו\"א ס\"פ וישב. אוה\"ת שם (כרך־ה תתקיג, א ואילך). ועוד."],["54","54","ראה אוה\"ת נצבים ע' א'קפט ואילך."],["55","55","ע\"פ הנ\"ל מובן הטעם שאין ישראל מברכין גם חודש תשרי, דלכאורה אף שהקב\"ה בעצמו מברכו, גם ישראל יברכו אותו או יאמרו הברכה (ע\"ד ברכת כהנים)? אלא לפי שהברכה אז היא מבחי' „נצבים\" שלמעלה משינויים, למעלה מעבודת האדם לגמרי, ובבחי' זו אין מקום לעבודת האדם. וראה לקו\"ש חי\"ח ע' 354 ובהערה 25 שם."],["56","56","עפ\"ז אולי יש לבאר הלשון בהתורה „ובכח זה ישראל מברכים את החדשים (ורק אח\"כ מוסיף) י\"א פעמים בשנה\". דלכאורה הול\"ל בקיצור „ובכח זה ישראל מברכים י\"א חדשי השנה\"? אלא דהכח דישראל כפי שהוא בשבת מברכים — ה\"ז עדיין"]]],[1300291194,"„וילך\" איז ניט אַ באַזונדער סדרה, נאָר אַ טייל פון „פרשת אתם נצבים\", ווייל דער „וילך\" פון אידן, איז מיוסד און פאַרבונדן מיטן „אתם נצבים\", מיט דער נתינה מלמעלה.\nאָבער, וויבאַלד אַז בפועל ובגלוי איז דאָס וואָס „ישראל מברכים את החדשים\" ברכת ועבודת האדם, דעריבער57 איז ניט מוכרח אַז דאָס זאָל אַלעמאָל זיין בגלוי אין דעם שבת פאַר ראש השנה, ובמילא לייענט מען ניט אַלעמאָל פרשת וילך לפני ר\"ה, אַמאָל ווערט עס געלייענט בשבת שלאחרי (אָבער בסמיכות צו) ראש השנה.\nיוד. דאָס וואָס מען לייענט פרשת אתם נצבים אין דעם שבת האחרון פון חודש אלול, איז ניט נאָר אַלס הכנה צו שנה הבאה בכלל (מצד דעם וואָס אין דעם שבת ווערט נמשך ברכתו של הקב\"ה), נאָר י\"ל, אַז דאָס איז אויך פאַרבונדן מיט דער עבודה פון ראש השנה עצמה, וואָס דערפאַר איז „פרשה זו (נצבים) קורין לעולם קודם ר\"ה\"58.\nועפ\"ז — זיינען די צוויי קוין הנ\"ל אין נצבים און וילך, אויך דאָ אין דער עבודה פון ראש השנה.\nוועט מען דאָס פאַרשטיין בהקדים — וויבאַלד אַז עס זיינען דאָ די צוויי קוין אין תורה ומצות עצמן, איז מובן, אַז פריער זיינען זיי דאָ אין דעם נותן התורה ומצווה המצות, כביכול. וואָס דאָס זיינען די צוויי ענינים — תענוג און רצון:\nאין תורה ומצות איז פאַראַן דאָס וואָס עס איז רצון העליון ב\"ה, און דאָס וואָס עס איז דער עונג העליון ב\"ה59, נחת רוח לפני שאמרתי ונעשה רצוני60. און דעם חילוק צווישן זיי61 וויבאַלד אַז דברה תורה כלשון בנ\"א — וועט מען פאַרשטיין דערפון ווי דאָס איז אין נפש האדם למטה (ובפרט אַז די כחות הנפש ווערן דאָך נשתלשל פון למעלה<sup data-n=\"62\">62</sup>. ביידע כוחות — סיי תענוג און סיי רצון — זיינען (ניט פון די כוחות הפנימיים של הנפש וואָס יעדערער פון זיי איז אַ כח פרטי, נאָר) פון די כוחות מקיפים, וואָס דאָס מיינט: כוחות כלליים, אין וועלכע די נפש (אינגאַנצן) גיט זיך אַרויס. דער חילוק צווישן זיי איז — אין אופן „גילוי הנפש\" שבהם, אין וועלכע עס זיינען פאַראַן צוויי אופנים:\nרצון — וואָס איז אויך מלשון רץ: די (גאַנצע) נפש וויל, ציט זיך, לויפט צו אַ זאַך וואָס איז חוץ ממנה, תענוג איז פאַרקערט — ס'איז אַן ענין פון מנוחה, און אמת'ר תענוג ובפרט שלימות פון תענוג איז ווען דער אדם איז זיך מתענג בעצמותו63.\nאון דאָס זיינען די צוויי ענינים פון „נצבים\" און „וילך\", בלתי שינוי און שינוי למעלה כביכול: עונג — די מנוחה",[["","","בבחי' כלל, וכמו שהם כלולים בכח, בברכתו של הקב\"ה, הרי נרגש לא י\"א חדשי השנה, כ\"א חדשים סתם (ורק שאח\"כ נתפרט י\"א פעמים בשנה)."],["57","57","וראה לקו\"ש חי\"ט ע' 299 ואילך."],["58","58","לקו\"ת ר\"פ נצבים. ועד\"ז הוא בשאר המקומות שנסמנו לעיל הערה 8."],["59","59","ראה לקו\"ת במדבר יח, א־ב. אוה\"ת ר\"ה (כרך ה) ע' ב'קי ואילך (פ\"ג). ועוד. אלא ששם מדובר בהארת העונג שהוא מחולק בכל מצוה, ובפנים מדובר ע\"ד שרש העונג, מקור התענוגים, שאין בו התחלקות (ראה אוה\"ת שם פ\"ב, פ\"ד ואילך). וראה לעיל ע' 101 ואילך."],["60","60","ספרי ופרש\"י פינחס כח, ח. ועוד."],["61","61","ראה בהבא לקמן המשך תרס\"ו ע' סג ואילך. ועוד."],["62","62","ראה תניא רפ\"ג."],["63","63","ראה גם סה\"מ תרנ\"ז ע' קעד. ועוד. ולהעיר מאוה\"ת שם פ\"ד."]]],[1300291195,"באמיתתה ובשלימותה, בעצמותו — אַן ענין פון העדר השינוי; און רצון — ריצה והטי' — אַן ענין של תנועה ושינוי.\nיא. וויבאַלד אַז בראש השנה דאַרף מען אויפטאָן דעם „תמליכוני עליכם\"64, אַז דער אויבערשטער זאָל ווערן אונזער מלך — איז דאָס פאַרבונדן מיט די ביידע תנועות: פריער דאַרף מען אויפטאָן למעלה, כביכול, דעם עונג65 אין ענין המלוכה, און דערנאָך — דעם רצון66 למלוכה67.\nאון דעריבער פאָדערט זיך פון אידן — וואָס דאַרפן אויפטאָן דעם „תמליכוני\" — צוויי תנועות, ובלשון תפלת ראש השנה68: אם כבנים אם כעבדים. וואָס דער פירוש הפנימי אין דעם איז69, אַז בר\"ה מאָנען זיך און זיינען דאָ בפועל ביידע אופני עבודה — סיי אַלס בנים און סיי אַלס עבדים (ווי מען זאָגט: אבינו מלכנו). וואָס דער חילוק ביניהם איז70: בן איז פאַרבונדן מיט עצמות אביו, און דער אב איז זיך משתעשע ומתענג בבנו (ווי דער מגיד איז מאריך בראש ספריו<sup data-n=\"71\">71</sup>, עבד איז מקיים רצון האדון (המלך).\nאון דאָס איז די שייכות פון די צוויי ענינים הנ\"ל אין דער קריאה פון פרשת אתם נצבים — „נצבים\" ובלתי שינוי, און „וילך\" שינוי — צו דער עבודה פון ראש השנה,\nווייל דורך דער עבודה פון אידן אין די צוויי תנועות פון „אם כבנים אם כעבדים\" טוען אויף אידן די (המשכת ה)מלוכה פון דעם אויבערשטן („תמליכוני עליכם\") — אין ביידע ענינים פון עונג און רצון, כנ\"ל.\nיב. דער שרש פון די ביידע תנועות הנ\"ל — איז איין נקודה (וואָס דערפאַר זיינען נצבים וילך בעצם איין סדרה, כנ\"ל): דער ביטול עצמי פון אַ אידן מצד עצם נפשו, וואָס איז העכער סיי פון רצון און סיי פון תענוג; וואָס מצד דעם איז אַ איד בוחר, כביכול, אין דעם אויבערשטן, ווייל זיי זיינען עצם אחד [נאָר בפועל קומט דאָס אַרויס, און דריקט זיך אויס אין צוויי תנועות פון בנים ועבדים].\nאון דאָס פועל'ט די בחירה שלמעלה אין אידן, „יבחר לנו את נחלתנו\"72, פון עצמות ומהות73, וואו אידן זיינען איין זאַך, כביכול, מיטן אויבערשטן74, און דאָס קומט אין די צוויי תנועות אין וועלכע עס ווערט נמשך „תמליכוני עליכם\", תענוג און רצון.\nאון בשעת מען לייענט פרשת אתם נצבים בשבת שלפני ר\"ה, ווערט שוין",[["64","64","ר\"ה טז, סע\"א. שם לד, ב."],["65","65","ראה גם לקו\"ת נצבים מט, ד. סדור ד\"ה להבין ענין תק\"ש ע\"פ כוונות הבעש\"ט."],["66","66","ראה גם ד\"ה יו\"ט של ר\"ה תרס\"ה. תש\"ג. ועוד."],["67","67","ראה לקו\"ת ר\"ה נו, ג ואילך. ועוד."],["68","68","פיוט היום הרת עולם. ולהעיר מב\"ב י, א."],["69","69","ראה ד\"ה אחרי ה\"א תלכו תרצ\"ז (סה\"מ קונטרסים ח\"ב בהוספות). וראה ד\"ה זה היום תשי\"ז."],["70","70","ולהעיר מדרך מצותיך קח, ב."],["71","71","לקו\"א ואו\"ת."],["72","72","תהלים מז, ה — המזמור שאומרים לפני תק\"ש."],["73","73","דמכיון דהרצון והעונג שבמלכות, שהוא הפנימיות שבמלכות, עולה ומסתלק למעלה, הרי מובן שצריכים „להגיע\" ולהמשיך מעצמות א\"ס שלמעלה גם מתענוג ורצון. ועד\"ז בנפש, שצ\"ל עבודה שמצד עצם הנפש שלמעלה מתענוג ורצון (ראה בכ\"ז — בהמקומות שנסמנו בהערות 65־67). וראה בהנסמן בהערה הבאה."],["74","74","ראה לקו\"ש ח\"ד ע' 1147 ואילך. ח\"ט ע' 212. ועוד."]]],[1300291196,"תיכף, גלייך דעמאָלט אויפגעטאָן דער „אתם נצבים קיימים ועומדים והיינו שזוכין בדין\"75 — „ברכתו של הקב\"ה בשבת מברכים חודש השביעי שהוא המושבע והמשביע76 ברוב טוב לכל ישראל על כל השנה\"77,\nאון עס ווערט נמשך אין אַ כתיבה וחתימה טובה לשנה טובה ומתוקה לכל אחד ואחת מישראל בטוב הנראה והנגלה למטה מעשרה טפחים, כפשוטו ממש.\n(משיחות ש\"פ נצו\"י תשמ\"ב, ו' תשרי, י\"ג תשרי תשד\"מ)",[["75","75","ע\"פ תורת הבעש\"ט הנ\"ל יומתק מה שהובא בטור (או\"ח סו\"ס תקפא) דישראל „לובשים לבנים ומתעטפים לבנים כו' ואוכלין ושותין ושמחים בר\"ה לפי שיודעין שהקב\"ה יעשה להם נס\", שזה שיודעין ובטוחים בר\"ה (ועוד לפני ר\"ה — ראה טור שם) הוא מצד הברכה כו' שזוכים בדין דשבת נצבים."],["76","76","ראה ויק\"ר פכ\"ט, ח. קיצורים והערות לתניא ע' נח."],["77","77","סיום תורת הבעש\"ט שם."]]],[1300291197,"<h3>ר\"ה - ו' תשרי*</h3>\nא. אין מס' ברכות1 זאָגט די גמרא „אמר רב המנונא כמה הלכתא גברוותא2 איכא למשמע מהני קראי דחנה3 וחנה היא מדברת על לבה מכאן למתפלל צריך שיכוין לבו, רק שפתי' נעות מכאן למתפלל שיחתוך בשפתיו, וקולה לא ישמע מכאן שאסור להגבי' קולו בתפלתו, ויחשבה כו'\".\nוצריך ביאור: אַלע ענינים אין תורה זיינען מדויק בתכלית, דער ענין פון תפלה שטייט שוין אין (די חמשה חומשי) תורה, וכמה פעמים אָנהויבנדיק פון תפלות אברהם4 יצחק5 ויעקב6, תפלת משה7 א.א.וו.8 — ווי קומט עס אַז דער מקור אויף „כמה הלכתא כו'\" איז דוקא אין תפלת חנה (אין חלק הנביאים, דברי קבלה) און ניט אין די תפלות וואָס שטייען אין תורה?\nלכאורה וואָלט מען געקענט זאָגן אַז תפלת חנה איז מיוחדת בזה וואָס זי איז אַ תפלה אויף אַ דבר עיקרי וכללי — אויף האָבן קינדער — „ונתת לאמתך זרע אנשים\"9, וואָס דאָס איז אַ זאַך וועלכע איז נעלית ביותר, און דאָס איז איינע פון די „מפתחות\" וואָס איז „בידו של הקב\"ה (שלא נמסרו ביד שליח)\"10, וואָס בכלל איז צו עם איז מען מתפלל, און דוקא צו עם11.\nאון ס'איז אויך נוגע ביותר, ובלשון רחל12 „ואם אין מתה אנכי\"13.\nאון ווייל דער תוכן ומבוקש פון תפלת חנה איז אַן ענין נעלה ביותר, דערפאַר איז די תפלה אַ יסוד ומקור פון וואַנען מ'לערנט אָפּ „כמה הלכתא גברוותא\" אין תפלה.\nמ'קען אָבער אַזוי ניט פאַרענטפערן, וואָרום אויך די תפלה פון יצחק14 (ורבקה) איז דאָך געווען ממש אויפן זעלבן ענין עיקרי, אויף קינדער —",[["","","*) הוא יום היארצייט של הרבנית הצדקנית מרת חנה תנצב\"ה (אמו של — יבלח\"ט — כ\"ק אדמו\"ר שליט\"א). נסתלקה שבת תשובה בעת עלות המנחה שנת תשכ\"ה."],["1","1","לא, סע\"א."],["2","2","כ\"ה בגמ' ובע\"י: גברוותא. ובשינוי — ראה רי\"ף ודק\"ס כאן. סוכה לח, ריש ע\"ב ובר\"ח, רי\"ף ור\"ן שם. ואכ\"מ."],["3","3","ש\"א א, יג ואילך."],["4","4","בנוגע לסדום (וירא יח, כג (ובפרש\"י שם) ואילך); על אבימלך (שם כ, יז. וראה שם, ז). וראה ברכות כו, ב. לקמן הערה 14."],["5","5","ח\"ש כד, סג ובפרש\"י שם (מברכות שם. ועוד). תולדות כה, כא (ופרש\"י שם)."],["6","6","ויצא כח, יא ופרש\"י שם (מברכות שם). וישלח לב, יו\"ד ואילך (ופרש\"י שם, ט)."],["7","7","ובפרט תפלתו ויחל משה גו' (תשא לב, יא ואילך) וכו' שמסופר בתורה אריכות התפלות."],["8","8","לדוגמא: וירא יט, יח (ופרש\"י) ואילך. ח\"ש כד, יב ואילך. ועוד."],["9","9","ש\"א שם, יא."],["10","10","ראה תענית ב, סע\"א ואילך: מפתח של חי' כו' דכתיב (ויצא ל, כב) ויזכור אלקים את רחל גו' ויפתח את רחמה."],["11","11","כל' הרמב\"ם (פיה\"מ פ' חלק היסוד החמישי): שהוא ית' הוא הראוי לעבדו . . אליו בלבד יכוונו המחשבות. וכהדגשת מחז\"ל: אליו ולא למדותיו (אפילו, ועאכו\"כ לא לשליח) — פרדס של\"ב פ\"ב בשם הספרי."],["12","12","ויצא ל, א. וראה הערה 10."],["13","13","וכמו שהי' בחנה „והיא מרת נפש\" — ש\"א שם, יו\"ד. וראה ברכות (ל, ב), דר' אליעזר למד דאין עומדין להתפלל אלא מתוך כובד ראש „דאמר קרא והיא מרת נפש\". ובגמ' שם: אמאי דילמא חנה שאני דהות מרירא לבא טובא. וראה צל\"ח שם."],["14","14","משא\"כ באברהם שלא נאמר באופן של תפלה — ראה לך טו, ב־ג."]]],[1300291198,"„ויעתר יצחק לה' לנוכח אשתו (ווי רש\"י טייטשט „הרבה והפציר בתפלה\") כי עקרה היא\"15!\nב. מ'קען אויך ניט פאַרענטפערן, אַז פון די תפלות של האבות וואָלט מען ניט געקענט אָפּלערנען, היות „אין למידין מקודם מ\"ת\"16 —\nווייל, ערשטנס, רעדט זיך דאָ ניט וועגן אַ לימוד (ממש) פון פסוק, נאָר וועגן אַ גילוי מילתא (כעין אסמכתא<sup data-n=\"17\">17</sup> ווי ס'דאַרף זיין18 דער אופן ההנהגה בתפלה; ובפרט אַז דער גאַנצער (ענין ו)סדר התפלה זאָגט דאָך די גמרא19 אַז „תפלות אבות תקנום\" — „אברהם תקן תפלת שחרית שנאמר כו' יצחק תקן תפלת מנחה שנאמר כו'\".\nזאת ועוד: בנוגע אַ טייל פון די „הלכתא גברוותא\", וואָס „איכא למשמע מהני קראי דחנה\", זאָגט דער מהרש\"א20 אַז „כמה דברים דחשיב הכא כגון שצריך שיכוין את לבו ואסור להשמיע קולו שמעינן להו נמי ממקומות אחרים כדלעיל אלא דקאמר דמהני קראי דחנה נמי איכא למשמע להו\".\nולפ\"ז: אָט די „דברים\" וואָס „שמעינן להו נמי ממקומות אחרים\" האָבן דאָך געוויס געקענט זיין מרומז אין איינע פון די תפלות האבות, וואָס דעמאָלט איז עס אינגאַנצן ניט בסתירה צו „אין למדין מקודם מ\"ת\", וויבאַלד דאָס איז ניט דער איינציקער מקור אויף די הלכות.\nמוז מען זאָגן, אַז דאָס וואָס חז\"ל זיינען מדייק ומדגיש „כמה הלכתא גברוותא איכא למשמע מהני קראי דחנה\" איז דאָס דערפאַר וואָס בתפלת חנה געפינט מען אַ חידוש מיוחד אין דעם גדר התפלה.\nג. ויש לומר הביאור בזה:\nאין תוכן התפלה זיינען דאָ צוויי כללית'דיקע סוגים: ס'איז דאָ אַ תפלה וואָס „אדם מתחנן ומתפלל בכל יום\"21, והיינו אויף די צרכים הרגילים והתמידיים וואָס אַ מענטש נויטיקט זיך אין זיי יעדן טאָג; און עס איז דאָ די תפלה „בעת מן העתים אשר יצטרך לדבר מן הדברים, כמו22 בעת צרה וכיוצא\"23.\nאון אפילו די פוסקים וואָס זאָגן24, אַז „תפלה בכל יום והנוסח התפלה הוא מצוה מדרבנן\"25, האַלטן זיי אָבער, אַז ס'איז אַ מצוה מדאורייתא „שיתפלל האדם . . בעת צרה\" וכיו\"ב, ווען ער דאַרף אַ דבר מיוחד.\nוההסברה אין דעת הפוסקים אלו איז מובן ע\"פ המבואר בכ\"מ אין דעם גדר התפלה און — ווי דער גדר איז מחולק פון גדר הברכה26:",[["15","15","תולדות שם."],["16","16","ראה שד\"ח כללים מערכת האל\"ף כלל שכא. פאת השדה כללים מערכת אלף סקל\"ה ס\"י. אנציקלופדי' תלמודית בערכו."],["17","17","דהרי זה נלמד מדברי קבלה, ופשיטא ד„הלכתא גברוותא\" אלו אינן מדאורייתא — וראה לקו\"ש ח\"ו ע' 322 ואילך."],["18","18","ראה במקומות שבהערה 16. וראה לקו\"ש חכ\"ה ע' 142 ואילך."],["19","19","ברכות כו, ב. — וראה בית האוצר (להר\"י ענגל) מערכת הא' כלל א' אות ז'."],["20","20","בחדא\"ג ברכות שם (לא, סע\"א) ד\"ה מהני קראי. וראה צל\"ח שם."],["21","21","ל' הרמב\"ם הל' תפלה פ\"א ה\"ב."],["22","22","ראה רמב\"ן וחינוך שבהערה 25."],["23","23","ל' הצ\"צ בשרש מצות התפלה בתחלתה."],["24","24","ודלא כדעת הרמב\"ם שם."],["25","25","ל' הצ\"צ שם — לדעת „רוב מוני המצות כמו הסמ\"ק והרשב\"ץ (וכ\"ד הרמב\"ן בחינוך שם)\". וראה רמב\"ן בסהמ\"צ מ\"ע ה. חינוך מצוה תלג."],["26","26","ראה לקו\"ת ראה יט, רע\"א. ד\"ה כה תברכו תרכ\"ו. ובכ\"מ."]]],[1300291199,"ברכה איז מלשון „בריכה\" — אַ מקום ריכוז פון מים27 וכיו\"ב, וואָס פון דאָרט איז מען ממשיך די מים לויט די צרכים ופרטים המתאימים. און ברכה איז אויך פון לשון „המבריך\"28, וואָס פירושו איז המשכה, ברכה איז ענינה צו ממשיך זיין אַ זאַך ממקורו.\nדאָס הייסט: דער אויפטו פון ברכה איז נאָר — ווען דער ענין (פון דער ברכה) איז שוין דאָ (במקורו), נאָר מאיזו סיבה האַלט זיך עס אָפּ פון נמשך ווערן להמתברך — און די ברכה פועל'ט אַז דאָס זאָל נמשך ווערן פון מקור און אַראָפּקומען למטה. ובלשון הפסוק29: איש אשר כברכתו ברך אותם — מיט דער ברכה, וואָס איז געווען ראוי און צוגעגרייט פאַר יעדן איינעם, דערמיט האָט ער זיי געבענטשט, ד.ה. די ברכה האָט ממשיך געווען צו יעדן איינעם למטה דאָס וואָס עס איז געווען אין מקור למעלה.\n[און ווי עס ברענגט זיך אויף דעם די ראי' פון דער ברכה וואָס יעקב האָט געבענטשט די בני יוסף, אַז יעקב האָט אַרויפגעלייגט30 „ימינו . . על ראש אפרים . . ואת שמאלו על ראש מנשה\", און יוסף האָט אים געזאָגט31 „כי זה הבכור שים ימינך על ראשו וימאן אביו . . אחיו הקטן יגדל ממנו וזרעו יהי' מלא הגוים\". דלכאורה, וויבאַלד אַז יעקב איז דער וואָס איז זיי מברך, האָט ער דאָך געקענט בענטשן מנשה'ן מיט דער ברכה גופא, אַז ער זאָל זיין גרעסער פון אפרים?\nנאָר דער ענין איז כנ\"ל: ברכה טוט ניט אויף קיין נייע זאַך — עס איז בלויז ממשיך („מבריך\") דעם ענין הברכה פון מקור. דערפאַר האָט יעקב ניט געקענט פועל'ן מיט זיין ברכה, אַז מנשה זאָל זיין גרעסער פון אפרים, ווייל דאָס איז ניט געווען אין מקור].\nאָבער תפלה איז ענינה, וואָס מ'בעט דעם אויבערשטן — „יהי רצון\" (וכיו\"ב), אַז ס'זאָל ווערן אַ רצון, אַ דבר חדש, וואָס איז ניט געווען פריער.\nועפ\"ז איז מובן דער טעם פון די דיעות וואָס האַלטן אַז גדר מצות התפלה איז דוקא בעת מן העתים כמו בעת צרה וכיו\"ב, וואָרום תפלה איז עיקר ענינה „יהי רצון\", צו פועל זיין אַ דבר חדש — ניט ווי ס'איז געווען דער סדר ביז דאַן — און דער אויפטו פון תפלה איז ניט אויף אַזויפיל מתאים ביי אַ תפלה אויף די צרכים התמידים והרגילים שבכל יום (וואו עס איז ניט ניכר אַז מ'פועלט „יהי רצון\", אַ דבר חדש) נאָר דוקא ביי אַ תפלה אויף אַ שינוי וחידוש אין דער הנהגה — עס זאָל זיין אַ ריווח ישועה והצלה פון דער „עת צרה\" וכיו\"ב.\nעפ\"ז איז מובן, אַז דער גודל התפלה איז לפי ערך דעם גודל השינוי והחידוש אין דער זאַך אויף וועלכער ער איז מתפלל. און דערפאַר איז אע\"פ אַז אַ תפלה צו מבטל זיין עצירת גשמים אָדער לרפאות החולה וכיו\"ב איז ענינה יהי' רצון, צו פועל'ן אַ הנהגה חדשה וואָס זאָל זיין ניט כפי הגזירה כו' — קומט דאָס אָבער ניט צו דער תפלה אויף בנים פון אַן עקרה, וואָס דאָ דאַרף זיך אויפטאָן אַ חידוש וואָס איז היפך פון סדר הטבע, טבע (עקר ועקרה —) בריאתו של הקב\"ה. ומובן, אַז אין דעם פאַל דריקט זיך אויס דער תוקף ומעלת התפלה ביתר שאת כו'.",[["27","27","ישעי' כב — ט, יא."],["28","28","כלאים רפ\"ז. וראה תו\"א מקץ לז, ג."],["29","29","ויחי מט, כח. וראה פרש\"י שם."],["30","30","ויחי מח, יד."],["31","31","שם, יח־יט."]]],[1300291200,"ד. ועפ\"ז יובן בעניננו:\nאע\"פ אַז תפלה אויף בנים באופן הנ\"ל איז אַ גרויסע מעלה כנ\"ל (וואָס דער ענין איז געווען ביי די אבות כנ\"ל ס\"א), איז אָבער תפלת חנה מיוחדת בזה גופא.\nוהביאור: דער תוכן פון תפלת חנה איז כמ\"ש32 „ותדור נדר ותאמר ה' צבאות אם ראה תראה בעני אמתך . . ונתת לאמתך זרע אנשים גו'\", וואָס אויף דעם שטייט אין רש\"י (פון ילקוט) על אתר, אַז דערמיט האָט זי געמיינט „צדיקים\"33. ד.ה. זי האָט געבעטן צו האָבן ניט סתם קינדער, נאָר „זרע אנשים — צדיקים\";\nאון איר כוונה דערביי איז געווען ניט נאָר אַן ענין פון צדיק בכח (אַז ער זאָל האָבן די נשמה פון אַ צדיק<sup data-n=\"34\">34</sup> — נאָר אויך צדיק בפועל35, ווי זי האָט געזאָגט אין איר נדר (וואָס איז געווען אַ טייל און המשך פון איר תפלה) „ונתתיו לה' כל ימי חייו\", אַז ער וועט בפועל זיין נתון לה' כל ימי חייו.\nאון וויבאַלד אַז ס'איז דערנאָך געווען אַזוי ווי זי האָט מתפלל געווען — ס'איז ביי איר געבאָרן געוואָרן שמואל, וועלכער איז טאַקע בפועל36 געווען נתון לה' — איז מסתבר, אַז דאָס איז געקומען דערפאַר וואָס דער אויבערשטער האָט ממלא געווען איר תפלה ובקשה און איר געגעבן אַזאַ זון ווי זי האָט געבעטן37 (וואָס וועט בפועל זיין נתון לה').\nוואָס דאָס איז אַן ענין וועלכער איז היפך ניט בלויז פון דער הנהגת הטבע וואָס דער אויבערשטער האָט איינגעשטעלט אין וועלט, נאָר כביכול אויך העכער פון די הגבלות ווי זיי זיינען ע\"פ תורה:\nס'איז דאָך ידוע38, אַז „מלאך הממונה על ההריון כו' אומר לפניו (דהקב\"ה) רבש\"ע כו' גבור או חלש כו' ואילו רשע או צדיק לא קאמר\", ווייל38 „הכל בידי שמים חוץ מיראת שמים\". דער ענין הבחירה, דאָס וואָס „רשות39 לכל אדם נתונה אם רצה להטות עצמו לדרך טובה ולהיות צדיק הרשות בידו ואם רצה כו'\", איז „עיקר40 גדול הוא והוא עמוד התורה והמצוה\".\nקומט דאָך אויס אַז תפלת חנה איז געווען41 אויף אַן ענין וואָס איז ניט נאָר היפך הטבע וואָס הטביע הקב\"ה בעולמו, נאָר אויך ניט לפי די הגבלות והגדרות וואָס דער אויבערשטער האָט קובע געווען בתורתו און אַלס אַן עיקר גדול ועמוד.\nה. דער ענין הנ\"ל איז אויך נוגע להלכה:\nדי משנה זאָגט42: נזיר הי' שמואל כו' שנאמר32 ומורה לא יעלה על ראשו נאמר בשמשון43 ומורה ונאמר בשמואל ומורה מה מורה האמורה בשמשון נזיר44 אף מורה האמורה בשמואל נזיר.",[["32","32","ש\"א א, יא."],["33","33","להעיר מפרש\"י שלח יג, ג."],["34","34","ע\"ד הפי' בתניא פי\"ד בדברי איוב „בראת צדיקים\" (ב\"ב טז, א)."],["35","35","ראה ברכות שם (בהמשך הסוגיא — לא, ב) מאי זרע אנשים . . זרע ששקול כשני אנשים . . משה ואהרן."],["36","36","וראה בהנסמן בהערה שלפנ\"ז."],["37","37","וכמ\"ש גם בדברי עלי אל חנה (ש\"א א, יז), „ואלקי ישראל יתן את שלתך אשר שאלת מעמו\"."],["38","38","נדה טז, ב."],["39","39","ל' הרמב\"ם הל' תשובה רפ\"ה."],["40","40","רמב\"ם שם ה\"ג."],["41","41","להעיר מאהבת יהונתן להפטורת יום א' דר\"ה ד\"ה ויען עלי."],["42","42","סוף נזיר."],["43","43","שופטים יג, ה."],["44","44","ראה רש\"י ותוס' נזיר שם."]]],[1300291201,"און אַזוי פסק'נט דער רמב\"ם45 אַז „שמואל הרמתי נזיר עולם הי'\".\nאיז ידוע די שאלה46 אין דעם: ווי אַזוי האָט געקענט זיין די חלות הנזירות אויף שמואל'ן? דאָס וואָס חנה האָט געזאָגט אַ נדר „ומורה לא יעלה על ראשו\" האָט ניט דעם כח (ע\"פ תורה) אַז שמואל זאָל דורך דעם ווערן אַ נזיר: א) שמואל איז בעת נדרה נאָך ניט געווען בעולם. ב) אפילו ווען ער וואָלט דאַן געווען בעולם, איז „האיש מדיר את בנו בנזיר ואין האשה מדרת את בנה בנזיר\"47.\nמען האָט אַמאָל שוין גערעדט בארוכה48 אַז די חלות הנזירות (אויף שמואל'ן) האָט זיך אויפגעטאָן דורך דעם וואָס שמואל אַליין האָט דאָס גענומען אויף זיך: וויבאַלד אַז בעת ער איז געוואָרן אַ גדול האָט ער (ניט נאָר ניט מוחה געווען, נאָר ער האָט) ממשיך געווען די הנהגת הנזירות (לויט ווי חנה האָט זיך מיט אים געפירט פריער), האָט די הנהגה (הסכמה) גע'פועל'ט די חלות קדושת נזירות למפרע49.\nדערמיט איז נאָך מער מודגש דער אופן נעלה פון תפלת חנה ונדרה: כאָטש זי האָט געוואוסט אַז איר נדר אַליין קען ניט אויפטאָן אויף איר זון די קדושת הנזירות — אויב ער וועט דערצו ניט מסכים זיין, אעפ\"כ איז זי געווען זיכער אַז „מורה לא יעלה על ראשו\" — זי איז געווען בטוחה בתפלתה אַז ער וועט געוויס מסכים זיין לנדרה און וועט זיין אַ נזיר כל ימי חייו.\nו. ועפ\"ז יש לבאר די שייכות מיוחדת פון די „כמה הלכתא גברוותא\" צו תפילת חנה („איכא למשמע מהני קראי דחנה\"), אַז אַ „מתפלל צריך שיכוין לבו\", „שיחתוך בשפתיו\" אָבער „אסור להגבי' קולו בתפלתו\" און „שכור אסור להתפלל\"50:\nאין גדר התפלה זיינען דאָ צוויי פרטים: די כוונת הלב שבתפלה און דער דבור שבתפלה.\nדער עיקר ענין התפלה איז, כידוע, די כוונת הלב שבתפלה. מיט דעם איז תפלה אַנדערש פון כמה מצות שבדבור, וואָס ביי תפלה איז כוונת הלב (ניט בלויז אַן ענין פון כוונת המצוה, ווי ביי אַנדערע מצות שבדבור, נאָר) אַ חלק פון קיום המצוה עצמה: די כוונת התפלה מאַכט אויף די חפצא של מצות תפלה, אויך דעם דבור של התפלה (ווי גערעדט אַמאָל בארוכה<sup data-n=\"51\">51</sup>.\nוי\"ל אַז דאָס איז דער טעם וואָס מען געפינט ניט הדגשת הכרח הכוונה ביי ברכה52, משא\"כ בתפלה איז דער עיקר די כוונה והרגש הלב —\nויומתק זה ע\"פ הנ\"ל: ברכה איז ענינה (כנ\"ל ס\"ג), צו פועל זיין אַז די השפעה זאָל נמשך ווערן ממקורה און אַראָפּקומען לידי גילוי למטה, און דעריבער",[["45","45","הל' נזירות פ\"ג הט\"ז."],["46","46","רד\"ק ש\"א שם, יא. ועוד."],["47","47","נזיר כח, ב (במשנה) — הובא ברד\"ק שם. ע\"ש."],["48","48","לקו\"ש חי\"ח ע' 66 ואילך ובהערות שם."],["49","49","עיי\"ש (ע' 68 ואילך) בארוכה ובהדוגמאות לגדר זה."],["50","50","ברכות לא, סע\"א."],["51","51","לקו\"ש חכ\"ב ע' 117 ואילך."],["52","52","ומה שבברכת כהנים (נשא ו, כג) פרש\"י „אמור מלא לא תברכם בחפזון ובבהלות אלא בכונה ובלב שלם\", הרי א) מזה גופא שצריכים לימוד מיוחד ע\"ז (אמור מלא) מוכח שעיקר ענין הברכה הוא האמירה והדיבור [וראה פרש\"י שם לפנ\"ז (מספרי) „אמור להם, שיהיו כולם שומעים\", ובסוטה (לח, סע\"א) „בקול רם\"]. ב) ברכת כהנים שאני שיש בה גם המעלה דתפלה כמבואר בד\"ה כה תברכו שם. ובכ\"מ. וראה לקו\"ש ח\"י ע' 38 ואילך. וש\"נ."]]],[1300291202,"איז דער עיקר דערביי דער דבור וואָס ענינו איז גילוי המחשבה.\nמשא\"כ ביי תפלה, אעפ\"י אַז תכליתה איז עס זאָל אויפגעטאָן ווערן אַ שינוי בגשמיות, „שיתרפא החולה וירד הגשם משמים לארץ ויולידה ויצמיחה\"53, איז דאָס אָבער אַ תוצאה דערפון וואָס מען פועל'ט אַ רצון חדש כביכול ביי הקב\"ה, און דאָס קומט בעיקר דורך כוונת הלב פון מתפלל54, „שיפנה את לבו מכל המחשבות ויראה עצמו כאילו הוא עומד לפני השכינה\"55.\nבשעת אַ איד איז מפנה לבו פון אַלע זיינע מחשבות ורצונות און איז זיך מבטל כעבדא קמי' מארי'56 צום אויבערשטן איז דאָס פועל, אויך למעלה כביכול (כמים הפנים לפנים<sup data-n=\"57\">57</sup> אַז עס זאָל זיין אַ רצון חדש, וועלכער איז ניט לויט די הגבלות פון סדר העולם, ביז אפילו ניט לויט דעם סדר והגבלה פון תורה, עשיית רצון חדש58.\nאון דער ענין איז אויך געווען אַ דבר עיקרי בתפלת חנה: די הדגשה אין די פסוקים איז ניט אַזוי די אריכות אין דעם דבור התפלה, נאָר דווקא אויף כוונת הלב — „והיא59 מרת נפש ותתפלל על ה' ובכה תבכה\"60, און ווי זי האָט געזאָגט צו עלי61 „ואשפוך את נפשי לפני ה'\".\nאון דעריבער איז תוכן פון כוונת הלב דער ערשטער ענין פון די „הלכתא גברוותא\" וואָס מען לערנט אָפּ פון תפלת חנה. און דאָס איז אויך דער תוכן62 פון די אַנדערע63 „הלכתא\"64.\nז. ע\"פ כהנ\"ל איז אויך מובן די שייכות בתוכן, פון דער הפטרה צו ראש השנה65 (ובפרט לפי הידוע66 אַז תפלת",[["53","53","ל' אדה\"ז בתניא — קו\"א (קנה, א). וראה לקו\"ת בלק ע, ד ואילך."],["54","54","דבפשטות זה ש„צריך שיכוין לבו\" שלמדין מחנה „וחנה היא מדברת על לבה\" (ש\"א שם, יג) היא לא (רק) כוונת פירוש המלות כ\"א (בעיקר) גדר ד„מתחנן ומתפלל (לפני הקב\"ה)\" (לשון הרמב\"ם הל' תפלה פ\"א ה\"ב — ראה בלקו\"ש חכ\"ב שם). וראה תר\"י ברכות שם (במשנה ד\"ה כדי שיכוונו)."],["55","55","רמב\"ם שם פ\"ד הט\"ז. וראה שו\"ע אדה\"ז או\"ח ר\"ס צח."],["56","56","שבת יוד, א. שו\"ע אדה\"ז או\"ח סו\"ס צה. ועיין ברכות לג, רע\"א. שו\"ע אדה\"ז סי' קד ס\"ב."],["57","57","משלי כז, יט. וראה תניא פמ\"ט (סט, א) עד\"ז לאידך."],["58","58","כמאמר המשנה: עשה רצונו כרצונך כדי שיעשה רצונך כרצונו (אבות פ\"ב מ\"ד)."],["59","59","ש\"א שם, י."],["60","60","להעיר משערי תשובה לאדהאמ\"צ (ד\"ה איתא בר\"מ פ\"א — ט, ב) „כתפלת חנה שהיתה מרת נפש שאין זה רק בקשת ר\"ר העליונים כידוע דצלותא נקרא רחמים (וזהו עיקר מצות התפלה בכל עת צרה דוקא)\"."],["61","61","ש\"א שם, טו."],["62","62","כי גם זה שלמדין שצריך שיחתוך בשפתיו, הרי זה פרט והקדמה לדין שלאח\"ז שאסור להגבי' קולו בתפלתו, וכפשטות הכתוב (ש\"א שם, יג) „מדברת על לבה רק שפתי' נעות וקולה לא ישמע\"."],["63","63","ראה לגבי שיכור — רמב\"ם שם הי\"ז (מעירובין סד, א — כנסמן בנ\"כ שם). שו\"ע אדה\"ז סי' קפה ס\"ה."],["64","64","וע\"פ כל הנ\"ל יש לבאר גם השייכות לשם צבאות שאמרה חנה כאן — כבברכות שם (בהמשך הסוגיא — לא, ב): מיום שברא הקב\"ה את עולמו לא הי' אדם שקראו להקב\"ה צבאות עד שבאתה חנה וקראתו צבאות כו' — ע\"פ המבואר בתו\"א (ס, א ואילך) תו\"ח (שמות קלז, א ואילך) ועוד, ששם זה מורה על ענין התלבשות אוא\"ס בכלים דבי\"ע להיות מתייחד עמהם ג\"כ כמו שמתייחד באצילות, וענין זה הוא לא ע\"פ סדר ומאמר קו המדה, והכח להמשכה זו המשיכו הנביאים מבחי' העיגול והסוכ\"ע אשר שם כחשיכה כאורה כו' שהוא דוקא יכול להשפיל את עצמו למטה מטה גם בבי\"ע. עיי\"ש בארוכה."],["65","65","ראה בארוכה לקו\"ש חי\"ט ע' 291 ואילך."],["66","66","של\"ה במס' ר\"ה שלו (ריד, א בהגהה) — ע\"פ ר\"ה יא, א: בר\"ה נפקדה . . חנה. וראה הגהות חת\"ס או\"ח סתקפ\"א (למג\"א סקט\"ז): לפי המפורסם דתפלת חנה הי' בר\"ה כו'. וכ\"ה בפני יהושע כתובות"]]],[1300291203,"חנה איז געווען בר\"ה), וואָרום דעמאָלט איז דער זמן וואָס מען טוט אויף דעם רצון חדש ביי דעם אויבערשטן (ניט נאָר בשייכות צו אַן ענין פרטי אין דער בריאה, נאָר) אויף דער כללות הבריאה.\nדער ביאור אין דעם:\nדער עיקר עבודה פון ר\"ה איז67 צו פועל זיין דעם „תמליכוני עליכם\"68; יעדן יאָר דאַרף מען פון דאָס־ניי מכתיר זיין דעם אויבערשטן אַלס מלך ישראל (ועי\"ז — מלך העולם).\nאון דאָס קומט דורכדעם וואָס מ'איז מעורר ביי דעם אויבערשטן דעם רצון צו וועלן זיין אַ מלך. ובדוגמא ווי דאָס איז ביי אַ מלך בשר ודם, וואָס אַן אמת'ער מלך איז דאָך „משכמו ומעלה גבוה מכל העם\"69, והיינו אַז דער ענין המלוכה, צו ווערן אַ מלך און אָנפירן מיט'ן עם, איז פאַר אים אַ ירידה (וויבאַלד אַז ער מצד עצמו איז גבוה, מרומם ומובדל פונעם עם), און דעריבער דאַרף מען ביי אים מעורר זיין אַ רצון למלוכה.\nאון די התעוררות הרצון למלוכה ווערט אויפגעטאָן דורך דעם ביטול וואָס דער עם ווייזט אַרויס צום מלך, וואָס דאַן איז דער ענין ההכתרה70.\nועד\"ז — און עאכו\"כ — איז עס אין נמשל, אַז דער אויבערשטער מצ\"ע איז לגמרי העכער פון צו זיין אַ מלך, וואָרום ער איז אינגאַנצן מובדל ומרומם פונעם גאַנצן ענין הבריאה. און דורך דער עבודה פון ר\"ה, וואָס אידן זיינען מגלה זייער קבלת עול מלכות שמים און פולשטענדיקן ביטול צום אויבערשטן, איז מען מעורר ביים אויבערשטן דעם רצון אויף צו זיין אַ מלך.\nאון דערפאַר איז „מצות היום בשופר\"71, ווייל דוקא תקיעת שופר אַנטהאַלט אין זיך דעם תוכן וואָס עס טוט אויף דער ענין פון „תמליכוני\", ווי די גמרא זאָגט68 „אמרו לפני בר\"ה מלכיות . . כדי שתמליכוני עליכם זכרונות כו' ובמה בשופר\":\nדער קול שופר איז אַ קול פשוט, וואָס קומט פון הבל הלב, וואָס בעבודת ה' איז עס72 די צעקה פשוטה פון אַן אידן פון פנימיות הלב, כמ\"ש73 „צעק לבם אל אד'\" — די צעקה פנימית פון אידן צום אויבערשטן, און דערפאַר איז דאָס מעורר למעלה אַ רצון פנימי למלוכה, אַז דער אויבערשטער זאָל אָננעמען די הכתרה פון די אידן און זיין מלך ישראל ועי\"ז דער מלך העולם,\nביז עס ווערט בגלוי „והי'74 ה' למלך על כל הארץ ביום ההוא יהי' ה' אחד ושמו אחד\".\n(משיחת ו' תשרי תש\"ל)",[["","","סה, א (לתוד\"ה אחרי). וראה הר המורי' לרמב\"ם הל' ביהב\"ח בתחלתו."],["67","67","בכל הבא לקמן — ראה בארוכה דרושי ר\"ה בלקו\"ת וכו'."],["68","68","ר\"ה טז, סע\"א. לד, ב."],["69","69","ע\"פ ש\"א י, כג (הנאמר בשאול)."],["70","70","ראה גם מכתב ח\"י אלול תשמ\"ה (נדפס לקמן בהוספות ע' 515)."],["71","71","ר\"ה כז, א."],["72","72","ראה לקו\"ת שם נד, ג. נח, ד. ובכ\"מ."],["73","73","איכה ב, יח."],["74","74","זכרי' יד, ט (מפסוקי מלכיות)."]]],[1300291204,"<h3>וילך</h3>\nא. אויפן פסוק1 „בן מאה ועשרים שנה אנכי היום לא אוכל עוד לצאת ולבא\" זאָגן חז\"ל2, אַז דאָס מיינט (ניט „לצאת ולבא ממש\" ווייל „תשש כחו\"3, נאָר) — „לצאת ולבא בדברי תורה. מלמד שנסתתמו ממנו שערי חכמה\".\nדער מאמר ווערט געבראַכט אין פירוש רש\"י על התורה4, נאָר — בשינוי לשון: אַנשטאָט „שערי חכמה\", איז דער לשון אין רש\"י — „מסורות ומעינות החכמה\".\nאין „עין יעקב\"2 (ועד\"ז בכמה ראשונים<sup data-n=\"5\">5</sup> ווערט געבראַכט די גירסא (אין גמרא) „מעינות\" אַנשטאָט „שערי\"; און אין תנחומא (פ' ואתחנן<sup data-n=\"6\">6</sup> איז די גירסא „מסורת חכמה\".\nאָבער, נוסף לזה וואָס מען דאַרף האָבן אַ ביאור פאַרוואָס ברענגט ניט רש\"י די גירסא רווחת (שערי חכמה)7 — איז עוד ועיקר: מען געפינט ניט אין ערגעץ (במדרשי חז\"ל שלפנינו) אַז עס זאָלן זיך ברענגען ביידע לשונות („מסורות ומעינות\", אויך ניט „מסורות ושערי\") — און רש\"י איז מצרף ביידע גירסאות צוזאַמען!8\nאויך איז ניט מובן: ווי גערעדט כמה פעמים9, איז ניט ענינו פון פרש\"י על התורה צו מעתיק זיין דרשות חז\"ל בדיוק לשונם — ולפ\"ז בעניננו: פאַרוואָס ברענגט רש\"י דעם לשון „מסורות ומעינות החכמה\" — און זאָגט ניט אַ לשון הרגיל (און וואָס רש\"י עצמו הויבט דערמיט אָן פירושו — „לצאת ולבא",[["1","1","פרשתנו לא, ב."],["2","2","סוטה יג, ב."],["3","3","לשון רש\"י עה\"פ. וראה ראב\"ע ורמב\"ן כאן."],["4","4","פרשתנו עה\"פ (בפי' הב' (בד\"ה אנכי היום). ראה בארוכה מפרשי רש\"י. ונת' בהתוועדות)."],["5","5","רמב\"ן עה\"ת כאן. רבינו בחיי. מושב זקנים. ועוד."],["6","6","בסופה (בשם „ר' שמואל בר נחמני א\"ר יונתן\" — בעל המאמר בסוטה שם). — גירסא זו („מסורת חכמה\") הובאה ג\"כ בשטמ\"ק סוטה שם. וראה מס' סוטה עם שינויי נוסחאות (ירושלים, תשל\"ז)."],["7","7","ובלאה\"כ לא נקט רש\"י גירסת התנחומא, דשם הלשון „נטלו מסורת כו'\", ורש\"י נקט כגירסת הש\"ס „נסתמו ממנו\" (ראה הערה 10). וטעמו של רש\"י — יש לומר, כי בזה מתרץ תמי' פשוטה: איך יתכן שהקב\"ה גרם שמשה רבינו ישכח (חסרון) תורתו*?! והתי' — שרק „נסתמו ממנו\", היינו כמו מעין שנסתם, שאינו נובע ממקומו לחוץ; וכן בעניננו, שלא ניטל ממשה הניתן לו כבר — ראה עיון יעקב לע\"י סוטה שם. ובענף יוסף שם — כ\"א כמו „בסתימת המעיין אין שום חסרון בגוף המעיין רק שיש דבר המונע . . מלצאת חוצה . . קודם מותו לא הי' בכחו לצמצם . . להוציאה לחוץ\". ע\"ש. וראה גם ש\"ך עה\"ת כאן: אמר לצאת כו' [משא\"כ לגירסת התנחומא ש„נטלו מסורת כו'\". וראה המשך הענין שם „ולא הי' יודע משה מה הי' יהושע דורש\"]. וראה לקמן הערה 30."],["8","8","בדפוס ראשון ושני דפרש\"י, וכן בכמה כת\"י רש\"י שתח\"י, איתא רק „מסורות החכמה\", וברוב כת\"י רש\"י שתח\"י איתא רק „מעינות החכמה\". אבל בדפוסי רש\"י הנפוצים (וכן בהוצאת בערלינער, גם במהד\"ק שלו) הוא כבפנים."],["9","9","ראה ס' כללי רש\"י (כפר חב\"ד, תש\"מ) פ\"ח ס\"ב (בהוצאת תנש\"א — פ\"ט ס\"ה). וש\"נ. *) ובפרט בנדו\"ד „שנמסרה לו תורה במתנה ככלה לחתן\" (פרש\"י תשא לא, יח). ולהעיר ממחז\"ל (תענית כה, א) דמשמיא מיהב יהבי מישקל לא שקלי (בתר דיהבי. רש\"י)."]]],[1300291205,"בדברי תורה\") — „שנסתמו10 ממנו דברי תורה\"11?\nב. ויש לומר, אַז רש\"י באַוואָרנט דערמיט אַ שאלה פשוטה (בלשון העולם: אַ „קלאָץ קשיא\"), שלא מצאתי לע\"ע אַז מען זאָל זיך שטעלן אויף דעם:\nווי זאָגט מען „לא אוכל עוד לצאת ולבא בדברי תורה\" — בשעת אַז באַלד דערנאָך האָט משה רבינו איבערגעגעבן אידן אַ ריבוי עניני תורה — די דריי סדרות וילך האזינו און וזאת הברכה?!\n[און נאָר בנוגע די לעצטע אַכט פסוקים פון תורה12 — וואָס הויבן זיך אָן מיט „וימת שם משה\" — געפינט מען צוויי דיעות13 (ווי אַראָפגעבראַכט אויך אין פרש\"י<sup data-n=\"14\">14</sup> צי יהושע האָט זיי געשריבן, אָדער „משה כותב15 בדמע\";\nאָבער בנוגע פ' וילך, האזינו און וזאת הברכה (ביז די לעצטע אַכט פסוקים) איז לית מאן דפליג אַז משה האָט זיי (געזאָגט און) געשריבן].\nאון מען קען ניט ענטפערן אַז מיט „דברי תורה\" ווערט געמיינט בלויז עניני הלכה16 — ווייל (נוסף לזה אַז עס איז אַ דוחק הכי גדול צו זאָגן אַז דברים פון תורה שבכתב גייען ניט אַריין אין כלל פון „דברי תורה\" — איז עוד ועיקר:) אין אָט די פרשיות זיינען פאַראַן אויך הלכות (מצות הקהל17, כתיבת ס\"ת18 ועוד<sup data-n=\"19\">19</sup>.\nנאָך מער: יעדער וואָרט פון תורה שבכתב איז געגעבן געוואָרן צו משה'ן מיט זיין פירוש20 אין תורה שבע\"פ21 (וואָרום דוקא דורך דעם קען מען וויסן קלאָר די כוונה פון תורה שבכתב22, כמובן בפשטות); און וויבאַלד אַז אויך די דריי סדרות (וילך, האזינו וברכה) זיינען איבערגעגעבן געוואָרן צו די אידן דורך משה רבינו, האָט ער דאָך זיי געוויס איבערגעגעבן אַלץ וואָס איז מוכרח להבנת פרשיות אלו — ד. ה. אויך דעם פירוש פון די פרשיות שבתורה שבעל פה.\n— איז ווי זאָגט מען „לא אוכל עוד לצאת ולבא בדברי תורה\"?!\nדעריבער איז רש\"י מוסיף „שנסתמו ממנו מסורות ומעינות החכמה\" — בנוגע די צוויי ענינים („מסורות\" און „מעינות החכמה\") איז שייך צו זאָגן אַז זיי זיינען ניט נכלל געוואָרן אין די „דברי תורה\" וואָס משה רבינו האָט געלערנט מיט די אידן אין די דריי סדרות. כדלקמן.\nג. דער טייטש פון וואָרט „מסורות\" איז — די ענינים וועלכע זיינען נמסר",[["10","10","בכמה דפוסי (וכת\"י) רש\"י „שנסתתמו\" (כבסוטה שם לפנינו). וראה שינויי נוסחאות במס' סוטה הנ\"ל הערה 6 — שתי הגירסאות בש\"ס."],["11","11","וראה מדרש לקח טוב כאן „לצאת ולבא בתורה\" (ותו לא)."],["12","12","ברכה לד, ה ואילך."],["13","13","ב\"ב טו, א (וש\"נ). ועד\"ז בספרי ברכה שם. — ולשיטת הראב\"ע גם מ„ויעל משה גו'\" (שם, א ואילך) כתב יהושע."],["14","14","ברכה שם, ה."],["15","15","ואינו מבאר בנוגע לאמירתן. ולהעיר ממפרשי הע\"י (מהרש\"א. הריטב\"א. עיון יעקב) ב\"ב שם."],["16","16","להעיר מבעה\"ט כאן: בששה סדרי משנה."],["17","17","פרשתנו לא, י ואילך (ומפורש „ויצו משה אותם גו'\")."],["18","18","שם, יט."],["19","19","ראה לדוגמא (גם בפרש\"י עה\"ת) האזינו לב, ג. ועוד."],["20","20","ראה רמב\"ם בהקדמתו לפיהמ\"ש וס' היד — בנוגע למצות התורה. וראה הל' ת\"ת לאדה\"ז פ\"א ס\"ד."],["21","21","כפרש\"י בחוקותי (כו, מו)."],["22","22","ראה בארוכה אגה\"ק סו\"ס כט (קנ, ב ואילך). וראה הקדמת הרמב\"ם לפיהמ\"ש שם."]]],[1300291206,"געוואָרן צו משה'ן מסיני בעל פה23, וי\"ל שבמיוחד די וועלכע האָבן ניט אפילו אַ רמז אין תורה שבכתב24\n[און ווי די גמרא זאָגט25 „תורה רוב בכתב ומיעוט על פה\", און ווי רש\"י איז דאָס מפרש: רוב בכתב, רוב התורה תלוי' במדרש כו' מדות שהתורה נדרשת בהן. ומיעוטה על פה, שאין רמז ללמוד לה בתורה אלא למשה נאמר על פה];\n„מעינות החכמה\" מיינט (ניט די גופי הלכות פון תורה שבע\"פ, נאָר) — פלפולה של תורה (וואָס איז בדוגמא צו אַ „מעין\", בלשון המשנה26 „מעין המתגבר\") — וואָס צו פלפולא דאורייתא איז ניטאָ קיין גבול (בלשון הכתוב27 „ארוכה מארץ מדה ורחבה מני ים\"), וכנראה בחוש:\nאון דערפון איז פאַרשטאַנדיק (ובפשטות), אַז אין די „דברי תורה\" וואָס משה רבינו האָט געלערנט מיט אידן (אפילו אין פירושה פון תורה שבע\"פ) זיינען נכלל געוואָרן בלויז די גופי הלכות ופירושים כו' פון תורה שבע\"פ, אָבער ניט פלפולא דאורייתא (וואָס האָט ניט קיין גבול).\n[ועאכו\"כ לויטן מאמר הגמרא28, אַז פלפולא דאורייתא „לא ניתנה . . אלא למשה ולזרעו\" נאָר „משה נהג בה טובת עין ונתנה לישראל\" — איז מובן, אַז אויך בלי פלפולא דאורייתא זיינען די „דברי תורה\" שקיבלו בנ\"י פון משה'ן אַ „דבר שלם\"29].\nועפ\"ז איז פאַרשטאַנדיק ווי אַזוי ס'איז קיין סתירה ניט, אַז אע\"פ וואָס „נסתמו ממנו מסורות ומעינות החכמה\", פונדעסטוועגן האָט משה רבינו איבערגעגעבן צו אידן די דריי סדרות בשלימותן — סיי די פרשיות עצמן (דתושב\"כ) און סיי פירושה (דתושבע\"פ) פירושה ממש — ווייל די „מסורות\" זיינען מלכתחילה ניט פאַרבונדן מיט די פרשיות (כתב) עצמן29*; און בנוגע די „מעינות\"30 (פלפולא דאורייתא) איז",[["23","23","ע\"ד ל' רש\"י (וישלח לד, ל) „מסורת כו' ביד הכנענים\". ולהעיר מ„יש אם למסורת\" (פסחים פו, ריש ע\"ב. וש\"נ). בבאר מים חיים (לאחי המהר\"ל) על פרש\"י כאן, ד„מסורות\" היינו ש„לא הי' לו עוד כח לטרוח ולמסור ליהושע מה שקיבל מסיני\". ומשמע שמפרש דמסורות היינו הכח למסור כו' [ובעץ יוסף לתנחומא ואתחנן שם ד„מסורות החכמה פי' כללי החכמה שעל פיהם מוסר הרב לתלמידיו שיבינו . . מדרך קצרה\"]. אבל [נוסף לזה שלכאורה דוחק לומר שנעשה חסרון בכח חכמתו של משה — דאם לא תששו כחותיו הגשמיים, עאכו\"כ שלא תששו כחותיו הרוחניים — הנה] לכאורה פשטות הלשון „מסורות\" מורה על דברים הנמסרים בע\"פ. [ואולי תיבת „החכמה\" בפרש\"י לא קאי על „מסורות\" שלפני פניו רק על תיבת „ומעינות\"]."],["24","24","ע\"ד הלכה למשה מסיני ש(רובם) אין להם שום רמז במקרא (פיהמ\"ש שם ד\"ה וכאשר (קרוב לסופו). וראה אנציקלופדי' תלמודית ערך הלכה למשה מסיני בתחלתו. וש\"נ)."],["25","25","גיטין ס, ריש ע\"ב."],["26","26","אבות פ\"ב מ\"ט. שם פ\"ו, א. — וראה גם באר מים חיים על פרש\"י כאן. עיון יעקב לע\"י סוטה שם."],["27","27","איוב יא, ט. ועיין הל' ת\"ת לאדה\"ז פ\"א ס\"ה."],["28","28","נדרים לח, א. וראה רש\"י שם ד\"ה פלפולא."],["29","29","אף שע\"י הפלפול „יתחדשו ג\"כ חידושי הלכות לאין קץ\" (ל' אדה\"ז בהל' ת\"ת שם) — מ\"מ, אינו מוכרח (ואי אפשר) שמשה ילמד בפועל עם ישראל פלפולא דאורייתא לתכליתו (משא\"כ ההלכות והמדרשים שנתגלו לנו שיש להם קץ — הל' ת\"ת שם). ואכ\"מ. 29*) ראה שוה\"ג להערה הבאה."],["30","30","הטעם שרש\"י לא הסתפק ב„מסורות\" ומוסיף „ומעינות החכמה\" — יש לומר, ע\"פ המבואר לעיל (הערה 7) שרק „נסתמו ממנו\", אבל לא ניטל ממנו מה שניתן לו — ועפ\"ז י\"ל שנסתמו ממנו רק ה„מסורות\" השייכות לג' פרשיות אלו*, *) ולכאורה צ\"ל דגם המסורות דפרשיות אלו כבר ניתן למשה מסיני (ראה רש\"י ר\"פ בהר:"]]],[1300291207,"ניטאָ קיין הכרח אַז משה זאָל מוזן לערנען די ענינים מיט די בני ישראל, כנ\"ל.\n[און דערפאַר שרייבט ניט רש\"י בפשוטו של מקרא דעם לשון „שערי חכמה\", וואָס האָט ניט קיין שייכות צו חילוקים ותוכן הנ\"ל].\nועפ\"ז יש לבאר פאַרוואָס רש\"י איז מדייק צו ברענגען אויך דעם וואָרט „(מעינות) החכמה\" — און זאָגט ניט „(מעינות) התורה\" — להדגיש, אַז די „מעינות\" זיינען ניט מוכרח פאַרן ענין פון תורה והוראה (וואָרום דעמאָלט וואָלט עס משה געמוזט לערנען מיט די אידן)29, נאָר ס'איז אַן ענין פון (תוספת) חכמה שבתורה31.\nד. לכאורה איז אָבער נאָך ניט גלאַטיק:\nדער ענין פון „נסתמו ממנו מסורות ומעינות החכמה\" קומט דאָך אַלס טעם אויף „לא אוכל עוד לצאת ולבא בדברי תורה\", וואָס מיינט (ניט דעם לימוד לעצמו, נאָר) דער לימוד עם בני ישראל.\nאיז ניט מובן: בשלמא בנוגע צו „מסורות\" איז מובן, אַז אויב נסתמו ביי משה'ן די „מסורות\" פון תורה קען ער ניט לצאת ולבוא, זיין דער וועלכער גיט איבער תורה צו אידן (ווייל אידן מוזן וויסן אויך די „מסורות\"); אָבער בנוגע צו „מעינות החכמה\", וויבאַלד אַז זייער לימוד איז ניט מוכרח פאַר די בנ\"י (כנ\"ל) — ווי פאַסט צו זאָגן אַז מצד דעם וואָס „נסתמו ממנו . . מעינות החכמה\" איז „לא אוכל עוד לצאת ולבא — צו אידן — בדברי תורה\"?\n[און מען קען ניט זאָגן אַז דער „לא אוכל עוד לצאת ולבא\" איז נאָר מצד דעם וואָס „נסתמו ממנו מסורות\" — ווייל לפ\"ז, פאַרוואָס האָט דער אויבערשטער געמאַכט אַז עס זאָלן נסתם ווערן פון משה'ן אויך די „מעינות החכמה\"? וגם: צוליב וואָס דאַרף עס רש\"י ברענגען?]32.\nויש לומר דעם ביאור אין דעם: פון דעם גופא וואָס עס איז געוואָרן נסתמו בחלק מתורתו — אע\"פ אַז עס קען זיין אַז עס וואָלט ניט משנה געווען זיין השפעה צו אידן — איז אַ סימן, אַז עס האָט זיך געענדיקט זיין לצאת ולבוא צו בנ\"י, זיין נשיאות, און ס'איז געקומען די צייט פאַר יהושע צו ווערן דער מנהיג ישראל33.\nובעומק יותר:\nעס איז ידוע וואָס חז\"ל זאָגן34 — אַראָפגעבראַכט אין פירש\"י עה\"ת35 — אַז „פני משה כחמה36 פני יהושע כלבנה\". איינער פון די חילוקים צווישן אור החמה און אור הלבנה איז, אַז דער",[["","","שהם מתי מספר לפ\"ע, וקשה לומר לכאורה שמשו\"ז „לא אוכל כו' בדברי תורה\"! שמשמע שהי' כאן חסרון כללי. אבל לאידך גם „מעינות חכמה\" לחוד לא מספיק, שהרי אי\"ז נוגע להלימוד עם בנ\"י, כדלקמן בפנים."],["31","31","להעיר מיגדיל תורה ויאדיר, דרוש וקבל שכר, כי אין נפק\"מ למעשה (חולין סו, ב. סוטה מד, א. וש\"נ). כללותיהן ודקדוקיהן. רש\"י בחוקותי שם) (ויתירה מזו — שכבר מסרם ליהושע כו'. דאל\"כ — מי מסרם לבנ\"י?)."],["32","32","ואולי זהו טעם הגירסא בפרש\"י שנאמר רק „מסורות\" (ולא „מעינות\") — ראה הערה 8."],["33","33","ראה גם ש\"ך עה\"ת כאן, דמזה „שכל יום ויום הי' מוסיף והולך ואותו יום . . לא הוסיף . . ידע כי נטלה ממנו הרשות\"."],["34","34","ב\"ב עה, סע\"א. ספרי פינחס כז, כ."],["35","35","פינחס שם."],["36","36","כ\"ה בפרש\"י (לא „כפני חמה . . כפני לבנה\", כבב\"ב וספרי). וראה לקו\"ש ח\"ט ע' 63 בשוה\"ג."]]],[1300291208,"אור הלבנה שטייט שטענדיק אין אַ מצב פון שינויים, עליות וירידות; משא\"כ אין אור החמה איז ניטאָ קיין שינוי.\nאון דאָס איז איינער פון די טעמים פאַרוואָס משה ווערט צוגעגליכן צו חמה דוקא — ווייל מדתו של משה איז מדת האמת37, וואָס ענינה איז — בלתי שינוי38, אַזוי, אַז אין „אורו\" של משה איז ניט שייך קיין ענין של שינוי39.\nדעריבער, בשעת משה רבינו האָט דערפילט אַז „נסתמו ממנו . . מעינות החכמה\" — ס'איז געוואָרן אַ „סתימה\" (ושינוי) אין זיין „אור\" — איז דאָס גופא אַ באַווייז אַז עס איז אָנגערירט געוואָרן עצם ענינו של אורו — לצאת ולבוא של משה;\nאון דעריבער איז קיין נפק\"מ ניט אין וועלכן ענין ס'איז געוואָרן דער שינוי („נסתמו ממנו\") — אפילו אויב ס'איז אין אַן ענין וואָס רירט ניט אָן לכאורה זיין השפעה צו בנ\"י — איז דער עצם ענין השינוי שוין אַ הוכחה אַז ס'איז געקומען די צייט פון שינויים, די צייט פאַר „פני יהושע כלבנה\" (אַן אור פון שינויים).\nה. פון דעם ענין (ווי ס'איז ביי משה'ן) ווערט אויך אַ הוראה אין דער עבודה פון יעדער אידן\n[וואָרום אע\"פ אַז „מי הוא זה ואיזהו אשר ערב לבו לגשת להשיג אפילו חלק אחד מני אלף ממדרגת . . רעיא מהימנא (משה רבינו)\"40 — איז אָבער מצד דעם וואָס „כל נפש ונפש מבית ישראל יש בה מבחי' משה רבינו ע\"ה\"41, קען יעדער איד דערגרייכן „אפס קצהו ושמץ מנהו\"40].\nויש לומר, אַז דאָס איז דער תוכן מאמר חז\"ל42 „כל השוכח דבר אחד ממשנתו מעלה עליו הכתוב כאילו מתחייב בנפשו\". דלכאורה, פאַרוואָס זאָל קומען אַזאַ עונש חמור בלויז צוליב דעם וואָס שכח „דבר אחד ממשנתו\" (און יתכן אַז ער געדענקט כל התורה כולה חוץ פון דעם „דבר אחד\")?!\nאיז איינער פון די ביאורים אין דעם: ביי אַ אידן דאַרפן דברי תורה נחקק ווערן אין זיין עצם מציאות, ביז אין אַן אופן אַז יעדער וואָרט פון תורה רירט אָן זיין עצם מציאות. און דעריבער, די עצם פאַסירונג פון „שוכח דבר אחד ממשנתו\" — איזו כמות וואָס ער האָט פאַרגעסן — דאַרף פועל'ן אַ שבירה אין זיין עצם מציאות, „כאילו43 מתחייב בנפשו\".\nועד\"ז איז בנוגע צו זמן — אַז יעדער רגע פון זיין לעבן דאַרף זיין פאַרבונדן מיט תורה. און דעריבער, ווען אַ איד איז ח\"ו מבטל תורה, אפילו איין רגע ווען",[["37","37","תנחומא שמות כח. שמו\"ר שם (פ\"ה, י). ובכ\"מ. וראה ב\"ב עד, א. ועוד."],["38","38","בלשון הכתוב (משלי יב, יט) שפת אמת תכון לעד. וראה תניא ספי\"ג. אגה\"ק ו. לקו\"ת מטות (פג, סע\"ג ואילך). מסעי (צג, ב-ג). וש\"נ. ובכ\"מ."],["39","39","ראה בארוכה אוה\"ת ואתחנן (ע' צג ואילך) ועוד (ושם, שמטעם זה אם הי' משה מכניס את בנ\"י לארץ הי' להם קיום נצחי בארץ. ע\"ש). וראה גם לקו\"ש חכ\"ו ע' 5-6. [ולכאורה צע\"ק מהעליות וירידות כו' שמצינו אצל משה ובפרט מעלייתו בכל שבת שלכן בכל שבת „ישמח משה במתנת חלקו\" (סי' האריז\"ל במקומו. וראה לקו\"ש ח\"ז ע' 245. וש\"נ). ולהעיר מאו\"ת להה\"מ ד\"ה ועינינו (פד, סע\"ד) שאצל משה היו שתי המעלות ד„שמש וירח\". ע\"ש. ואכ\"מ]."],["40","40","ל' התניא פמ\"ד (סג, א)."],["41","41","תניא רפמ\"ב. וראה גם פמ\"ד שם."],["42","42","אבות פ\"ג מ\"ח. הובא להלכה בהל' ת\"ת לאדה\"ז (פ\"ב ס\"ד ואילך)."],["43","43","ראה הל' ת\"ת שם ס\"ה."]]],[1300291209,"„אפשר (לו) לעסוק בתורה (איז) . . הכרת תכרת\"44 — עס רירט אָן זיין עצם מציאות. ווייל דאָ איז ניט פועל די כמות הזמן וואָס ער האָט פאַרפעלט צו לערנען, נאָר די עצם זאַך אַז עס איז אַדורך אַ רגע ווען ער איז ניט געווען פאַרבונדן מיט תורה.\nועד\"ז איז בנוגע צו אַלע ענינים פון אידישקייט: ביי אַ אידן דאַרף דער ענין פון עבודת השם זיין נחקק אין זיין מציאות, אַזוי אַז דער קלענסטער ענין פון עבודת השם — אפילו אַ דקדוק קל של ד\"ס אָדער אפילו אַ מנהג ישראל — דאַרף אים זיין נוגע בנפש, ביז אַז אויב ער פאַרפעלט ח\"ו אפילו „דבר אחד\" (און אַ דבר הכי קל) פועל'ט עס אַ שבירה בכל מהותו.\nאון דאָס גופא ברענגט אים צו מוסיף זיין אין עבודת השם, און אין אַן אופן אַז ער פילט ווי יעדער ענין טוב וואָס ער טוט איז מוסיף אין זיין עצם חיות, דביקות אין מחי' חיים45, מקור החיים — „ואתם46 הדבקים בה' אלקיכם חיים כולכם היום\".\n(משיחת ש\"פ וילך תשכ\"ו)",[["44","44","סנהדרין צט, א. הובא בטושו\"ע יו\"ד סו\"ס רמו (סכ\"ה). הל' ת\"ת לאדה\"ז פ\"ג ס\"ו (אלא שבטושו\"ע והל' ת\"ת שם הובאה רק התחלת הכתוב (הענין) ד„דבר ה' בזה\"). תניא פ\"א."],["45","45","יומא עא, א."],["46","46","ואתחנן ד, ד."]]],[1300291210,"<h3>האזינו</h3>\nא. שוין גערעדט פיל מאָל, אַז ענינו של רש\"י בפירושו על התורה איז (ווי רש\"י אַליין גיט אַרויס דעם כלל<sup data-n=\"1\">1</sup> „אני לא באתי אלא לפשוטו של מקרא“, און אפילו אין די ערטער וואו בהשקפה ראשונה זעט אויס אַז רש\"י ברענגט סתם אַראָפּ אַ דרש (של חז\"ל), אָבער כד דייקת זעט מען אַז דער געבראַכטער דרש (אויב ער זאָגט ניט אויף דעם „רבותינו דרשו“ וכיו\"ב) איז מוכרח בפשוטו של מקרא2.\nאון דאָס איז ניכר באופן בולט אין פירוש רש\"י בפרשתנו: רש\"י זאָגט אַ פירוש וואָס ווען מ'איז מעיין אין די מקורות פונעם פירוש זעט מען אַז דאָס זיינען דריי באַזונדערע דרשות חז\"ל — איינע אין גמרא, די צווייטע אין ספרי בפ' וילך און לבסוף אַ דרש וואָס שטייט אין ספרי על אתר — און במקורם האָבן די דרשות קיין שייכות ניט צווישן זיך, אָבער רש\"י בפירושו על התורה איז זיי אַלע דריי מצרף און כולל אין איין פירוש!\nובע\"כ צ\"ל אַז זיי זיינען נוגע צו פשט הכתוב, וואָס דאָס בינדט זיי צוזאַמען; ובמילא איז אויך דער סדר הבאתם בפירושו אַן ענין וואָס איז אין פשש\"מ — וכמשי\"ת להלן.\nב. אויפן פסוק3 „ויבא משה וידבר גו' הוא והושע בן נון“ איז רש\"י מעתיק פון פסוק די ווערטער „הוא והושע בן נון“ און איז מפרש: „שבת של דיוזגי היתה נטלה רשות מזה ונתנה לזה העמיד לו משה מתורגמן ליהושע שיהא דורש בחייו כדי שלא יאמרו ישראל בחיי רבך לא הי' לך להרים ראש ולמה קוראו כאן הושע לומר שלא זחה דעתו עליו שאע\"פ שנתנה לו גדולה השפיל עצמו כאשר מתחלתו“.\nהתחלת פירש\"י — „שבת של דיוזגי היתה נטלה רשות מזה ונתנה לזה“ שטייט אין גמרא סוטה4; דער המשך פרש\"י „העמיד לו משה מתורגמן ליהושע כו'“ שטייט אין ספרי פ' וילך5, און דער תוכן פון סיום פרש\"י „ולמה קוראו כאן הושע“ שטייט אין ספרי פרשתנו עה\"פ.\nפאַרוואָס איז דאָ רש\"י מצרף די דריי באַזונדערע מאמרים אין איין פירוש?\nאון נאָכמער: בשלמא די ערשטע צוויי ענינים אין פרש\"י — (א) „שבת של דיוזגי כו'“, (ב) „העמיד לו משה מתורגמן ליהושע כו'“ — האָבן אַ שייכות צווישן זיך בתוכנם — אויך אין צווייטן ענין איז מודגש ווי דער ענין ה„רשות“ איז אַריבער צו יהושע'ן; אָבער דער המשך הפירוש „ולמה קוראו כאן הושע כו'“ איז לכאורה אינגאַנצן אַ באַזונדער באַוואָרעניש, וואָס האָט קיין שייכות ניט צו דעם פריערדיקן ענין — און אעפ\"כ איז לא די וואָס רש\"י שטעלט עס אַריין",[["1","1","בראשית ג, ח. שם, כד (וראה שם, כב. ד, ח. ו, ג). ועוד."],["2","2","ראה ספר כללי רש\"י (קה\"ת, תש\"מ. תנש\"א) פ\"ה. ועוד."],["3","3","פרשתנו לב, מד."],["4","4","יג, ב. וראה גם ספרי כאן על התחלת הפסוק: בא . . והרשות נתנה ביד אחר."],["5","5","קרוב לתחלתו. ועד\"ז הוא בספרי פינחס כז, יח (ראה לקמן הערות 14, 25)."]]],[1300291211,"אין דעם זעלבן ד\"ה, נאָר ער פאַרבינדט עס נאָך מיט אַ וא\"ו המחבר־מוסיף — „ולמה קוראו כאן כו'“6 — כאילו ווי די שאלה שטעלט זיך דוקא לאחרי ובהמשך צום פריערדיקן פירוש „שבת של דיוזגי כו' העמיד לו משה מתורגמן כו'“!\nדי תמי' הנ\"ל — וואָס רש\"י איז מצרף דריי באַזונדערע ענינים צוזאַמען — איז נאָך גרעסער: ניט נאָר קומען זיי אין באַזונדערע ערטער און אפילו באַזונדערע ספרים ומדרשי חז\"ל — נאָר רש\"י אַליין ברענגט די (ערשטע צוויי) מאמרים במקום אחר אָבער יעדערן פאַר זיך! אין פ' פינחס אויפן פסוק7 „וסמכת את ידך עליו“ זאָגט רש\"י8 „תן לו מתורגמן שידרוש בחייך שלא יאמרו עליו לא הי' לו להרים ראש בימי משה“; און אין אנהויב פ' וילך, אויפן פסוק9 „לא אוכל עוד לצאת ולבא“, זאָגט רש\"י „איני רשאי שנטלה ממני הרשות וניתנה ליהושע“ — ד.ה. אַז אויך לויט רש\"י זיינען די צוויי ענינים (נטלה הרשות כו' און העמיד לו משה מתורגמן כו') ניט תלוי איינער אין דעם אַנדערן — וואָס איז מכריח רש\"י צו פאַרבינדן זיי צוזאַמען אין אונזער פסוק?\nג. אויך דאַרף מען פאַרשטיין: דער מאמר „שבת של דיוזגי היתה נטלה רשות מזה ונתנה לזה“ שטייט אין גמרא בנוגע אַן אַנדערן (פריערדיקן) פסוק, אין פ' וילך — „וילך משה ויהושע ויתיצבו באהל מועד“10. ולכאורה האָט רש\"י געדאַרפט זאָגן דעם גאַנצן פירוש אויף דעם פסוק אין פ' וילך, וואו עס שטייט בלשון זו (משה ויהושע) צום ערשטן מאָל11.\nמען קען ניט פאַרענטפערן, אַז היות ווי רש\"י האָט שוין געבראַכט דעם תוכן פון דעם פירוש אין אָנהויב פ' וילך (כנ\"ל), דאַרף שוין רש\"י ניט איבערחזר'ן דעם ענין נאָכאַמאָל אין המשך הפרשה אויפן פסוק „וילך משה ויהושע“ — ווייל אויב אַזוי, פאַרוואָס דאַרף עס רש\"י נאָכאַמאָל איבערחזר'ן בפרשתנו? און נאָך מער: דוקא בפרשתנו איז ער מוסיף דעם ענין פון „שבת של דיוזגי היתה“.\nועד\"ז איז ניט פאַרשטאַנדיק בנוגע דעם ענין פון „העמיד לו משה מתורגמן כו'“: וויבאַלד רש\"י האָט שוין געבראַכט דעם ענין אין פ' פינחס (אַז דער אויבערשטער האָט געהייסן משה'ן „תן לו מתורגמן כו'“ — וואָס זיכער האָט עס משה מקיים געווען) — פאַרוואָס דאַרף עס רש\"י נאָכאַמאָל איבערחזר'ן בפרשתנו?\nאפילו את\"ל אַז דאָס איז ע\"ד ווי מ'געפינט בכ\"מ בפרש\"י, אַז אַן ענין וואָס ער האָט מפרש געווען אין אַ פריערדיקן ספר חזר'ט ער אים איבער נאָכאַמאָל אין אַ ספר שלאח\"ז; וכש\"כ בנדו\"ד וואו עס רעדט זיך ניט וועגן דעם זעלבן ענין בדיוק — אין פ' פינחס רעדט זיך וועגן דעם ציווי הקב\"ה „תן לו מתורגמן“ און בפרשתנו — וועגן דער עשי' בפועל „העמיד לו משה מתורגמן“",[["6","6","ובא' מכת\"י רש\"י (שתח\"י) „למה“ (בלי וא\"ו). אלא שעפ\"ז קשה דהו\"ל לרש\"י לומר זה בפ\"ע בד\"ה הושע."],["7","7","שם."],["8","8","וראה גם ספרי שם (וראה לקמן סעיף ד והערה 14)."],["9","9","לא, ב."],["10","10","לא, יד."],["11","11","וראה חדא\"ג סוטה שם הראי' מהכתוב: דעד היום לא בא למחנה שכינה דהיינו אה\"מ רק משה בלבד אבל באותו יום שמת משה הי' גם יהושע נצב במחנה שכינה כו'."]]],[1300291212,"— איז אָבער ניט מובן, פאַרוואָס דאַרף ער איבערחזר'ן אַלע פרטים, אויך דעם טעם „כדי שלא יאמרו ישראל כו'“, וויבאַלד ער האָט דאָס שוין מפרש געווען בפ' פינחס [וואָרום כמדובר כמ\"פ, בשעת רש\"י חזר'ט איבער אַ פירוש וואָס ער האָט שוין געזאָגט פריער, זאָגט ער דאָס נאָר בקיצור12, און אין די ערטער וואו ער זאָגט עס איבער מיט אַלע פרטים, איז עס דערפאַר וואָס דאָס איז מוכרח מצד די כתובים על אתר].\nאויך דאַרף מען פאַרשטיין: דעם לשון „שבת של דיוזגי“ טייטשט אָפּ רש\"י (אין גמרא)13: „שני זוגות שני חברים היו בה תחלת היום למשה וסופו ליהושע“, וואָס בפשטות באַוואָרנט דאָ רש\"י, אַז „דיוזגי“ קען דאָ ניט געטייטשט ווערן כפשוטו, מלשון זוג — וואָרום די נשיאות פון משה איז געווען בתחלת היום און פון יהושע'ן בסופו (ס'איז ניט געווען אַן ענין פון אַ „זוג“, ביידע צוזאַמען) — נאָר עס מיינט „שני חברים היו“.\nאיז ניט מובן: וויבאַלד אַז רש\"י אין גמרא דאַרף דאָס באַוואָרענען (צו אַ בן חמש עשרה לגמרא), איז פשיטא אַז ער דאַרף עס טאָן אין לימוד ע\"פ פשט (צו אַ בן חמש למקרא)?\nד. וועט מען כ\"ז פאַרשטיין בהקדים לבאר דעם שינויי הלשונות אין פרש\"י, לגבי דעם לשון במקורו אין ספרי:\nא) אין ספרי שטייט „תן לו מתורגמן ליהושע והוא שואל ודורש ומורה בהוריות בחייך וכשתפטר לא יהו ישראל אומרים לו בחיי משה רבך לא היית מדבר ועכשיו אתה מדבר“14. משא\"כ בפרש\"י „שיהא דורש בחייו כו' בחיי רבך לא הי' לך להרים ראש“. וואָס איז דער דיוק הלשון „להרים ראש“?\nב) בנוגע דעם טעם וואָס ער ווערט דאָ אָנגערופן „הושע“ שטייט אין ספרי „ללמדך צדקתו של יהושע שומע אני שצפה15 דעתו עליו משנתנה15 ברשות ת\"ל הוא והושע בן נון הושע בצדקתו אע\"פ שנתמנה פרנס על הצבור הוא הושע בצדקו“16. רש\"י זאָגט אָבער אינגאַנצן אַנדערש — „שלא זחה דעתו עליו שאע\"פ שניתנה לו גדולה השפיל עצמו כאשר מתחלתו“.\nה. וי\"ל דעם ביאור בכל זה:\nדער טעם וואָס רש\"י זאָגט ניט דעם ענין פון „שבת של דיוזגי היתה“ גלייך אין אנהויב פ' וילך, איז — ווייל דאָרטן איז ניטאָ קיין הכרח צו זאָגן אַז דעמאָלט האָט זיך שוין אָנגעהויבן בפועל נשיאותו של יהושע. וואָרום אע\"פ אַז רש\"י זאָגט „איני רשאי שניטלה ממני הרשות וניתנה ליהושע“, איז דאָך רש\"י גלייך ממשיך (בהמשך פירושו) „וה' אמר אלי זהו פירוש לא אוכל עוד לצאת ולבא לפי שה' אמר אלי (לא תעבור את הירדן הזה<sup data-n=\"17\">17</sup>“. ד.ה. אַז נתינת הרשות צו יהושע איז נוגע (ניט בו ביום, נאָר)",[["12","12","ראה ס' כללי רש\"י פ\"ז."],["13","13","סוטה שם ד\"ה דיו זוגי."],["14","14","ועד\"ז הוא לשון הספרי פינחס שם אלא שמסיים „בחיי רבו לא הורה ועכשיו הוא מורה“. — ע\"ד הלשון בספרי וילך, איתא גם בספרי מטות לא, כא (גבי אלעזר הכהן)."],["15","15","כ\"ה בספרי לפנינו, ועוד. בילקוט עה\"פ: שתזוח (ע\"ד ל' רש\"י) . . משנתמנה. וראה עוד גי' בספרי הוצאת הורוויץ (נ. י. תשכ\"ט)."],["16","16","וממשיך שם בספרי, שעד\"ז הוא ביוסף ודוד."],["17","17","בדפוסים הנפוצים ליתא תיבות אלו בפרש\"י. בדפוס ראשון הובא בפרש\"י „לא תעבור וגו'“, ובדפוס שני הובא רק „וגו'“. ובכל אופן מובן הוא גם לפי הדפוסים שלפנינו — כי זהו ש„ה' אמר גו'“."]]],[1300291213,"צוליב דעם ענין ובמילא — דעם זמן פון „תעבור את הירדן הזה“. ובמילא איז ניטאָ קיין הכרח אַז בעת אמירת משה „לא אוכל עוד לצאת ולבא“ האָט זיך שוין אָנגעהויבן בפועל נשיאותו של יהושע.\nעד\"ז אין פסוק „וילך משה ויהושע ויתיצבו באהל מועד“ (ווייטער אין פ' וילך) — איז אין דעם (אַז יהושע איז אַריין צוזאַמען מיט משה'ן אין אהל מועד) ניטאָ קיין תוכן אַז יהושע איז שוין געווען אַ נשיא על ישראל בפועל — דאָס איז נאָך געווען אַ קיום האמירה פון דעם אויבערשטן „קרא את יהושע והתיצבו באהל מועד ואצונו“18.\nבשעת אָבער מ'קומט צו פרשתנו, וואו דער פסוק זאָגט „וידבר גו' הוא והושע בן נון“ ווערט דאָ די תמי': וואָס איז כוונת הכתוב אין מצרף זיין יהושע מיט משה'ן — ווי קומט דאָ אַריין יהושע (הושע)?! אין הכי נמי אַז יהושע „לא ימיש מתוך האהל“19, ער איז שטענדיק געווען מיט משה'ן — אָבער מאי טעמא וואָס די תורה זאָגט עס בפירוש דוקא דאָ?\nמוז מען זאָגן, אַז די ווערטער „הוא והושע בן נון“ באַציען זיך צו דעם „וידבר“ שבתחילת הכתוב, ד.ה. נאָך דעם ווי די תורה דערציילט אַז משה האָט געזאָגט די שירה, איז דער פסוק מוסיף20 „הוא והושע בן נון“ — די שירה האָט געזאָגט ניט בלויז משה אַליין נאָר אויך יהושע בן נון האָט עס געזאָגט „באזני העם“. נאָך מער: פון דעם וואָס די תורה זאָגט „הוא והושע בן נון“ — דלכאורה איז דער וואָרט „הוא“ איבעריק — איז מובן, אַז די תורה איז דערמיט מדגיש אַז משה ויהושע זיינען דאָ געווען ביידע גלייך (אין דעם ענין ואופן דיבור זה — בסגנון פון אַ נשיא — לבנ\"י).\nאון דעריבער זאָגט רש\"י דוקא דאָ אַז „שבת של דיוזגי היתה“, און רש\"י דאַרף ניט אויסטייטשן וואָס דאָס מיינט — כוונתו בזה איז פשוטו כמשמעו, אַז זיי זיינען געווען ביידע צוזאַמען אַ זוג פון נשיאים21.\n[און דערמיט מאַכט רש\"י קלאָר, אַז דאָס וואָס ער איז ממשיך לאח\"ז „נטלה רשות מזה ונתנה לזה“ מיינט ניט אַז דאַן האָט זיך שוין געענדיקט נשיאותו של משה, נאָר אַז ס'איז געווען אין אַן אופן פון „זוג“, ביידע צוזאַמען; נאָר וויבאַלד אַז משה איז שוין ניט געווען דער איינציקער נשיא (אין אַן אופן פון „דבר אחד לדור“<sup data-n=\"22\">22</sup> זאָגט מען אויף דעם „נטלה רשות מזה ונתנה לזה“23].",[["18","18","וראה שם לא, כג ובפרש\"י — הציווי ליהושע בפועל (הובא גם לפנ\"ז שם — בפרש\"י לא, ז)."],["19","19","תשא לג, יא. וראה פרש\"י משפטים כד, יג דמשמע דאוהל לאו דוקא."],["20","20","ע\"ד (ולא ממש): אז ישיר משה ובנ\"י גו' ויאמרו גו' אשירה (בשלח טו, א)."],["21","21","מש\"כ רש\"י „שבת של דיוזגי“ צ\"ע מנין לו לרש\"י בפשש\"מ שהי' שבת. ואף שכן מפורש בסוטה שם, אבל מכיון שרש\"י לא כתב ע\"ז „רבותינו דרשו“ (וכיו\"ב), מובן שכן מוכרח גם ע\"פ פשש\"מ. ועוד, לכאורה איך אפ\"ל שהי' יום השבת והרי (בפשש\"מ) ביום מותו גמר לכתוב הס\"ת (וכידועה השקו\"ט גם ע\"ד ההלכה עד\"ז — ראה לקו\"ש ח\"ו ע' 361 ובהנסמן שם. וראה גם לקו\"ש חכ\"ד ע' 208 הערה 15). ואולי הי' כתוב ברש\"י, „ש' של דיוזגי“, והכוונה „שררה“ או „שלטון“ של דיוזגי, של שניהם, והמעתיק שלא הבין כוונת רש\"י ב„ש'“ פיענחו כבש\"ס „שבת“."],["22","22","לשון רש\"י וילך לא, ז."],["23","23","ודוחק קצת — ובלאה\"כ דוחק הסתירה בניטלה וניתנה דפשוטה רשות אחת ודיוזוגי — שתי רשויות*. *) ואין לומר, שמכח בקשת משה „יפקוד ה'"]]],[1300291214,"ו. דערמיט ווערט אויך פאַרענטפערט בפשטות פאַרוואָס רש\"י איז דאָ מוסיף „העמיד לו משה מתורגמן ליהושע כו'“ — און איז זיך ניט מסתפק מיט „ניטלה רשות מזה ונתנה לזה“ (כפירושו פריער אין פ' וילך) — ווייל אין דעם באַשטייט דער חידוש פון דעם פסוק „הוא והושע בן נון“, אַז יהושע האָט בפועל גערעדט מיט אידן אין דעם זעלבן אופן ווי משה, נשיאות בפועל; יהושע האָט געדערש'נט „באזני העם“ ווי אַ נשיא דרש'נט — מיט אַ מתורגמן24.\nעפ\"ז איז אויך פאַרשטאַנדיק דער חידוש פון דעם פירוש רש\"י לגבי פירושו בפ' פינחס (וואו ער זאָגט „תן לו מתורגמן שידרוש בחייך“):\n„מתורגמן“ פאַר דרשת יהושע פון פ' פינחס איז ניט געווען אַן ענין פון נשיאות25, נאָר — כדי לאפוקי אַז אידן זאָלן ניט זאָגן „לא הי' לו להרים ראש בימי משה“, און דערפאַר איז געווען דער אָנזאָג „תן לו מתורגמן שידרוש בחייך“; משא\"כ בפרשתנו זאָגט עס רש\"י בהמשך לפירושו לפנ\"ז „שבת של דיוזגי היתה נטלה רשות מזה ונתנה לזה“ — והיינו, אַז דאָ איז עס ביי יהושע געווען בתור נשיאות, ביז אין אַן אופן פון „דיוזגי“ — יהושע איז אַ בן זוג פון משה רבינו.\nז. אָבער, רש\"י קען זיך ניט מסתפק זיין מיט זאָגן „שבת של דיוזגי כו' העמיד לו משה מתורגמן כו'“ — ווייל לפ\"ז ווערט נתעורר אַ תמי' גדולה: פאַרוואָס האָט זיך געפאָדערט אַזאַ סדר אַז נשיאותו של יהושע זאָל זיך אָנהויבן נאָך בחיי משה (היפך הכלל „דבר אחד לדור“)?!\nאין הכי נמי, משה האָט געדאַרפט ממנה זיין יהושע'ן אַלס זיין ממלא מקום, אָבער וואָס איז דער הכרח אַז יהושע (תלמידו של משה) זאָל פירן נשיאות בחיי (רבו) משה (און אין אַן אופן פון „דיוזגי“ — ביידע צוזאַמען) — און ניט ווי מען געפינט ביי אַנדערע ממלאי־מקום פון די נשיאים שלפניהם, אַז די נשיאות פון ממלא־מקום (אפילו ווען ער איז דערצו באַשטימט געוואָרן אין פאָראויס) האָט זיך אָנגעהויבן לאחרי פטירת הנשיא שלפניו26?\nאויף דעם איז רש\"י ממשיך „שלא יאמרו ישראל בחיי רבך לא הי' לך",[["24","24","וזהו הפי' של דיוזגי — ב' זוגים, משה ומתורגמנו שלו ויהושע ומתורגמנו שלו. וראה מפרשי רש\"י כאן."],["25","25","וכן בספרי בב' המקומות בפ' פינחס ובוילך, שאין ההדגשה על ענין הנשיאות, אלא ע\"ז שיכול להורות ולדבר (וע\"ד המבואר לגבי אלעזר בספרי מטות כנ\"ל הערה 14). אלא שגם בפ' פינחס שינה רש\"י וכתב „להרים ראש“ ולא כבספרי, כי מכיון שהמדובר שם („וסמכת את ידך עליו“) בא בהמשך לבקשת משה „יפקוד ה' אלקי הרוחות“ — מובן שגם שם, זה שהי' דורש לא הי' כ\"כ מצד עצם ענין הדיבור או הוראה, אלא ענין של הרמת ראש וחשיבות. אלא שאי\"ז דרגת נשיאות על כל ישראל ופשיטא שלא ע\"ד ובשוה למשה רבינו — ובזה הוא החידוש בפרש\"י פרשתנו, כדלקמן בפנים."],["26","26","וכפי' הפשוט ד„ממלא מקום“ וכתוכנו הפשוט — שבא במקום שנתרוקן, לאחרי זה שקדמו. אלקי הרוחות“ וקיומו ציווי ה' שסמך ידיו על יהושע בעין יפה (פינחס כז, טז ואילך ובפרש\"י שם, כג) נעשה ענין של נשיאות ביהושע אלא שהי' טפל למשה (ע\"ד קיסר ופלגי קיסר — סנהדרין צח, סע\"ב), ואח\"כ ביום פטירת משה נתחלפו, שיהושע נעשה העיקר ומשה טפל אליו — „נטלה רשות מזה (היינו עיקר הנשיאות) ונתנה לזה (ליהושע)“ (וראה לקו\"ש חכ\"ד ע' 218 ואילך). — כי לומר שמשה הי' מקבל מיהושע — ה\"ז היפך המפורסם בכ\"מ, אף שמצינו שמשה ביקש להכנס לארץ באופן כזה (ספרי פינחס כז, יב (פיסקא קלה). תנחומא ואתחנן ו. יל\"ש ואתחנן ג, כו. ועוד)."]]],[1300291215,"להרים ראש“: דוקא ביי יהושע'ן האָט זיך געפאָדערט אַ „הרמה“ מיוחדת, מצד דעם וואָס בחיי משה איז זיין גאַנצע הנהגה געווען אין אַ כיוון הפכי — פאַרקערט בתכלית פון רוממות, ביטול ושפלות: כל מהותו איז באַשטאַנען אין דעם וואָס ער איז „משרת משה“, „ומשרתו יהושע גו' נער לא ימיש גו'“27, ער איז כסדר געשטאַנען אין אַ תנועה פון תכלית הביטול — „נער“28 ו„משרת“\n[ניט ווי מ'געפינט לדוגמא ביי אהרן, דאע\"פ וואָס משה איז געווען דער נשיא, האָט אויך אהרן אַליין געלערנט תורה מיט אַלע אידן (ווי רש\"י ברענגט29 אין דעם „סדר משנה“). אָבער ביי יהושע'ן געפינט מען ניט ביז דאַמאָלס קיין ענין של רוממות על כל ישראל30].\nאון דערפאַר האָט מען דאָ במיוחד געדאַרפט באַוואָרענען אַז אידן זאָלן ניט זאָגן „בחיי רבך לא הי' לך להרים ראש“ — היות אַז ביי אים האָט געפעלט לגמרי הרמת ראש (בחיי רבו)31, איז ער דערפאַר ניט מסוגל צו זיין אַ נשיא ישראל. און דעריבער „העמיד לו משה מתורגמן ליהושע שיהא דורש בחייו“.\nח. ע\"פ כ\"ז וועט מען אויך פאַרשטיין דעם המשך אין פרש\"י „ולמה קוראו כאן הושע לומר שלא זחה דעתו עליו כו'“ (און רש\"י איז מדייק צו זאָגן „השפיל עצמו כאשר בתחילתו“, ניט ווי אין ספרי „הוא הושע בצדקו כו'“):\nדי שאלה איז ניט סתם „למה קוראו הושע“ לאחרי ווי מ'האָט אים אַ נאָמען געגעבן „יהושע“ — נאָר „ולמה קוראו כאן הושע“, אין דעם פסוק, דלכאורה, אדרבה — דוקא אין דעם פסוק איז מתאים מ'זאָל אים רופן „יהושע“:\nוויבאַלד דער פסוק קומט מדגיש זיין דעם ענין והכרח פון הרמת ראש (נשיאות) של יהושע שוין בחיי משה — ווי קומט עס אַז דער פסוק קלייבט דאָ אויס דווקא דעם נאָמען „הושע“, וואָס ער האָט געהאַט איידער משה האָט אים אַ נאָמען געגעבן „יהושע“32 (וואָס דערמאָנט אַז יהושע האָט געדאַרפט אָנקומען צו דער תפילה (מיוחדת) און פון משה'ן אַז בעתיד „י־ה יושיעך מעצת מרגלים“<sup data-n=\"33\">33</sup>?\nאויף דעם איז רש\"י מבאר, אַז אדרבה „לומר“ — דאָס קומט לערנען מעלתו של יהושע „שלא זחה דעתו עליו שאע\"פ שנתנה לו גדולה השפיל עצמו כאשר מתחלתו“: טבע האדם איז, אַז בשעת ער",[["27","27","תשא לג, יא (והי' אז בן נו שנה — ראה ראב\"ע ורמב\"ן שם. ועוד). וראה גם משפטים כד, יג. בהעלותך יא, כח (ובפרש\"י בהנ\"ל)."],["28","28","ראה ראב\"ע ורמב\"ן בפי' „נער“ בנוגע ליהושע (אף שהי' בן נו שנה, כנ\"ל) — אבל ראה סיום פי' הרמב\"ן בטעם שנק' בן נון."],["29","29","בס\"פ תשא (לד, לב)."],["30","30","ואע\"פ ד„ויאמר משה אל יהושע בחר לנו אנשים וצא הלחם בעמלק גו'“ (בשלח יג, ט), י\"ל: א) דבפשש\"מ אי\"ז מורה על גדלות בתור מנהיג לכל ישראל כו', כ\"א ע\"ד שר הצבא (ולהעיר מפרש\"י שם). ב) ע\"פ מ\"ש במדרשים (פסיקתא דר\"כ פי' ג. ובכ\"מ) לפי שהי' משבט יוסף, שאין זרעו של עשו נמסר אלא ביד זרעו של יוסף שנאמר (עובדי' א, יח) והי' בית יעקב גו' (ב\"ב קכג, ב), וכהובא בפרש\"י לפנ\"ז (ויצא ל, כה. ר\"פ וישב (רש\"י ישן)). ג) ע\"פ פרש\"י שם, יד: ושים באזני יהושע — המכניס את ישראל לארץ כו', י\"ל שלכן גם עצם המלחמה הי' על ידו — (ראה פרש\"י שם, יג)."],["31","31","ועד שגם „משה אמר ליהושע זקנים שבדור יהיו עמך הכל לפי דעתן ועצתן“, ורק „הקב\"ה אמר ליהושע . . הכל תלוי בך טול מקל והך על קדקדן“ (פרש\"י וילך לא, ז. וראה לקו\"ש חי\"ט ע' 309 ואילך)."],["32","32","שלח יג, ח. שם, טז."],["33","33","פרש\"י שם, טז."]]],[1300291216,"איז עולה לגדולה ענדערן זיך זיינע מדות והנהגות בהתאם צו דעם שינוי וגדולה שלו. ועאכו\"כ בענין נשיאות, אַז ווען איינער ווערט נתמנה אַלס נשיא, רופט עס ביי אים אַרויס אַ תנועה פון גדולה והתנשאות. ניט ח\"ו אַ תנועה פון גאוה34 וישות ח\"ו — נאָר אין קדושה גופא, אַ תנועה35 פון גדולה ורוממות וואָס פאָדערט זיך ע\"פ תורה — כדי דער נשיא זאָל קענען פירן נשיאותו כדבעי. און ווי רש\"י בריינגט בנדו\"ד אַז דער אויבערשטער זאָגט אָן יהושע „טול מקל והך“36.\nאון דאָס דערציילט די תורה, אַז ניט קוקנדיק אויף דעם וואָס מ'האָט געגעבן יהושע'ן גדולה — און ער האָט זיכער באַקומען בסמיכת משה בעין יפה די נויטיקע גדולה והתנשאות וואָס אַ נשיא דאַרף האָבן37 — איז אָבער ביחד עם זה ביי אים געווען די תנועה והנהגה פון „השפיל עצמו כאשר מתחלתו“:\nפונקט ווי איידער מ'האָט אים געגעבן גדולה, איז זיין ענין געווען — „משרת משה“, אַ הנהגה פון שפלות, אַזוי אויך דערנאָך, ווען ניתנה לו גדולה, איז ביי אים געבליבן די זעלבע הנהגה ותנועה פון שפלות עצמו, „השפיל עצמו כאשר מתחלתו“. וי\"ל שזהו שייך גם לזה שרש\"י האָט אַראָפּגעבראַכט פריער38 „פני משה כחמה פני יהושע כלבנה“, אַז ביי אים האָט זיך שטענדיק אָנגעהערט אַז ער איז אַ מקבל (ווי לבנה פון דעם שמש), ובמילא בקטנות ושפלות39 בהתאם לזה.\nט. פון דעם האָט מען אויך אַ הוראה אין עבודת כאו\"א:\nכשם ווי ס'איז געווען ביי יהושע'ן, אַז לאחרי ווי ער האָט זוכה געווען צו גדולה, און ניט צו גדולה סתם, נאָר צו אַ גדולה נעלית כזו אַז ער האָט געהאַט נשיאות שוין בחיי משה און נאָכמער אין אַן אופן פון „דיוזגי“, איז ער פונדעסטוועגן געווען ביי זיך שפל בתכלית „כאשר מתחילתו“,\nעד\"ז איז ביי יעדן אידן (ובפרט אַז משה40 מסרה — ליהושע): בשעת ער איז זוכה צו אַן ענין של גדלות, גדלות אין אַן ענין של שררה, אָדער אַ גדלות בשאר ענינים, וואָס ער איז זוכה צו ברכות נעלות פון אויבערשטן — קען ער דאָך מאַכן אַ חשבון, אַז דערפון גופא וואָס ער האָט זוכה געווען צו די גדלות, איז אַ סימן אַז דוקא ער איז ראוי לזה, ובמילא רופט עס אַרויס ביי אים אַ תנועה פון הרחבת הדעת — טאַקע ניט קיין גאוה ח\"ו, אָבער עכ\"פ אַ תנועה של הרחבה ורוממות,\nלערנט מען פון יהושע'ן אַז אדרבה: דוקא ווען מ'איז זוכה צו אַן ענין של",[["34","34","להעיר שבכמה כת\"י רש\"י (שתח\"י) במקום „זחה“ הלשון „גסה“, ובמקומות הנ\"ל נאמר בלשון הוראה — שלא יהא דעתו גסה כו'."],["35","35","מכיון שרש\"י אינו מפרש פי' תיבת „זחה“ צ\"ל לפי שמובן הוא מעצמו. וע\"ד החידוד אולי י\"ל שהוא ע\"ד הלשון „ולא יזח החושן“ (תצוה כח, כח) שפרש\"י „ל' ניתוק“, וכן פירושו כאן שלא הי' ניתוק והזזה בדעתו למצב של גדלות. וראה ערוך וערוך השלם ערך זח."],["36","36","וילך לא, ז. ראה הערה 31."],["37","37","וראה לעיל הערה 31."],["38","38","פינחס כז, כ."],["39","39","ראה המשך תרס\"ו בהוספות (בהוצאת קה\"ת, תשל\"א ואילך ס\"ע תקנד. ובהוצאת תנש\"א — ס\"ע תקעח). וראה לקו\"ש חי\"ט שם ע' 313 ואילך. וש\"נ."],["40","40","ובכל נפש מבית ישראל יש בה מבחי' מרע\"ה (תניא רפמ\"ב)."]]],[1300291217,"גדולה, דאַרף זיין דער „השפיל עצמו כאשר מתחלתו“41,\nאון דאָס איז אויך די כלי אַז די גדלות וואָס מען גיט — זאָל האָבן אַ קיום.\nי. דער ענין הנ\"ל איז שייך צו דעם זמן אין יאָר ווען מען לייענט די פרשה אין תורה — נאָך (ובסמיכות צו<sup data-n=\"42\">42</sup> ראש השנה:\nדי עבודה פון ראש השנה איז — „אמרו כו' שתמליכוני עליכם“43, אידן זיינען ממליך דעם אויבערשטן אַלס מלך, מלך ישראל און — מלך על כל העולם כולו.\nאון וויבאַלד אַז דער ענין פון מלוכה ווערט אויפגעטאָן דורך עבודת ישראל, ווייזט עס דאָך אויף חשיבות פון אַ אידן, אַז בכחם איז צו ממליך זיין דעם מלך מלכי המלכים הקב\"ה! ובמילא, קען דערפון אַרויסקומען אַ סברא, אַז ער זאָל נתעורר ווערן מיט אַ תנועה פון היפך השפלות לגמרי\n— איז אויף דעם די הוראה, אַז אַדרבה: דוקא לאחרי ווי אידן טוען אויף אַזאַ גרויסן ענין — פון ממליך זיין דעם אויבערשטן אַלס מלך, דאַרף דאָס אַרויסרופן ביי אַ אידן אַ תנועה פון ביטול בתכלית, השפיל עצמו44,\nאון דורך דעם45 איז מען מוסיף נאָכמער אין ברכות ה' בכל המצטרך, אין אַ חתימה און גמר חתימה טובה, לשנה טובה ומתוקה, בטוב הנראה והנגלה, למטה מעשרה טפחים, בבני חיי ומזוני רוויחי, ובכולם רוויחי.\n(משיחות ש\"פ האזינו תשל\"א, תשמ\"ג)",[["41","41","ראה לקו\"ש חכ\"ד ע' 142 ואילך."],["42","42","או עכ\"פ מיד אחרי יוהכ\"פ (הסיום והגמר דר\"ה) ש„נק' ג\"כ ר\"ה בכתוב“ (לקו\"ת ר\"ה נח, א)."],["43","43","ר\"ה טז, סע\"א. לד, ב."],["44","44","עיין אגה\"ק ס\"ב."],["45","45","ראה תו\"א סד\"ה השמים כסאי ובהערות לשם (באוה\"ת וכו')."]]],[1300291218,"<h3>יום הכפורים</h3>\nא. מ'האָט שוין פיל מאָל גערעדט1 וועגן דעם לשון חז\"ל2 „עשרה ימים שבין ראש השנה ליום הכפורים” — אַז אין דעם לשון זיינען לכאורה פאַראַן צוויי הפכים: „שבין3 ר\"ה ליוהכ\"פ” באַווייזט4 אַז ראש השנה און יוהכ\"פ גייען נִיט אַריין אין די ימים5; פון דעם אָבער וואָס די גמרא זאָגט „עשרה ימים שבין כו'” איז מוכח, אַז אויך ר\"ה ויוהכ\"פ גייען אַריין אין דעם חשבון פון די עשרה ימים, וואָרום צווישן ר\"ה און יוהכ\"פ זיינען דאָך בלויז זיבן טעג.\nוי\"ל דעם ביאור אין דעם, אַז אין ר\"ה ויוהכ\"פ זיינען דאָ צוויי ענינים:\nא) זייער עיקר ענין (וואָס דאָס איז נִיט דער ענין התשובה): דער ענין עיקרי פון ראש השנה איז — „תמליכוני עליכם”, קבלת מלכותו ית' „ובמה בשופר”6; און דער ענין עיקרי פון יום הכפורים איז — „עצמו7 של יום הכפורים מכפר”8 (אַ כפרה מצד דעם עצם טאָג, וואָס איז (נאָך) העכער ווי די כפרה שעל ידי תשובה<sup data-n=\"9\">9</sup> — און מצד דעם זיינען זיי העכער פון די „ימים שבין ר\"ה ליוהכ\"פ” (וואָס ענינם איז תשובה);\nב) דערנאָך איז פאַראַן אין זיי אויך דער ענין התשובה — צוליב וועלכן זיי אויך ווערן אַריינגערעכנט אין די (עשרת) ימי תשובה.\n[ביז אַז מען געפינט, אַז די תשובה פון ר\"ה ויוהכ\"פ איז אַן אַנדערער, אַ העכערער אופן אין תשובה, וואָס איז ניט פאַרבונדן (כ\"כ) מיט דער תנועה פון מרירות, נאָר זי איז (בעיקר) אַ תשובה מתוך שמחה10.\nלא מיבעי ראש השנה, ווען מ'טאָר ניט זאָגן קיין וידויים כו'11, נאָר אפילו ביום הכפורים (ווען עס איז דאָ אַ חיוב להתודות<sup data-n=\"12\">12</sup> — פסק'נט דער אַלטער רבי13: „הלובש שק מחמת תשובה צריך לפשטו ביוה\"כ מפני שהוא יו\"ט וצריך לכבדו בכסות נקי'”. ד.ה. אַז די תשובה פון",[["1","1","ראה לקו\"ש ח\"ד ע' 1144. 1150. ועוד."],["2","2","ר\"ה יח, א. יבמות מט, סע\"א. שם קה, סע\"א."],["3","3","בע\"י ר\"ה שם: שמר\"ה עד יוהכ\"פ. אבל בש\"ס לפנינו (במקומות שבהערה הקודמת) וכן בע\"י יבמות שם הוא כבפנים. וכ\"ה בר\"ח ר\"ה שם. ועוד."],["4","4","ראה בנדו\"ז תענית ה, רע\"א. בהנסמן בשד\"ח כללים מע' הבי\"ת כלל עב (ובשו\"ת בית אפרים חאו\"ח סנ\"א שצוין שם — ד„הך דעשרת ימים שבין ר\"ה כו' ודאי דאיכא דלא דייק ונקט כי הך לישנא”)."],["5","5","ולהעיר מטאו\"ח סתר\"ג: אלו הם שבעה ימים שבין ר\"ה ליוהכ\"פ. וראה לקמן הערה 16."],["6","6","ר\"ה טז, סע\"א. שם לד, ב. וראה הנסמן בלקו\"ש ח\"ד ע' 1354. ח\"ט ע' 434. ועוד."],["7","7","כ\"ה ברמב\"ם לפנינו. ובקרית ספר (להמבי\"ט) על הרמב\"ם כאן (ולהלן פ\"ב) „עיצומו”. וראה ס' המדע (ירושלים, תשכ\"ד) בשינויי נוסחאות."],["8","8","רמב\"ם הל' תשובה פ\"א ה\"ג וד'. וראה תוס' שבועות יג, סע\"א: היום עצמו . . מכפר."],["9","9","ראה בארוכה לקו\"ש ח\"ד ע' 1150 ואילך."],["10","10","אף שבכללות — בכל תשובה („לעולם” — כל השנה) צריך לבוא „לידי שמחה אמתית” (תניא פל\"א ואילך. שם ספל\"ד. אגה\"ת ספ\"י וספי\"א). וראה לקמן סעיף ד' והערה 29."],["11","11","שו\"ע אדה\"ז או\"ח סתקפ\"ד ס\"ב."],["12","12","ראה רמב\"ם הל' תשובה פ\"ב ה\"ז וח'. שו\"ע אדה\"ז שם רסתר\"ז (וראה גם טור ושו\"ע שם. טור שם סתר\"כ)."],["13","13","או\"ח סו\"ס תרי (ממג\"א שם סק\"ה בשם ס' חסידים סתרט\"ז)."]]]]});
